// app/api/admin/users/[id]/route.ts
import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth/next';
import { authOptions } from '../../../auth/[...nextauth]/route';
import { getCollection } from '@/lib/db/mongo';
import { ObjectId } from 'mongodb';

interface User {
  _id?: ObjectId;
  email: string;
  name: string;
  role: 'admin' | 'user';
  passwordHash: string;
  createdAt: Date;
  updatedAt: Date;
}

interface UserResponse {
  id: string;
  email: string;
  name: string;
  role: 'admin' | 'user';
  createdAt: Date;
  updatedAt: Date;
  joinDate: string;
  status: string;
  lastLogin: string;
  avatar: string;
}

interface UpdateUserRequest {
  name?: string;
  email?: string;
  role?: 'admin' | 'user';
}

// Helper function to validate ObjectId
function isValidObjectId(id: string): boolean {
  return ObjectId.isValid(id) && id.length === 24;
}

// Helper function to transform user data for response
function transformUserForResponse(user: User): UserResponse {
  return {
    id: user._id?.toString() || '',
    name: user.name,
    email: user.email,
    role: user.role,
    createdAt: user.createdAt,
    updatedAt: user.updatedAt,
    joinDate: user.createdAt.toLocaleDateString('en-US', {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
    }),
    status: 'Active', // Simulated status - could be enhanced with real activity tracking
    lastLogin: 'Recently', // Simulated - could be enhanced with real login tracking
    avatar: user.name
      .split(' ')
      .map(n => n[0])
      .join('')
      .toUpperCase(),
  };
}

// GET /api/admin/users/[id] - Fetch single user by ID
export async function GET(
  request: NextRequest,
  { params }: { params: { id: string } }
): Promise<NextResponse> {
  // Check authentication
  const session = await getServerSession(authOptions);

  if (!session || session.user?.role !== 'admin') {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  try {
    const userId = params.id;

    // Validate ObjectId format
    if (!isValidObjectId(userId)) {
      return NextResponse.json(
        { error: 'Invalid user ID format' },
        { status: 400 }
      );
    }

    const collection = await getCollection<User>('users');

    // Find user by ID
    const user = await collection.findOne({ _id: new ObjectId(userId) });

    if (!user) {
      return NextResponse.json(
        { error: 'User not found' },
        { status: 404 }
      );
    }

    // Transform and return user data (excluding sensitive information)
    const userResponse = transformUserForResponse(user);

    return NextResponse.json({
      success: true,
      user: userResponse,
    });
  } catch (error) {
    console.error('Error fetching user:', error);
    return NextResponse.json(
      { error: 'Failed to fetch user' },
      { status: 500 }
    );
  }
}

// PUT /api/admin/users/[id] - Update single user by ID
export async function PUT(
  request: NextRequest,
  { params }: { params: { id: string } }
): Promise<NextResponse> {
  // Check authentication
  const session = await getServerSession(authOptions);

  if (!session || session.user?.role !== 'admin') {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  try {
    const userId = params.id;

    // Validate ObjectId format
    if (!isValidObjectId(userId)) {
      return NextResponse.json(
        { error: 'Invalid user ID format' },
        { status: 400 }
      );
    }

    const updateData: UpdateUserRequest = await request.json();
    const collection = await getCollection<User>('users');

    // Validate update data
    if (!updateData || Object.keys(updateData).length === 0) {
      return NextResponse.json(
        { error: 'No update data provided' },
        { status: 400 }
      );
    }

    // Check if user exists
    const existingUser = await collection.findOne({ _id: new ObjectId(userId) });
    if (!existingUser) {
      return NextResponse.json(
        { error: 'User not found' },
        { status: 404 }
      );
    }

    // If email is being updated, check for conflicts
    if (updateData.email && updateData.email !== existingUser.email) {
      const emailConflict = await collection.findOne({ 
        email: updateData.email,
        _id: { $ne: new ObjectId(userId) }
      });

      if (emailConflict) {
        return NextResponse.json(
          { error: 'Email address is already in use by another user' },
          { status: 409 }
        );
      }
    }

    // Validate role if provided
    if (updateData.role && !['admin', 'user'].includes(updateData.role)) {
      return NextResponse.json(
        { error: 'Invalid role. Must be either "admin" or "user"' },
        { status: 400 }
      );
    }

    // Prepare update object
    const updateObject: Partial<User> = {
      ...updateData,
      updatedAt: new Date(),
    };

    // Update user
    const result = await collection.updateOne(
      { _id: new ObjectId(userId) },
      { $set: updateObject }
    );

    if (result.matchedCount === 0) {
      return NextResponse.json(
        { error: 'User not found' },
        { status: 404 }
      );
    }

    // Fetch updated user
    const updatedUser = await collection.findOne({ _id: new ObjectId(userId) });

    if (!updatedUser) {
      throw new Error('Failed to fetch updated user');
    }

    const userResponse = transformUserForResponse(updatedUser);

    return NextResponse.json({
      success: true,
      message: 'User updated successfully',
      user: userResponse,
    });
  } catch (error) {
    console.error('Error updating user:', error);
    return NextResponse.json(
      { error: 'Failed to update user' },
      { status: 500 }
    );
  }
}

// DELETE /api/admin/users/[id] - Delete single user by ID
export async function DELETE(
  request: NextRequest,
  { params }: { params: { id: string } }
): Promise<NextResponse> {
  // Check authentication
  const session = await getServerSession(authOptions);

  if (!session || session.user?.role !== 'admin') {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  try {
    const userId = params.id;

    // Validate ObjectId format
    if (!isValidObjectId(userId)) {
      return NextResponse.json(
        { error: 'Invalid user ID format' },
        { status: 400 }
      );
    }

    const collection = await getCollection<User>('users');

    // Check if user exists before deletion
    const existingUser = await collection.findOne({ _id: new ObjectId(userId) });
    if (!existingUser) {
      return NextResponse.json(
        { error: 'User not found' },
        { status: 404 }
      );
    }

    // Prevent deletion of the current admin user
    if (session.user?.id === userId) {
      return NextResponse.json(
        { error: 'Cannot delete your own account' },
        { status: 403 }
      );
    }

    // Check if this is the last admin user
    if (existingUser.role === 'admin') {
      const adminCount = await collection.countDocuments({ role: 'admin' });
      if (adminCount <= 1) {
        return NextResponse.json(
          { error: 'Cannot delete the last admin user' },
          { status: 403 }
        );
      }
    }

    // Delete user
    const result = await collection.deleteOne({ _id: new ObjectId(userId) });

    if (result.deletedCount === 0) {
      return NextResponse.json(
        { error: 'User not found or already deleted' },
        { status: 404 }
      );
    }

    return NextResponse.json({
      success: true,
      message: 'User deleted successfully',
      deletedUserId: userId,
    });
  } catch (error) {
    console.error('Error deleting user:', error);
    return NextResponse.json(
      { error: 'Failed to delete user' },
      { status: 500 }
    );
  }
}

// app/api/admin/users/stats/route.ts
import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth/next';
import { authOptions } from '../../../auth/[...nextauth]/route';
import { getCollection } from '@/lib/db/mongo';
import { ObjectId } from 'mongodb';

// Enhanced TypeScript interfaces for comprehensive statistics
interface User {
  _id?: ObjectId;
  email: string;
  name: string;
  role: 'admin' | 'user';
  createdAt: Date;
  updatedAt: Date;
}

interface RoleDistribution {
  role: string;
  count: number;
  percentage: number;
}

interface ActivityMetrics {
  totalLogins: number;
  activeToday: number;
  activeThisWeek: number;
  activeThisMonth: number;
  averageSessionDuration: number; // in minutes
  lastLoginDistribution: {
    today: number;
    thisWeek: number;
    thisMonth: number;
    older: number;
  };
}

interface GrowthTrend {
  period: string;
  newUsers: number;
  totalUsers: number;
  growthRate: number; // percentage
}

interface UserLifecycle {
  newUsers: number;
  returningUsers: number;
  dormantUsers: number; // no activity in 30 days
  churnRate: number; // percentage
}

interface RealTimeMetrics {
  currentActiveSessions: number;
  usersOnlineNow: number;
  recentSignups24h: number;
  recentActivity: Array<{
    type: 'login' | 'signup' | 'update';
    count: number;
    timestamp: Date;
  }>;
}

interface ComprehensiveStats {
  // Basic counts
  total: number;
  active: number;
  inactive: number;

  // Role breakdown
  roleDistribution: RoleDistribution[];

  // Activity analysis
  activityMetrics: ActivityMetrics;

  // Growth trends
  growthTrends: GrowthTrend[];
  monthlyGrowth: number;
  weeklyGrowth: number;

  // User lifecycle
  userLifecycle: UserLifecycle;

  // Real-time data
  realTimeMetrics: RealTimeMetrics;

  // Additional insights
  insights: {
    averageUsersPerDay: number;
    peakRegistrationDay: string;
    mostActiveRole: string;
    accountAgeDistribution: {
      newAccounts: number; // < 7 days
      recentAccounts: number; // 7-30 days
      establishedAccounts: number; // > 30 days
    };
  };
}

export async function GET(request: NextRequest): Promise<NextResponse> {
  // Authentication check
  const session = await getServerSession(authOptions);
  if (!session || session.user?.role !== 'admin') {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  try {
    const collection = await getCollection<User>('users');
    const now = new Date();

    // Calculate date boundaries
    const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
    const weekAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
    const monthAgo = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);
    const threeMonthsAgo = new Date(now.getTime() - 90 * 24 * 60 * 60 * 1000);

    // Basic user counts
    const [total, adminCount, userCount] = await Promise.all([
      collection.countDocuments(),
      collection.countDocuments({ role: 'admin' }),
      collection.countDocuments({ role: 'user' })
    ]);

    // Role distribution calculation
    const roleDistribution: RoleDistribution[] = [
      {
        role: 'admin',
        count: adminCount,
        percentage: total > 0 ? Math.round((adminCount / total) * 100) : 0
      },
      {
        role: 'user',
        count: userCount,
        percentage: total > 0 ? Math.round((userCount / total) * 100) : 0
      }
    ];

    // Registration trends using aggregation pipeline
    const growthPipeline = [
      {
        $group: {
          _id: {
            year: { $year: '$createdAt' },
            month: { $month: '$createdAt' },
            week: { $week: '$createdAt' }
          },
          count: { $sum: 1 },
          users: { $push: '$$ROOT' }
        }
      },
      {
        $sort: { '_id.year': -1, '_id.month': -1, '_id.week': -1 }
      },
      {
        $limit: 12 // Last 12 periods
      }
    ];

    const growthData = await collection.aggregate(growthPipeline).toArray();

    // Calculate growth trends
    const growthTrends: GrowthTrend[] = growthData.map((period, index) => {
      const previousPeriod = growthData[index + 1];
      const growthRate = previousPeriod 
        ? Math.round(((period.count - previousPeriod.count) / previousPeriod.count) * 100)
        : 0;

      return {
        period: `${period._id.year}-${String(period._id.month).padStart(2, '0')}`,
        newUsers: period.count,
        totalUsers: period.count, // Simplified - in real app would be cumulative
        growthRate
      };
    });

    // Recent signup counts
    const [recentSignups24h, weeklySignups, monthlySignups] = await Promise.all([
      collection.countDocuments({ createdAt: { $gte: today } }),
      collection.countDocuments({ createdAt: { $gte: weekAgo } }),
      collection.countDocuments({ createdAt: { $gte: monthAgo } })
    ]);

    // Calculate growth rates
    const monthlyGrowth = total > 0 ? Math.round((monthlySignups / total) * 100) : 0;
    const weeklyGrowth = total > 0 ? Math.round((weeklySignups / total) * 100) : 0;

    // Account age distribution
    const [newAccounts, recentAccounts] = await Promise.all([
      collection.countDocuments({ createdAt: { $gte: weekAgo } }),
      collection.countDocuments({ 
        createdAt: { 
          $gte: monthAgo, 
          $lt: weekAgo 
        } 
      })
    ]);
    const establishedAccounts = total - newAccounts - recentAccounts;

    // Simulated activity metrics (in real app, would track actual login data)
    const activityMetrics: ActivityMetrics = {
      totalLogins: Math.floor(total * 15.5), // Simulated: avg 15.5 logins per user
      activeToday: Math.floor(total * 0.15), // 15% active today
      activeThisWeek: Math.floor(total * 0.45), // 45% active this week
      activeThisMonth: Math.floor(total * 0.75), // 75% active this month
      averageSessionDuration: 25, // 25 minutes average
      lastLoginDistribution: {
        today: Math.floor(total * 0.15),
        thisWeek: Math.floor(total * 0.30),
        thisMonth: Math.floor(total * 0.35),
        older: Math.floor(total * 0.20)
      }
    };

    // User lifecycle metrics
    const dormantUsers = Math.floor(total * 0.20); // 20% dormant
    const userLifecycle: UserLifecycle = {
      newUsers: newAccounts,
      returningUsers: total - newAccounts - dormantUsers,
      dormantUsers,
      churnRate: total > 0 ? Math.round((dormantUsers / total) * 100) : 0
    };

    // Real-time metrics (simulated)
    const realTimeMetrics: RealTimeMetrics = {
      currentActiveSessions: Math.floor(total * 0.08), // 8% currently active
      usersOnlineNow: Math.floor(total * 0.05), // 5% online now
      recentSignups24h,
      recentActivity: [
        {
          type: 'login',
          count: Math.floor(activityMetrics.activeToday * 2.3),
          timestamp: new Date(now.getTime() - 1000 * 60 * 15) // 15 min ago
        },
        {
          type: 'signup',
          count: recentSignups24h,
          timestamp: new Date(now.getTime() - 1000 * 60 * 60 * 2) // 2 hours ago
        },
        {
          type: 'update',
          count: Math.floor(total * 0.05),
          timestamp: new Date(now.getTime() - 1000 * 60 * 30) // 30 min ago
        }
      ]
    };

    // Find peak registration day
    const peakDay = growthTrends.reduce((peak, current) => 
      current.newUsers > peak.newUsers ? current : peak, 
      growthTrends[0] || { period: 'N/A', newUsers: 0, totalUsers: 0, growthRate: 0 }
    );

    // Additional insights
    const insights = {
      averageUsersPerDay: monthlySignups > 0 ? Math.round(monthlySignups / 30) : 0,
      peakRegistrationDay: peakDay.period,
      mostActiveRole: adminCount > userCount ? 'admin' : 'user',
      accountAgeDistribution: {
        newAccounts,
        recentAccounts,
        establishedAccounts
      }
    };

    // Compile comprehensive response
    const comprehensiveStats: ComprehensiveStats = {
      total,
      active: total - dormantUsers,
      inactive: dormantUsers,
      roleDistribution,
      activityMetrics,
      growthTrends,
      monthlyGrowth,
      weeklyGrowth,
      userLifecycle,
      realTimeMetrics,
      insights
    };

    return NextResponse.json(comprehensiveStats, {
      headers: {
        'Cache-Control': 'no-store, max-age=0', // Ensure fresh data
      },
    });

  } catch (error) {
    console.error('Error fetching comprehensive user stats:', error);
    return NextResponse.json(
      { error: 'Failed to fetch user statistics' },
      { status: 500 }
    );
  }
}

