const { chromium } = require('playwright');
const fs = require('fs');

const hotels = JSON.parse(fs.readFileSync('hotel_statements_formatted.json', 'utf8'));

(async () => {
  const browser = await chromium.launch({ headless: false, slowMo: 100 });
  const context = await browser.newContext({ storageState: 'auth.json' });
  const page = await context.newPage();

  try {
    // STEP 1: Open Loop
    await page.goto('https://loop.microsoft.com');
    await page.waitForSelector('text=Positioning & Benefits', { timeout: 60000 });
    console.log('✅ Loop loaded.');

    // STEP 2: Navigate to Windsurfer - Allora
    await page.click('text=Positioning & Benefits', { timeout: 15000 });
    await page.waitForTimeout(500);
    await page.click('text=Windsurfer - Allora', { timeout: 15000 });
    console.log('📂 Navigated to Windsurfer - Allora.');

    // STEP 3: Process each hotel
    for (let i = 0; i < hotels.length; i++) {
      const hotel = hotels[i];
      const title = hotel.hotel_name;
      const content = `# Positioning Statement
${hotel.positioning_statement}

# Leisure Benefits Statement
${hotel.leisure_benefits_statement}

# Business Benefits Statement
${hotel.business_benefits_statement}`;

      console.log(`\n🏨 Processing hotel ${i + 1}/${hotels.length}: "${title}"`);

      try {
        // Select Template page
        await page.click('text=Template', { timeout: 10000 });
        await page.waitForTimeout(1000);

        // Right-click Template > Duplicate
        await page.locator('text=Template').first().click({ button: 'right' });
        await page.waitForTimeout(500);
        await page.getByText('Duplicate').click();
        console.log(`🌀 Duplicated page for "${title}"`);

        // Wait for duplication to complete
        await page.waitForTimeout(15000);
        await page.waitForLoadState('networkidle');

        // Click on the new duplicated page
        await page.click('text=Template 2', { timeout: 10000 });
        await page.waitForTimeout(3000);

        // Find and interact with the editable area
        console.log('🔍 Looking for editable canvas...');
        const editableSelectors = [
          '[contenteditable="true"]',
          'div[role="textbox"]',
          '.ql-editor',
          '[data-testid*="editor"]',
          '[aria-label*="editor"]',
          '[data-testid="CanvasComponent"]',
          '.canvas-content'
        ];

        let canvas = null;
        for (const selector of editableSelectors) {
          try {
            const elements = await page.locator(selector).all();
            for (const element of elements) {
              if (await element.isVisible()) {
                canvas = element;
                console.log(`📝 Found canvas with selector: ${selector}`);
                break;
              }
            }
            if (canvas) break;
          } catch (e) {
            continue;
          }
        }

        // Fallback: try getting by role
        if (!canvas) {
          try {
            canvas = await page.getByRole('textbox', { name: 'Canvas' });
            if (!(await canvas.isVisible())) {
              canvas = await page.getByRole('textbox').first();
            }
            console.log('📝 Found canvas using role selector');
          } catch (e) {
            console.log('⚠️  Could not find canvas with role selector');
          }
        }

        if (!canvas) {
          throw new Error('Could not find editable canvas');
        }

        // Clear and write content
        console.log('✏️  Clearing existing content...');
        await canvas.click();
        await page.waitForTimeout(1000);

        // Clear existing content with multiple methods
        await page.keyboard.press('Control+A');
        await page.waitForTimeout(500);
        await page.keyboard.press('Delete');
        await page.waitForTimeout(1000);

        // Additional clearing attempt
        await page.keyboard.press('Control+A');
        await page.keyboard.press('Backspace');
        await page.waitForTimeout(1000);

        // Write the content using multiple methods for reliability
        console.log('✍️  Inserting new content...');

        try {
          // Method 1: Try fill first (fastest)
          await canvas.fill(content);
          await page.waitForTimeout(2000);

          // Verify content was inserted
          let currentContent = '';
          try {
            currentContent = await canvas.textContent() || await canvas.innerText() || '';
          } catch (e) {
            currentContent = '';
          }

          // If fill didn't work or content is empty, try typing
          if (!currentContent || currentContent.length < 10) {
            console.log('🔄 Fill method didn\'t work, trying keyboard typing...');
            await canvas.click();
            await page.waitForTimeout(500);
            await page.keyboard.type(content, { delay: 50 });
            await page.waitForTimeout(2000);
          }
        } catch (fillError) {
          console.log('🔄 Fill failed, using keyboard typing...');
          await canvas.click();
          await page.waitForTimeout(500);
          await page.keyboard.type(content, { delay: 50 });
          await page.waitForTimeout(2000);
        }

        // Save the content
        console.log('💾 Saving content...');
        await page.keyboard.press('Control+S');
        await page.waitForTimeout(3000);

        // Verify content was written
        try {
          const finalContent = await canvas.textContent() || await canvas.innerText() || '';
          if (finalContent.includes('Positioning Statement') || finalContent.length > 50) {
            console.log(`✅ Content successfully inserted for "${title}"`);
          } else {
            console.log(`⚠️  Content may not have been inserted properly for "${title}"`);
            console.log(`Content length: ${finalContent.length}`);
          }
        } catch (e) {
          console.log('⚠️  Could not verify content insertion');
        }

        // Rename the page
        console.log('📝 Renaming page...');
        await page.click('text=Template 2', { button: 'right' });
        await page.waitForTimeout(500);
        await page.getByText('Rename and style').click();

        // Fill in rename field and confirm
        const renameInput = '#renameDialog-newName';
        await page.waitForSelector(renameInput, { timeout: 10000 });
        await page.fill(renameInput, title);
        await page.getByTestId('UpdateButtonTestId').click();
        console.log(`📄 Renamed to "${title}"`);

        // Wait before processing next hotel
        await page.waitForTimeout(3000);

      } catch (err) {
        console.error(`❌ Error processing "${title}":`, err.message);

        // Take a screenshot for debugging
        const screenshotName = `error-${title.replace(/[^a-z0-9]/gi, '_')}-${Date.now()}.png`;
        try {
          await page.screenshot({ path: screenshotName });
          console.log(`📸 Screenshot saved: ${screenshotName}`);
        } catch (screenshotErr) {
          console.log('Could not save screenshot');
        }

        // Continue with next hotel instead of stopping
        console.log('⏭️  Continuing with next hotel...');
        continue;
      }
    }

    console.log('✅ All hotels processed successfully!');

  } catch (globalError) {
    console.error('❌ Global error:', globalError.message);

    // Take a final screenshot
    try {
      await page.screenshot({ path: `global-error-${Date.now()}.png` });
    } catch (e) {
      // Ignore screenshot errors
    }
  } finally {
    console.log('🔒 Closing browser...');
    await browser.close();
  }
})();

