input.content:
'use client';

import React, { useState, useEffect } from 'react';
import { useParams, useRouter } from 'next/navigation';
import {
  Card,
  Text,
  Title,
  Stack,
  Group,
  Badge,
  Avatar,
  ActionIcon,
  Button,
  Grid,
  Timeline,
  Table,
  Tabs,
  Alert,
  Loader,
  Center,
  Modal,
  TextInput,
  Select,
  Paper,
  Anchor,
  Divider,
  ThemeIcon,
  Box,
  Skeleton,
  Menu,
  Switch,
  Notification,
} from '@mantine/core';
import {
  IconEdit,
  IconTrash,
  IconMail,
  IconShield,
  IconUser,
  IconClock,
  IconMapPin,
  IconPhone,
  IconLanguage,
  IconKey,
  IconActivity,
  IconSettings,
  IconDownload,
  IconUserX,
  IconAlertTriangle,
  IconCheck,
  IconDots,
  IconChevronRight,
  IconEye,
  IconDevices,
  IconCalendar,
} from '@tabler/icons-react';
import { useForm } from '@mantine/form';
import { notifications } from '@mantine/notifications';

// Types and Interfaces
interface UserProfile {
  id: string;
  name: string;
  email: string;
  role: 'admin' | 'user';
  status: 'active' | 'inactive' | 'suspended';
  avatar?: string;
  createdAt: string;
  updatedAt: string;
  lastLogin?: string;
  loginCount: number;
  phone?: string;
  location?: string;
  language: string;
  passwordLastChanged?: string;
  twoFactorEnabled: boolean;
  accountSource: string;
  createdBy?: string;
  lastModifiedBy?: string;
}

interface ActivityLog {
  id: string;
  action: string;
  timestamp: string;
  details: string;
  ipAddress?: string;
  userAgent?: string;
}

interface UserStats {
  totalLogins: number;
  averageSessionDuration: string;
  lastLoginLocation: string;
  deviceTypes: string[];
  daysSinceLastActivity: number;
  sessionFrequency: string;
  peakActivityHours: string;
}

// Utility Functions
const formatDate = (dateString: string): string => {
  return new Date(dateString).toLocaleDateString('en-US', {
    year: 'numeric',
    month: 'long',
    day: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
  });
};

const getRelativeTime = (dateString: string): string => {
  const now = new Date();
  const date = new Date(dateString);
  const diffMs = now.getTime() - date.getTime();
  const diffDays = Math.floor(diffMs / (1000 * 60 * 60 * 24));

  if (diffDays === 0) return 'Today';
  if (diffDays === 1) return 'Yesterday';
  if (diffDays < 7) return `${diffDays} days ago`;
  if (diffDays < 30) return `${Math.floor(diffDays / 7)} weeks ago`;
  return `${Math.floor(diffDays / 30)} months ago`;
};

const getRoleBadgeColor = (role: string): string => {
  switch (role) {
    case 'admin': return 'red';
    case 'user': return 'blue';
    default: return 'gray';
  }
};

const getStatusBadgeColor = (status: string): string => {
  switch (status) {
    case 'active': return 'green';
    case 'inactive': return 'gray';
    case 'suspended': return 'red';
    default: return 'gray';
  }
};

export default function UserProfilePage() {
  const params = useParams();
  const router = useRouter();
  const userId = params.id as string;

  // State Management
  const [user, setUser] = useState<UserProfile | null>(null);
  const [activityLogs, setActivityLogs] = useState<ActivityLog[]>([]);
  const [userStats, setUserStats] = useState<UserStats | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [editMode, setEditMode] = useState<string | null>(null);
  const [deleteModalOpen, setDeleteModalOpen] = useState(false);
  const [roleChangeModalOpen, setRoleChangeModalOpen] = useState(false);

  // Form handling
  const editForm = useForm({
    initialValues: {
      name: '',
      email: '',
      phone: '',
      location: '',
      language: 'en',
    },
  });

  const roleForm = useForm({
    initialValues: {
      role: 'user' as 'admin' | 'user',
    },
  });

  // Data Fetching
  const fetchUserData = async () => {
    try {
      setLoading(true);
      const response = await fetch(`/api/admin/users/${userId}`);

      if (!response.ok) {
        throw new Error(`Failed to fetch user: ${response.status}`);
      }

      const userData = await response.json();
      setUser(userData);

      // Set form values
      editForm.setValues({
        name: userData.name || '',
        email: userData.email || '',
        phone: userData.phone || '',
        location: userData.location || '',
        language: userData.language || 'en',
      });

      roleForm.setValues({
        role: userData.role || 'user',
      });

      // Fetch activity logs (simulated data for now)
      setActivityLogs(generateMockActivityLogs());

      // Fetch user stats (simulated data for now)
      setUserStats(generateMockUserStats());

      setError(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to load user data');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    if (userId) {
      fetchUserData();
    }
  }, [userId]);

  // Mock Data Generators (replace with real API calls)
  const generateMockActivityLogs = (): ActivityLog[] => [
    { id: '1', action: 'Login', timestamp: new Date().toISOString(), details: 'Successful login from Chrome', ipAddress: '192.168.1.1' },
    { id: '2', action: 'Profile Update', timestamp: new Date(Date.now() - 86400000).toISOString(), details: 'Updated phone number' },
    { id: '3', action: 'Password Change', timestamp: new Date(Date.now() - 172800000).toISOString(), details: 'Password changed successfully' },
    { id: '4', action: 'Login', timestamp: new Date(Date.now() - 259200000).toISOString(), details: 'Login from Safari' },
    { id: '5', action: 'Role Change', timestamp: new Date(Date.now() - 345600000).toISOString(), details: 'Role changed from user to admin' },
  ];

  const generateMockUserStats = (): UserStats => ({
    totalLogins: 127,
    averageSessionDuration: '45 minutes',
    lastLoginLocation: 'New York, NY',
    deviceTypes: ['Desktop', 'Mobile', 'Tablet'],
    daysSinceLastActivity: 2,
    sessionFrequency: '3.2 times per week',
    peakActivityHours: '9:00 AM - 11:00 AM',
  });

  // Action Handlers
  const handleSaveEdit = async (field: string, value: string) => {
    try {
      const response = await fetch(`/api/admin/users/${userId}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ [field]: value }),
      });

      if (response.ok) {
        setUser(prev => prev ? { ...prev, [field]: value } : null);
        setEditMode(null);
        notifications.show({
          title: 'Success',
          message: 'User updated successfully',
          color: 'green',
          icon: <IconCheck size={16} />,
        });
      }
    } catch (error) {
      notifications.show({
        title: 'Error',
        message: 'Failed to update user',
        color: 'red',
      });
    }
  };

  const handleRoleChange = async (newRole: 'admin' | 'user') => {
    try {
      const response = await fetch(`/api/admin/users/${userId}`, {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ role: newRole }),
      });

      if (response.ok) {
        setUser(prev => prev ? { ...prev, role: newRole } : null);
        setRoleChangeModalOpen(false);
        notifications.show({
          title: 'Success',
          message: 'User role updated successfully',
          color: 'green',
          icon: <IconCheck size={16} />,
        });
      }
    } catch (error) {
      notifications.show({
        title: 'Error',
        message: 'Failed to update user role',
        color: 'red',
      });
    }
  };

  const handleDeleteUser = async () => {
    try {
      const response = await fetch(`/api/admin/users/${userId}`, {
        method: 'DELETE',
      });

      if (response.ok) {
        setDeleteModalOpen(false);
        notifications.show({
          title: 'Success',
          message: 'User deleted successfully',
          color: 'green',
          icon: <IconCheck size={16} />,
        });
        router.push('/admin/dashboard/users');
      }
    } catch (error) {
      notifications.show({
        title: 'Error',
        message: 'Failed to delete user',
        color: 'red',
      });
    }
  };

  const handleSendEmail = (type: 'welcome' | 'reset') => {
    // Simulate email sending
    notifications.show({
      title: 'Email Sent',
      message: `${type === 'welcome' ? 'Welcome' : 'Password reset'} email sent successfully`,
      color: 'blue',
      icon: <IconMail size={16} />,
    });
  };

  const handleExportData = () => {
    if (user) {
      const dataStr = JSON.stringify(user, null, 2);
      const dataUri = 'data:application/json;charset=utf-8,'+ encodeURIComponent(dataStr);
      const exportFileDefaultName = `user-${user.id}-data.json`;

      const linkElement = document.createElement('a');
      linkElement.setAttribute('href', dataUri);
      linkElement.setAttribute('download', exportFileDefaultName);
      linkElement.click();
    }
  };

  // Loading State
  if (loading) {
    return (
      <Stack gap="lg" p="md">
        <Group justify="space-between">
          <Skeleton height={40} width={300} />
          <Group gap="sm">
            <Skeleton height={36} width={80} />
            <Skeleton height={36} width={80} />
            <Skeleton height={36} width={100} />
          </Group>
        </Group>
        <Grid>
          <Grid.Col span={{ base: 12, md: 4 }}>
            <Skeleton height={400} />
          </Grid.Col>
          <Grid.Col span={{ base: 12, md: 4 }}>
            <Skeleton height={400} />
          </Grid.Col>
          <Grid.Col span={{ base: 12, md: 4 }}>
            <Skeleton height={400} />
          </Grid.Col>
        </Grid>
      </Stack>
    );
  }

  // Error State
  if (error || !user) {
    return (
      <Center h={400}>
        <Stack align="center" gap="md">
          <IconAlertTriangle size={48} color="red" />
          <Text size="lg">Failed to load user profile</Text>
          <Text c="dimmed">{error || 'User not found'}</Text>
          <Button onClick={() => router.push('/admin/dashboard/users')}>
            Back to Users
          </Button>
        </Stack>
      </Center>
    );
  }

  return (
    <Stack gap="lg" p="md">
      {/* Header Section */}
      <Paper withBorder p="lg" radius="md">
        <Group justify="space-between" align="flex-start">
          <Group align="flex-start" gap="lg">
            <Avatar size={120} radius="md" color="blue">
              {user.name.split(' ').map(n => n[0]).join('').toUpperCase()}
            </Avatar>

            <Stack gap="xs">
              <Group align="center" gap="sm">
                <Title order={2}>{user.name}</Title>
                <Badge color={getRoleBadgeColor(user.role)} variant="filled" size="sm">
                  {user.role.toUpperCase()}
                </Badge>
                <Badge color={getStatusBadgeColor(user.status)} variant="dot" size="sm">
                  {user.status.charAt(0).toUpperCase() + user.status.slice(1)}
                </Badge>
              </Group>

              <Anchor href={`mailto:${user.email}`} c="dimmed">
                {user.email}
              </Anchor>

              <Text size="sm" c="dimmed">
                <IconClock size={14} style={{ marginRight: 4 }} />
                Last seen: {user.lastLogin ? getRelativeTime(user.lastLogin) : 'Never'}
              </Text>

              <Text size="sm" c="dimmed">
                User ID: {user.id} • Joined {formatDate(user.createdAt)}
              </Text>
            </Stack>
          </Group>

          <Group gap="sm">
            <Button variant="light" leftSection={<IconEdit size={16} />}>
              Edit
            </Button>
            <Button variant="light" leftSection={<IconMail size={16} />} onClick={() => handleSendEmail('reset')}>
              Send Email
            </Button>
            <Menu shadow="md" width={200}>
              <Menu.Target>
                <ActionIcon variant="light" size="lg">
                  <IconDots size={16} />
                </ActionIcon>
              </Menu.Target>
              <Menu.Dropdown>
                <Menu.Item leftSection={<IconShield size={14} />} onClick={() => setRoleChangeModalOpen(true)}>
                  Change Role
                </Menu.Item>
                <Menu.Item leftSection={<IconDownload size={14} />} onClick={handleExportData}>
                  Export Data
                </Menu.Item>
                <Menu.Divider />
                <Menu.Item leftSection={<IconTrash size={14} />} color="red" onClick={() => setDeleteModalOpen(true)}>
                  Delete User
                </Menu.Item>
              </Menu.Dropdown>
            </Menu>
          </Group>
        </Group>
      </Paper>

      {/* Main Content Grid */}
      <Grid>
        {/* Column 1: User Information */}
        <Grid.Col span={{ base: 12, md: 4 }}>
          <Stack gap="md">
            {/* Personal Details */}
            <Card withBorder padding="lg" radius="md">
              <Title order={4} mb="md">Personal Information</Title>
              <Stack gap="sm">
                <Group justify="space-between">
                  <Text size="sm" fw={500}>Full Name</Text>
                  {editMode === 'name' ? (
                    <Group gap="xs">
                      <TextInput
                        size="xs"
                        value={editForm.values.name}
                        onChange={(e) => editForm.setFieldValue('name', e.target.value)}
                      />
                      <ActionIcon size="sm" onClick={() => handleSaveEdit('name', editForm.values.name)}>
                        <IconCheck size={12} />
                      </ActionIcon>
                    </Group>
                  ) : (
                    <Group gap="xs">
                      <Text size="sm">{user.name}</Text>
                      <ActionIcon size="sm" variant="subtle" onClick={() => setEditMode('name')}>
                        <IconEdit size={12} />
                      </ActionIcon>
                    </Group>
                  )}
                </Group>

                <Group justify="space-between">
                  <Text size="sm" fw={500}>Email</Text>
                  <Text size="sm">{user.email}</Text>
                </Group>

                <Group justify="space-between">
                  <Text size="sm" fw={500}>Phone</Text>
                  {editMode === 'phone' ? (
                    <Group gap="xs">
                      <TextInput
                        size="xs"
                        value={editForm.values.phone}
                        onChange={(e) => editForm.setFieldValue('phone', e.target.value)}
                      />
                      <ActionIcon size="sm" onClick={() => handleSaveEdit('phone', editForm.values.phone)}>
                        <IconCheck size={12} />
                      </ActionIcon>
                    </Group>
                  ) : (
                    <Group gap="xs">
                      <Text size="sm">{user.phone || 'Not provided'}</Text>
                      <ActionIcon size="sm" variant="subtle" onClick={() => setEditMode('phone')}>
                        <IconEdit size={12} />
                      </ActionIcon>
                    </Group>
                  )}
                </Group>

                <Group justify="space-between">
                  <Text size="sm" fw={500}>Location</Text>
                  <Text size="sm">{user.location || 'Not provided'}</Text>
                </Group>

                <Group justify="space-between">
                  <Text size="sm" fw={500}>Language</Text>
                  <Text size="sm">{user.language}</Text>
                </Group>
              </Stack>
            </Card>

            {/* Account Security */}
            <Card withBorder padding="lg" radius="md">
              <Title order={4} mb="md">Account Security</Title>
              <Stack gap="sm">
                <Group justify="space-between">
                  <Text size="sm" fw={500}>Password Changed</Text>
                  <Text size="sm">{user.passwordLastChanged ? getRelativeTime(user.passwordLastChanged) : 'Never'}</Text>
                </Group>

                <Group justify="space-between">
                  <Text size="sm" fw={500}>Two-Factor Auth</Text>
                  <Badge color={user.twoFactorEnabled ? 'green' : 'red'} variant="light" size="sm">
                    {user.twoFactorEnabled ? 'Enabled' : 'Disabled'}
                  </Badge>
                </Group>

                <Group justify="space-between">
                  <Text size="sm" fw={500}>Account Source</Text>
                  <Text size="sm">{user.accountSource}</Text>
                </Group>
              </Stack>
            </Card>
          </Stack>
        </Grid.Col>

        {/* Column 2: Activity & Statistics */}
        <Grid.Col span={{ base: 12, md: 4 }}>
          <Stack gap="md">
            {/* Activity Timeline */}
            <Card withBorder padding="lg" radius="md">
              <Title order={4} mb="md">Recent Activity</Title>
              <Timeline bulletSize={24} lineWidth={2}>
                {activityLogs.slice(0, 5).map((log) => (
                  <Timeline.Item
                    key={log.id}
                    bullet={<IconActivity size={12} />}
                    title={log.action}
                  >
                    <Text size="xs" c="dimmed">{log.details}</Text>
                    <Text size="xs" c="dimmed">{getRelativeTime(log.timestamp)}</Text>
                  </Timeline.Item>
                ))}
              </Timeline>
            </Card>

            {/* Usage Statistics */}
            {userStats && (
              <Card withBorder padding="lg" radius="md">
                <Title order={4} mb="md">Usage Statistics</Title>
                <Stack gap="sm">
                  <Group justify="space-between">
                    <Text size="sm" fw={500}>Total Logins</Text>
                    <Text size="sm">{userStats.totalLogins}</Text>
                  </Group>

                  <Group justify="space-between">
                    <Text size="sm" fw={500}>Avg Session</Text>
                    <Text size="sm">{userStats.averageSessionDuration}</Text>
                  </Group>

                  <Group justify="space-between">
                    <Text size="sm" fw={500}>Last Location</Text>
                    <Text size="sm">{userStats.lastLoginLocation}</Text>
                  </Group>

                  <Group justify="space-between">
                    <Text size="sm" fw={500}>Device Types</Text>
                    <Text size="sm">{userStats.deviceTypes.join(', ')}</Text>
                  </Group>

                  <Group justify="space-between">
                    <Text size="sm" fw={500}>Peak Hours</Text>
                    <Text size="sm">{userStats.peakActivityHours}</Text>
                  </Group>
                </Stack>
              </Card>
            )}
          </Stack>
        </Grid.Col>

        {/* Column 3: Administrative Controls */}
        <Grid.Col span={{ base: 12, md: 4 }}>
          <Stack gap="md">
            {/* Role Management */}
            <Card withBorder padding="lg" radius="md">
              <Title order={4} mb="md">Role Management</Title>
              <Stack gap="sm">
                <Group justify="space-between">
                  <Text size="sm" fw={500}>Current Role</Text>
                  <Badge color={getRoleBadgeColor(user.role)} variant="filled" size="sm">
                    {user.role.toUpperCase()}
                  </Badge>
                </Group>

                <Button variant="light" fullWidth onClick={() => setRoleChangeModalOpen(true)}>
                  Change Role
                </Button>

                <Text size="xs" c="dimmed">
                  Role changes are logged and require admin confirmation
                </Text>
              </Stack>
            </Card>

            {/* Account Actions */}
            <Card withBorder padding="lg" radius="md">
              <Title order={4} mb="md">Account Actions</Title>
              <Stack gap="sm">
                <Button variant="light" fullWidth leftSection={<IconMail size={16} />} onClick={() => handleSendEmail('welcome')}>
                  Send Welcome Email
                </Button>

                <Button variant="light" fullWidth leftSection={<IconKey size={16} />} onClick={() => handleSendEmail('reset')}>
                  Send Password Reset
                </Button>

                <Button variant="light" fullWidth leftSection={<IconUserX size={16} />}>
                  Force Logout All Devices
                </Button>

                <Button variant="light" fullWidth leftSection={<IconDownload size={16} />} onClick={handleExportData}>
                  Export User Data
                </Button>
              </Stack>
            </Card>

            {/* Danger Zone */}
            <Card withBorder padding="lg" radius="md" style={{ borderColor: 'var(--mantine-color-red-3)' }}>
              <Title order={4} mb="md" c="red">Danger Zone</Title>
              <Stack gap="sm">
                <Button color="red" variant="light" fullWidth onClick={() => setDeleteModalOpen(true)}>
                  Delete Account
                </Button>
                <Text size="xs" c="dimmed">
                  This action cannot be undone and will permanently delete all user data
                </Text>
              </Stack>
            </Card>
          </Stack>
        </Grid.Col>
      </Grid>

      {/* Modals */}
      <Modal
        opened={deleteModalOpen}
        onClose={() => setDeleteModalOpen(false)}
        title="Delete User Account"
        centered
      >
        <Stack>
          <Alert color="red" icon={<IconAlertTriangle size={16} />}>
            This action cannot be undone. The user account and all associated data will be permanently deleted.
          </Alert>

          <Text>Are you sure you want to delete <strong>{user.name}</strong>?</Text>

          <Group justify="flex-end" gap="sm">
            <Button variant="default" onClick={() => setDeleteModalOpen(false)}>
              Cancel
            </Button>
            <Button color="red" onClick={handleDeleteUser}>
              Delete Account
            </Button>
          </Group>
        </Stack>
      </Modal>

      <Modal
        opened={roleChangeModalOpen}
        onClose={() => setRoleChangeModalOpen(false)}
        title="Change User Role"
        centered
      >
        <Stack>
          <Text>Change role for <strong>{user.name}</strong></Text>

          <Select
            label="New Role"
            data={[
              { value: 'user', label: 'User' },
              { value: 'admin', label: 'Administrator' },
            ]}
            value={roleForm.values.role}
            onChange={(value) => roleForm.setFieldValue('role', value as 'admin' | 'user')}
          />

          <Group justify="flex-end" gap="sm">
            <Button variant="default" onClick={() => setRoleChangeModalOpen(false)}>
              Cancel
            </Button>
            <Button onClick={() => handleRoleChange(roleForm.values.role)}>
              Change Role
            </Button>
          </Group>
        </Stack>
      </Modal>
    </Stack>
  );
}

// components/admin/UserManagementModals.tsx
'use client';

import React, { useState, useEffect } from 'react';
import {
  Modal,
  TextInput,
  Select,
  Button,
  Stack,
  Group,
  Alert,
  PasswordInput,
  Text,
  Divider,
} from '@mantine/core';
import { useForm } from '@mantine/form';
import { IconAlertCircle, IconCheck } from '@tabler/icons-react';
import { z } from 'zod';
import crypto from 'crypto-js';

// Validation schemas
const createUserSchema = z.object({
  name: z.string().min(2, 'Name must be at least 2 characters'),
  email: z.string().email('Invalid email address'),
  password: z.string().min(8, 'Password must be at least 8 characters'),
  confirmPassword: z.string(),
  role: z.enum(['admin', 'user'], { required_error: 'Role is required' }),
}).refine((data) => data.password === data.confirmPassword, {
  message: "Passwords don't match",
  path: ["confirmPassword"],
});

const editUserSchema = z.object({
  name: z.string().min(2, 'Name must be at least 2 characters'),
  email: z.string().email('Invalid email address'),
  role: z.enum(['admin', 'user'], { required_error: 'Role is required' }),
  changePassword: z.boolean().optional(),
  newPassword: z.string().optional(),
  confirmNewPassword: z.string().optional(),
}).refine((data) => {
  if (data.changePassword) {
    return data.newPassword && data.newPassword.length >= 8;
  }
  return true;
}, {
  message: "New password must be at least 8 characters",
  path: ["newPassword"],
}).refine((data) => {
  if (data.changePassword) {
    return data.newPassword === data.confirmNewPassword;
  }
  return true;
}, {
  message: "Passwords don't match",
  path: ["confirmNewPassword"],
});

type CreateUserForm = z.infer<typeof createUserSchema>;
type EditUserForm = z.infer<typeof editUserSchema>;

interface User {
  id: string;
  name: string;
  email: string;
  role: string;
  status: string;
  joinDate: string;
}

interface UserManagementModalsProps {
  addModalOpened: boolean;
  editModalOpened: boolean;
  selectedUser: User | null;
  onAddModalClose: () => void;
  onEditModalClose: () => void;
  onUserCreated: () => void;
  onUserUpdated: () => void;
}

// Hash password function (client-side hashing before sending to server)
const hashPassword = (password: string): string => {
  const salt = crypto.lib.WordArray.random(128/8);
  const key = crypto.PBKDF2(password, salt, {
    keySize: 512/32,
    iterations: 100000
  });
  return salt.toString() + ':' + key.toString();
};

export function UserManagementModals({
  addModalOpened,
  editModalOpened,
  selectedUser,
  onAddModalClose,
  onEditModalClose,
  onUserCreated,
  onUserUpdated,
}: UserManagementModalsProps) {
  const [createLoading, setCreateLoading] = useState(false);
  const [editLoading, setEditLoading] = useState(false);
  const [createError, setCreateError] = useState<string | null>(null);
  const [editError, setEditError] = useState<string | null>(null);

  // Create user form
  const createForm = useForm<CreateUserForm>({
    initialValues: {
      name: '',
      email: '',
      password: '',
      confirmPassword: '',
      role: 'user',
    },
    validate: {
      name: (value) => value.length < 2 ? 'Name must be at least 2 characters' : null,
      email: (value) => /^\S+@\S+$/.test(value) ? null : 'Invalid email',
      password: (value) => value.length < 8 ? 'Password must be at least 8 characters' : null,
      confirmPassword: (value, values) => 
        value !== values.password ? "Passwords don't match" : null,
    },
  });

  // Edit user form
  const editForm = useForm<EditUserForm>({
    initialValues: {
      name: '',
      email: '',
      role: 'user',
      changePassword: false,
      newPassword: '',
      confirmNewPassword: '',
    },
    validate: {
      name: (value) => value.length < 2 ? 'Name must be at least 2 characters' : null,
      email: (value) => /^\S+@\S+$/.test(value) ? null : 'Invalid email',
      newPassword: (value, values) => {
        if (values.changePassword && (!value || value.length < 8)) {
          return 'Password must be at least 8 characters';
        }
        return null;
      },
      confirmNewPassword: (value, values) => {
        if (values.changePassword && value !== values.newPassword) {
          return "Passwords don't match";
        }
        return null;
      },
    },
  });

  // Update edit form when selected user changes
  useEffect(() => {
    if (selectedUser && editModalOpened) {
      editForm.setValues({
        name: selectedUser.name,
        email: selectedUser.email,
        role: selectedUser.role as 'admin' | 'user',
        changePassword: false,
        newPassword: '',
        confirmNewPassword: '',
      });
      setEditError(null);
    }
  }, [selectedUser, editModalOpened]);

  // Reset create form when modal opens
  useEffect(() => {
    if (addModalOpened) {
      createForm.reset();
      setCreateError(null);
    }
  }, [addModalOpened]);

  // Handle create user
  const handleCreateUser = async (values: CreateUserForm) => {
    setCreateLoading(true);
    setCreateError(null);

    try {
      const response = await fetch('/api/admin/users', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          name: values.name,
          email: values.email,
          passwordHash: hashPassword(values.password),
          role: values.role,
        }),
      });

      if (!response.ok) {
        const error = await response.json();
        throw new Error(error.error || 'Failed to create user');
      }

      onUserCreated();
      onAddModalClose();
      createForm.reset();
    } catch (error) {
      setCreateError(error instanceof Error ? error.message : 'Failed to create user');
    } finally {
      setCreateLoading(false);
    }
  };

  // Handle update user
  const handleUpdateUser = async (values: EditUserForm) => {
    if (!selectedUser) return;

    setEditLoading(true);
    setEditError(null);

    try {
      const updateData: any = {
        userId: selectedUser.id,
        name: values.name,
        email: values.email,
        role: values.role,
      };

      if (values.changePassword && values.newPassword) {
        updateData.passwordHash = hashPassword(values.newPassword);
      }

      const response = await fetch('/api/admin/users', {
        method: 'PUT',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(updateData),
      });

      if (!response.ok) {
        const error = await response.json();
        throw new Error(error.error || 'Failed to update user');
      }

      onUserUpdated();
      onEditModalClose();
    } catch (error) {
      setEditError(error instanceof Error ? error.message : 'Failed to update user');
    } finally {
      setEditLoading(false);
    }
  };

  return (
    <>
      {/* Add User Modal */}
      <Modal
        opened={addModalOpened}
        onClose={onAddModalClose}
        title="Add New User"
        size="md"
        centered
      >
        <form onSubmit={createForm.onSubmit(handleCreateUser)}>
          <Stack gap="md">
            {createError && (
              <Alert
                icon={<IconAlertCircle size={16} />}
                color="red"
                variant="light"
              >
                {createError}
              </Alert>
            )}

            <TextInput
              label="Full Name"
              placeholder="Enter user's full name"
              required
              {...createForm.getInputProps('name')}
            />

            <TextInput
              label="Email Address"
              placeholder="Enter email address"
              required
              {...createForm.getInputProps('email')}
            />

            <Select
              label="Role"
              placeholder="Select user role"
              required
              data={[
                { value: 'user', label: 'User' },
                { value: 'admin', label: 'Admin' },
              ]}
              {...createForm.getInputProps('role')}
            />

            <Divider label="Password Setup" labelPosition="center" />

            <PasswordInput
              label="Password"
              placeholder="Enter password"
              required
              {...createForm.getInputProps('password')}
            />

            <PasswordInput
              label="Confirm Password"
              placeholder="Confirm password"
              required
              {...createForm.getInputProps('confirmPassword')}
            />

            <Group justify="flex-end" mt="md">
              <Button
                variant="outline"
                onClick={onAddModalClose}
                disabled={createLoading}
              >
                Cancel
              </Button>
              <Button
                type="submit"
                loading={createLoading}
                leftSection={<IconCheck size={16} />}
              >
                Create User
              </Button>
            </Group>
          </Stack>
        </form>
      </Modal>

      {/* Edit User Modal */}
      <Modal
        opened={editModalOpened}
        onClose={onEditModalClose}
        title={`Edit User: ${selectedUser?.name || ''}`}
        size="md"
        centered
      >
        <form onSubmit={editForm.onSubmit(handleUpdateUser)}>
          <Stack gap="md">
            {editError && (
              <Alert
                icon={<IconAlertCircle size={16} />}
                color="red"
                variant="light"
              >
                {editError}
              </Alert>
            )}

            <TextInput
              label="Full Name"
              placeholder="Enter user's full name"
              required
              {...editForm.getInputProps('name')}
            />

            <TextInput
              label="Email Address"
              placeholder="Enter email address"
              required
              {...editForm.getInputProps('email')}
            />

            <Select
              label="Role"
              placeholder="Select user role"
              required
              data={[
                { value: 'user', label: 'User' },
                { value: 'admin', label: 'Admin' },
              ]}
              {...editForm.getInputProps('role')}
            />

            <Divider />

            <Group>
              <Text size="sm" fw={500}>Change Password</Text>
              <Button
                size="xs"
                variant={editForm.values.changePassword ? "filled" : "outline"}
                onClick={() => {
                  const newValue = !editForm.values.changePassword;
                  editForm.setFieldValue('changePassword', newValue);
                  if (!newValue) {
                    editForm.setFieldValue('newPassword', '');
                    editForm.setFieldValue('confirmNewPassword', '');
                  }
                }}
              >
                {editForm.values.changePassword ? 'Cancel' : 'Change Password'}
              </Button>
            </Group>

            {editForm.values.changePassword && (
              <>
                <PasswordInput
                  label="New Password"
                  placeholder="Enter new password"
                  required
                  {...editForm.getInputProps('newPassword')}
                />

                <PasswordInput
                  label="Confirm New Password"
                  placeholder="Confirm new password"
                  required
                  {...editForm.getInputProps('confirmNewPassword')}
                />
              </>
            )}

            <Group justify="flex-end" mt="md">
              <Button
                variant="outline"
                onClick={onEditModalClose}
                disabled={editLoading}
              >
                Cancel
              </Button>
              <Button
                type="submit"
                loading={editLoading}
                leftSection={<IconCheck size={16} />}
              >
                Update User
              </Button>
            </Group>
          </Stack>
        </form>
      </Modal>
    </>
  );
}

// app/(admin)/admin/dashboard/users/page.tsx
'use client';

import React, { useState, useEffect } from 'react';
import {
  Card,
  Text,
  Title,
  Stack,
  Group,
  Badge,
  Avatar,
  ActionIcon,
  TextInput,
  Select,
  Button,
  Table,
  Pagination,
  Menu,
  ThemeIcon,
  SimpleGrid,
  Alert,
  Loader,
  Center,
  Modal,
} from '@mantine/core';
import {
  IconSearch,
  IconPlus,
  IconDots,
  IconEdit,
  IconTrash,
  IconMail,
  IconUsers,
  IconUserCheck,
  IconUserX,
  IconCrown,
  IconAlertCircle,
  IconCheck,
  IconX,
} from '@tabler/icons-react';
import { UserManagementModals } from '@/components/admin/UserManagementModals';

// Types for user data
interface User {
  id: string;
  name: string;
  email: string;
  role: string;
  status: string;
  lastLogin: string;
  avatar: string;
  joinDate: string;
}

interface UserStats {
  total: number;
  active: number;
  admins: number;
  recentSignups: number;
}

interface UsersResponse {
  users: User[];
  pagination: {
    page: number;
    limit: number;
    total: number;
    pages: number;
    hasNext: boolean;
    hasPrev: boolean;
  };
}

export default function Users() {
  // State management
  const [users, setUsers] = useState<User[]>([]);
  const [userStats, setUserStats] = useState<UserStats | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [roleFilter, setRoleFilter] = useState<string | null>(null);
  const [statusFilter, setStatusFilter] = useState<string | null>(null);
  const [currentPage, setCurrentPage] = useState(1);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [pagination, setPagination] = useState({
    page: 1,
    limit: 10,
    total: 0,
    pages: 0,
    hasNext: false,
    hasPrev: false,
  });

  // Modal states
  const [addModalOpened, setAddModalOpened] = useState(false);
  const [editModalOpened, setEditModalOpened] = useState(false);
  const [deleteModalOpened, setDeleteModalOpened] = useState(false);
  const [emailModalOpened, setEmailModalOpened] = useState(false);
  const [selectedUser, setSelectedUser] = useState<User | null>(null);
  const [deleteLoading, setDeleteLoading] = useState(false);

  // Fetch users from API
  const fetchUsers = async () => {
    setLoading(true);
    setError(null);

    try {
      const params = new URLSearchParams({
        page: currentPage.toString(),
        limit: '10',
        ...(searchTerm && { search: searchTerm }),
        ...(roleFilter && { role: roleFilter }),
        ...(statusFilter && { status: statusFilter }),
      });

      const response = await fetch(`/api/admin/users?${params}`);

      if (!response.ok) {
        throw new Error(`Failed to fetch users: ${response.status}`);
      }

      const data: UsersResponse = await response.json();
      setUsers(data.users);
      setPagination(data.pagination);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An error occurred');
      console.error('Error fetching users:', err);
    } finally {
      setLoading(false);
    }
  };

  // Fetch user statistics
  const fetchUserStats = async () => {
    try {
      const response = await fetch('/api/admin/users/stats');
      if (response.ok) {
        const stats = await response.json();
        setUserStats(stats);
      }
    } catch (err) {
      console.error('Error fetching user stats:', err);
    }
  };

  // Delete user function
  const handleDeleteUser = async () => {
    if (!selectedUser) return;

    setDeleteLoading(true);
    try {
      const response = await fetch('/api/admin/users', {
        method: 'DELETE',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ userId: selectedUser.id }),
      });

      if (!response.ok) {
        const error = await response.json();
        throw new Error(error.error || 'Failed to delete user');
      }

      fetchUsers(); // Refresh the list
      fetchUserStats(); // Refresh stats
      setDeleteModalOpened(false);
      setSelectedUser(null);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to delete user');
    } finally {
      setDeleteLoading(false);
    }
  };

  // Send email function (placeholder)
  const handleSendEmail = async () => {
    if (!selectedUser) return;

    // Placeholder for email functionality
    console.log(`Sending email to ${selectedUser.email}`);
    alert(`Email functionality would send to: ${selectedUser.email}`);
    setEmailModalOpened(false);
    setSelectedUser(null);
  };

  // Modal handlers
  const openEditModal = (user: User) => {
    setSelectedUser(user);
    setEditModalOpened(true);
  };

  const openDeleteModal = (user: User) => {
    setSelectedUser(user);
    setDeleteModalOpened(true);
  };

  const openEmailModal = (user: User) => {
    setSelectedUser(user);
    setEmailModalOpened(true);
  };

  // Effects
  useEffect(() => {
    fetchUsers();
  }, [currentPage, searchTerm, roleFilter, statusFilter]);

  useEffect(() => {
    fetchUserStats();
  }, []);

  // Handle search with debounce
  useEffect(() => {
    const timer = setTimeout(() => {
      setCurrentPage(1); // Reset to first page when searching
    }, 300);

    return () => clearTimeout(timer);
  }, [searchTerm]);

  // Stats data for display
  const statsData = userStats
    ? [
        {
          title: 'Total Users',
          value: userStats.total.toString(),
          icon: IconUsers,
          color: 'blue',
        },
        {
          title: 'Active Users',
          value: userStats.active.toString(),
          icon: IconUserCheck,
          color: 'green',
        },
        {
          title: 'Recent Signups',
          value: userStats.recentSignups.toString(),
          icon: IconUserX,
          color: 'orange',
        },
        {
          title: 'Admin Users',
          value: userStats.admins.toString(),
          icon: IconCrown,
          color: 'violet',
        },
      ]
    : [];

  // Table rows
  const rows = users.map(user => (
    <Table.Tr key={user.id}>
      <Table.Td>
        <Group gap="sm">
          <Avatar color="blue" radius="xl">
            {user.avatar}
          </Avatar>
          <div>
            <Text fw={500}>{user.name}</Text>
            <Text size="sm" c="dimmed">
              {user.email}
            </Text>
          </div>
        </Group>
      </Table.Td>
      <Table.Td>
        <Badge
          variant="light"
          color={
            user.role === 'admin'
              ? 'red'
              : user.role === 'editor'
                ? 'blue'
                : 'gray'
          }
        >
          {user.role}
        </Badge>
      </Table.Td>
      <Table.Td>
        <Badge
          variant="dot"
          color={
            user.status === 'Active'
              ? 'green'
              : user.status === 'Inactive'
                ? 'red'
                : 'orange'
          }
        >
          {user.status}
        </Badge>
      </Table.Td>
      <Table.Td>
        <Text size="sm">{user.lastLogin}</Text>
      </Table.Td>
      <Table.Td>
        <Text size="sm">{user.joinDate}</Text>
      </Table.Td>
      <Table.Td>
        <Group gap={4}>
          <ActionIcon
            variant="subtle"
            color="blue"
            onClick={() => openEditModal(user)}
          >
            <IconEdit size={16} />
          </ActionIcon>
          <ActionIcon
            variant="subtle"
            color="green"
            onClick={() => openEmailModal(user)}
          >
            <IconMail size={16} />
          </ActionIcon>
          <Menu shadow="md" width={200}>
            <Menu.Target>
              <ActionIcon variant="subtle" color="gray">
                <IconDots size={16} />
              </ActionIcon>
            </Menu.Target>
            <Menu.Dropdown>
              <Menu.Item
                leftSection={<IconEdit size={14} />}
                onClick={() => openEditModal(user)}
              >
                Edit User
              </Menu.Item>
              <Menu.Item
                leftSection={<IconMail size={14} />}
                onClick={() => openEmailModal(user)}
              >
                Send Email
              </Menu.Item>
              <Menu.Divider />
              <Menu.Item
                leftSection={<IconTrash size={14} />}
                color="red"
                onClick={() => openDeleteModal(user)}
              >
                Delete User
              </Menu.Item>
            </Menu.Dropdown>
          </Menu>
        </Group>
      </Table.Td>
    </Table.Tr>
  ));

  // Loading state
  if (loading && users.length === 0) {
    return (
      <Stack gap="lg">
        <Group justify="space-between">
          <div>
            <Title order={2}>User Management</Title>
            <Text c="dimmed" size="sm">
              Manage user accounts, roles, and permissions
            </Text>
          </div>
        </Group>
        <Center h={400}>
          <Stack align="center" gap="md">
            <Loader size="lg" />
            <Text>Loading users...</Text>
          </Stack>
        </Center>
      </Stack>
    );
  }

  return (
    <Stack gap="lg">
      <Group justify="space-between">
        <div>
          <Title order={2}>User Management</Title>
          <Text c="dimmed" size="sm">
            Manage user accounts, roles, and permissions
          </Text>
        </div>
        <Button
          leftSection={<IconPlus size={16} />}
          onClick={() => setAddModalOpened(true)}
        >
          Add User
        </Button>
      </Group>

      {/* Error Display */}
      {error && (
        <Alert
          icon={<IconAlertCircle size="1rem" />}
          title="Error"
          color="red"
          variant="light"
          onClose={() => setError(null)}
          withCloseButton
        >
          {error}
        </Alert>
      )}

      {/* User Stats */}
      {userStats && (
        <SimpleGrid cols={{ base: 2, sm: 4 }} spacing="lg">
          {statsData.map(stat => (
            <Card key={stat.title} withBorder padding="md" radius="md">
              <Group justify="space-between">
                <div>
                  <Text c="dimmed" size="sm" tt="uppercase" fw={700}>
                    {stat.title}
                  </Text>
                  <Text fw={700} size="xl">
                    {stat.value}
                  </Text>
                </div>
                <ThemeIcon
                  color={stat.color}
                  size={38}
                  radius="md"
                  variant="light"
                >
                  <stat.icon size={22} stroke={1.5} />
                </ThemeIcon>
              </Group>
            </Card>
          ))}
        </SimpleGrid>
      )}

      {/* Filters and Search */}
      <Card withBorder padding="lg" radius="md">
        <Group justify="space-between" mb="md">
          <Text fw={500} size="lg">
            All Users
          </Text>
          <Text size="sm" c="dimmed">
            {pagination.total} users found
          </Text>
        </Group>

        <Group mb="lg">
          <TextInput
            placeholder="Search users..."
            leftSection={<IconSearch size={16} />}
            value={searchTerm}
            onChange={event => setSearchTerm(event.currentTarget.value)}
            style={{ flex: 1 }}
          />
          <Select
            placeholder="Filter by role"
            data={['admin', 'user']}
            value={roleFilter}
            onChange={setRoleFilter}
            clearable
            style={{ width: 150 }}
          />
          <Select
            placeholder="Filter by status"
            data={['Active', 'Inactive', 'Pending']}
            value={statusFilter}
            onChange={setStatusFilter}
            clearable
            style={{ width: 150 }}
          />
        </Group>

        {/* Users Table */}
        {loading ? (
          <Center p="xl">
            <Stack align="center" gap="md">
              <Loader />
              <Text>Loading users...</Text>
            </Stack>
          </Center>
        ) : users.length === 0 ? (
          <Center p="xl">
            <Stack align="center" gap="md">
              <IconUsers size={48} color="gray" />
              <Text size="lg" c="dimmed">
                No users found
              </Text>
              <Text size="sm" c="dimmed">
                {searchTerm || roleFilter || statusFilter
                  ? 'Try adjusting your search or filters'
                  : 'No users have been created yet'}
              </Text>
            </Stack>
          </Center>
        ) : (
          <>
            <Table.ScrollContainer minWidth={800}>
              <Table verticalSpacing="sm">
                <Table.Thead>
                  <Table.Tr>
                    <Table.Th>User</Table.Th>
                    <Table.Th>Role</Table.Th>
                    <Table.Th>Status</Table.Th>
                    <Table.Th>Last Login</Table.Th>
                    <Table.Th>Join Date</Table.Th>
                    <Table.Th>Actions</Table.Th>
                  </Table.Tr>
                </Table.Thead>
                <Table.Tbody>{rows}</Table.Tbody>
              </Table>
            </Table.ScrollContainer>

            {/* Pagination */}
            {pagination.pages > 1 && (
              <Group justify="center" mt="lg">
                <Pagination
                  value={currentPage}
                  onChange={setCurrentPage}
                  total={pagination.pages}
                  size="sm"
                />
              </Group>
            )}
          </>
        )}
      </Card>

      {/* User Management Modals */}
      <UserManagementModals
        addModalOpened={addModalOpened}
        editModalOpened={editModalOpened}
        selectedUser={selectedUser}
        onAddModalClose={() => setAddModalOpened(false)}
        onEditModalClose={() => setEditModalOpened(false)}
        onUserCreated={() => {
          fetchUsers();
          fetchUserStats();
        }}
        onUserUpdated={() => {
          fetchUsers();
          fetchUserStats();
        }}
      />

      {/* Delete Confirmation Modal */}
      <Modal
        opened={deleteModalOpened}
        onClose={() => setDeleteModalOpened(false)}
        title="Delete User"
        centered
      >
        <Stack gap="md">
          <Text>
            Are you sure you want to delete user <strong>{selectedUser?.name}</strong>?
            This action cannot be undone.
          </Text>
          <Group justify="flex-end">
            <Button
              variant="outline"
              onClick={() => setDeleteModalOpened(false)}
              disabled={deleteLoading}
            >
              Cancel
            </Button>
            <Button
              color="red"
              onClick={handleDeleteUser}
              loading={deleteLoading}
              leftSection={<IconTrash size={16} />}
            >
              Delete User
            </Button>
          </Group>
        </Stack>
      </Modal>

      {/* Email Modal */}
      <Modal
        opened={emailModalOpened}
        onClose={() => setEmailModalOpened(false)}
        title="Send Email"
        centered
      >
        <Stack gap="md">
          <Text>
            Send an email to <strong>{selectedUser?.name}</strong> at{' '}
            <strong>{selectedUser?.email}</strong>?
          </Text>
          <Text size="sm" c="dimmed">
            This will open your default email client or you can implement
            custom email functionality here.
          </Text>
          <Group justify="flex-end">
            <Button
              variant="outline"
              onClick={() => setEmailModalOpened(false)}
            >
              Cancel
            </Button>
            <Button
              onClick={handleSendEmail}
              leftSection={<IconMail size={16} />}
            >
              Send Email
            </Button>
          </Group>
        </Stack>
      </Modal>
    </Stack>
  );
}

