'use client';

import React, { useState, useEffect, useCallback, useMemo } from 'react';
import {
  Card,
  Text,
  Title,
  Stack,
  Group,
  Badge,
  Avatar,
  ActionIcon,
  TextInput,
  Select,
  Button,
  Table,
  Pagination,
  Menu,
  ThemeIcon,
  SimpleGrid,
  Alert,
  Loader,
  Center,
  Checkbox,
  Paper,
  Transition,
  Modal,
  Progress,
  FileInput,
  Tabs,
  NumberInput,
  DateInput,
  MultiSelect,
  Switch,
  Tooltip,
  UnstyledButton,
  ScrollArea,
  Divider,
  Anchor,
} from '@mantine/core';
import {
  IconSearch,
  IconPlus,
  IconDots,
  IconEdit,
  IconTrash,
  IconMail,
  IconUsers,
  IconUserCheck,
  IconUserX,
  IconCrown,
  IconAlertCircle,
  IconDownload,
  IconUpload,
  IconFilter,
  IconClearAll,
  IconCheck,
  IconX,
  IconChevronDown,
  IconChevronUp,
  IconColumns,
  IconSettings,
  IconFileExport,
  IconFileImport,
  IconTrashX,
  IconUserShield,
  IconSend,
  IconHistory,
  IconReload,
  IconCalendar,
  IconEye,
  IconEyeOff,
} from '@tabler/icons-react';
import { useDisclosure } from '@mantine/hooks';
import { notifications } from '@mantine/notifications';

// Enhanced interfaces
interface User {
  id: string;
  name: string;
  email: string;
  role: string;
  status: string;
  lastLogin: string;
  avatar: string;
  joinDate: string;
  isActive?: boolean;
  loginCount?: number;
  lastActivity?: string;
}

interface UserStats {
  total: number;
  active: number;
  admins: number;
  recentSignups: number;
  inactiveUsers?: number;
  suspendedUsers?: number;
}

interface BulkOperation {
  type: 'delete' | 'changeRole' | 'activate' | 'deactivate' | 'sendEmail';
  users: string[];
  data?: any;
}

interface FilterState {
  search: string;
  role: string | null;
  status: string | null;
  dateRange: [Date | null, Date | null];
  isActive: boolean | null;
  loginCount: [number, number];
}

interface SortConfig {
  field: string;
  direction: 'asc' | 'desc';
}

export default function EnhancedUsers() {
  // State management
  const [users, setUsers] = useState<User[]>([]);
  const [userStats, setUserStats] = useState<UserStats | null>(null);
  const [selectedUsers, setSelectedUsers] = useState<Set<string>>(new Set());
  const [currentPage, setCurrentPage] = useState(1);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [bulkLoading, setBulkLoading] = useState(false);
  const [bulkProgress, setBulkProgress] = useState(0);

  // Filter and search state
  const [filters, setFilters] = useState<FilterState>({
    search: '',
    role: null,
    status: null,
    dateRange: [null, null],
    isActive: null,
    loginCount: [0, 1000],
  });

  // Table customization state
  const [sortConfig, setSortConfig] = useState<SortConfig>({ field: 'name', direction: 'asc' });
  const [visibleColumns, setVisibleColumns] = useState<Set<string>>(
    new Set(['name', 'role', 'status', 'lastLogin', 'joinDate', 'actions'])
  );
  const [tableDensity, setTableDensity] = useState<'xs' | 'sm' | 'md' | 'lg'>('sm');

  // Modal states
  const [bulkModalOpened, { open: openBulkModal, close: closeBulkModal }] = useDisclosure(false);
  const [importModalOpened, { open: openImportModal, close: closeImportModal }] = useDisclosure(false);
  const [exportModalOpened, { open: openExportModal, close: closeExportModal }] = useDisclosure(false);
  const [filtersModalOpened, { open: openFiltersModal, close: closeFiltersModal }] = useDisclosure(false);

  // Operation state
  const [currentBulkOperation, setCurrentBulkOperation] = useState<BulkOperation | null>(null);
  const [operationHistory, setOperationHistory] = useState<any[]>([]);

  const [pagination, setPagination] = useState({
    page: 1,
    limit: 10,
    total: 0,
    pages: 0,
    hasNext: false,
    hasPrev: false,
  });

  // Available options
  const roleOptions = [
    { value: 'admin', label: 'Admin' },
    { value: 'user', label: 'User' },
    { value: 'editor', label: 'Editor' },
    { value: 'viewer', label: 'Viewer' },
  ];

  const statusOptions = [
    { value: 'Active', label: 'Active' },
    { value: 'Inactive', label: 'Inactive' },
    { value: 'Suspended', label: 'Suspended' },
    { value: 'Pending', label: 'Pending' },
  ];

  const columnOptions = [
    { value: 'name', label: 'Name' },
    { value: 'role', label: 'Role' },
    { value: 'status', label: 'Status' },
    { value: 'lastLogin', label: 'Last Login' },
    { value: 'joinDate', label: 'Join Date' },
    { value: 'loginCount', label: 'Login Count' },
    { value: 'actions', label: 'Actions' },
  ];

  // Memoized filtered and sorted data
  const filteredAndSortedUsers = useMemo(() => {
    let filtered = users.filter(user => {
      // Search filter
      if (filters.search) {
        const searchLower = filters.search.toLowerCase();
        if (!user.name.toLowerCase().includes(searchLower) && 
            !user.email.toLowerCase().includes(searchLower)) {
          return false;
        }
      }

      // Role filter
      if (filters.role && user.role !== filters.role) return false;

      // Status filter
      if (filters.status && user.status !== filters.status) return false;

      // Active filter
      if (filters.isActive !== null && user.isActive !== filters.isActive) return false;

      return true;
    });

    // Sort data
    filtered.sort((a, b) => {
      const { field, direction } = sortConfig;
      const aValue = a[field as keyof User] || '';
      const bValue = b[field as keyof User] || '';

      if (direction === 'asc') {
        return aValue > bValue ? 1 : -1;
      } else {
        return aValue < bValue ? 1 : -1;
      }
    });

    return filtered;
  }, [users, filters, sortConfig]);

  // Fetch users with enhanced filtering
  const fetchUsers = useCallback(async () => {
    setLoading(true);
    setError(null);

    try {
      const params = new URLSearchParams({
        page: currentPage.toString(),
        limit: pagination.limit.toString(),
        ...(filters.search && { search: filters.search }),
        ...(filters.role && { role: filters.role }),
        ...(filters.status && { status: filters.status }),
      });

      const response = await fetch(`/api/admin/users?${params}`);
      if (!response.ok) throw new Error(`Failed to fetch users: ${response.status}`);

      const data = await response.json();
      setUsers(data.users);
      setPagination(data.pagination);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An error occurred');
    } finally {
      setLoading(false);
    }
  }, [currentPage, pagination.limit, filters]);

  // Fetch user statistics
  const fetchUserStats = useCallback(async () => {
    try {
      const response = await fetch('/api/admin/users/stats');
      if (response.ok) {
        const stats = await response.json();
        setUserStats(stats);
      }
    } catch (err) {
      console.error('Error fetching user stats:', err);
    }
  }, []);

  // Selection handlers
  const handleSelectAll = (checked: boolean) => {
    if (checked) {
      const visibleUserIds = filteredAndSortedUsers.map(user => user.id);
      setSelectedUsers(new Set(visibleUserIds));
    } else {
      setSelectedUsers(new Set());
    }
  };

  const handleSelectUser = (userId: string, checked: boolean) => {
    const newSelection = new Set(selectedUsers);
    if (checked) {
      newSelection.add(userId);
    } else {
      newSelection.delete(userId);
    }
    setSelectedUsers(newSelection);
  };

  const clearSelection = () => {
    setSelectedUsers(new Set());
  };

  // Sorting handler
  const handleSort = (field: string) => {
    setSortConfig(prev => ({
      field,
      direction: prev.field === field && prev.direction === 'asc' ? 'desc' : 'asc'
    }));
  };

  // Filter handlers
  const updateFilter = <K extends keyof FilterState>(
    key: K,
    value: FilterState[K]
  ) => {
    setFilters(prev => ({ ...prev, [key]: value }));
    setCurrentPage(1); // Reset to first page when filtering
  };

  const clearAllFilters = () => {
    setFilters({
      search: '',
      role: null,
      status: null,
      dateRange: [null, null],
      isActive: null,
      loginCount: [0, 1000],
    });
  };

  // Bulk operations
  const performBulkOperation = async (operation: BulkOperation) => {
    setBulkLoading(true);
    setBulkProgress(0);

    try {
      const response = await fetch('/api/admin/users/bulk', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(operation),
      });

      if (!response.ok) throw new Error('Bulk operation failed');

      const result = await response.json();

      // Update UI
      await fetchUsers();
      await fetchUserStats();
      clearSelection();

      // Add to history
      setOperationHistory(prev => [{
        id: Date.now(),
        type: operation.type,
        userCount: operation.users.length,
        timestamp: new Date(),
        result,
      }, ...prev.slice(0, 9)]); // Keep last 10 operations

      notifications.show({
        title: 'Bulk Operation Complete',
        message: `Successfully processed ${operation.users.length} users`,
        color: 'green',
      });
    } catch (err) {
      notifications.show({
        title: 'Bulk Operation Failed',
        message: err instanceof Error ? err.message : 'An error occurred',
        color: 'red',
      });
    } finally {
      setBulkLoading(false);
      setBulkProgress(0);
      closeBulkModal();
    }
  };

  // Delete handler
  const handleDelete = async (userId: string) => {
    if (!confirm('Are you sure you want to delete this user?')) return;

    try {
      const response = await fetch('/api/admin/users', {
        method: 'DELETE',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ userId }),
      });

      if (response.ok) {
        await fetchUsers();
        await fetchUserStats();
        notifications.show({
          title: 'User Deleted',
          message: 'User has been successfully deleted',
          color: 'green',
        });
      } else {
        throw new Error('Failed to delete user');
      }
    } catch (err) {
      notifications.show({
        title: 'Delete Failed',
        message: err instanceof Error ? err.message : 'Failed to delete user',
        color: 'red',
      });
    }
  };

  // Effects
  useEffect(() => {
    fetchUsers();
  }, [fetchUsers]);

  useEffect(() => {
    fetchUserStats();
  }, [fetchUserStats]);

  // Search with debounce
  useEffect(() => {
    const timer = setTimeout(() => {
      setCurrentPage(1);
    }, 300);
    return () => clearTimeout(timer);
  }, [filters.search]);

  // Computed values
  const isAllSelected = filteredAndSortedUsers.length > 0 && 
    filteredAndSortedUsers.every(user => selectedUsers.has(user.id));
  const isIndeterminate = selectedUsers.size > 0 && !isAllSelected;
  const hasActiveFilters = Object.values(filters).some(value => 
    value !== null && value !== '' && 
    (!Array.isArray(value) || value.some(v => v !== null))
  );

  // Loading state
  if (loading && users.length === 0) {
    return (
      <Stack gap="lg">
        <Group justify="space-between">
          <div>
            <Title order={2}>User Management</Title>
            <Text c="dimmed" size="sm">Manage user accounts, roles, and permissions</Text>
          </div>
        </Group>
        <Center h={400}>
          <Stack align="center" gap="md">
            <Loader size="lg" />
            <Text>Loading users...</Text>
          </Stack>
        </Center>
      </Stack>
    );
  }

  return (
    <Stack gap="lg">
      {/* Header */}
      <Group justify="space-between">
        <div>
          <Title order={2}>User Management</Title>
          <Text c="dimmed" size="sm">
            Advanced user management with bulk operations and analytics
          </Text>
        </div>
        <Group>
          <Button
            leftSection={<IconFileImport size={16} />}
            variant="light"
            onClick={openImportModal}
          >
            Import
          </Button>
          <Button
            leftSection={<IconFileExport size={16} />}
            variant="light"
            onClick={openExportModal}
          >
            Export
          </Button>
          <Button leftSection={<IconPlus size={16} />}>
            Add User
          </Button>
        </Group>
      </Group>

      {/* Error Display */}
      {error && (
        <Alert
          icon={<IconAlertCircle size="1rem" />}
          title="Error"
          color="red"
          variant="light"
          onClose={() => setError(null)}
          withCloseButton
        >
          {error}
        </Alert>
      )}

      {/* Enhanced Stats */}
      {userStats && (
        <SimpleGrid cols={{ base: 2, sm: 4, lg: 6 }} spacing="lg">
          <Card withBorder padding="md" radius="md">
