// Utility functions for user management operations
const userManagementUtils = {
  // Bulk operation helpers
  validateBulkOperation: (operation: BulkOperation): { valid: boolean; errors: string[] } => {
    const errors: string[] = [];

    if (!operation.users || operation.users.length === 0) {
      errors.push('No users selected for operation');
    }

    if (operation.type === 'changeRole' && !operation.data?.newRole) {
      errors.push('New role must be specified');
    }

    if (operation.type === 'sendEmail') {
      if (!operation.data?.subject?.trim()) {
        errors.push('Email subject is required');
      }
      if (!operation.data?.message?.trim()) {
        errors.push('Email message is required');
      }
    }

    return { valid: errors.length === 0, errors };
  },

  // Export data formatting
  formatExportData: (users: User[], fields: string[], format: string) => {
    const filteredData = users.map(user => {
      const filtered: any = {};
      fields.forEach(field => {
        if (field in user) {
          filtered[field] = user[field as keyof User];
        }
      });
      return filtered;
    });

    switch (format) {
      case 'csv':
        return convertToCSV(filteredData);
      case 'json':
        return JSON.stringify(filteredData, null, 2);
      case 'excel':
        return convertToExcel(filteredData);
      default:
        return filteredData;
    }
  },

  // Import validation
  validateImportData: (data: any[]): { valid: any[]; invalid: any[] } => {
    const valid: any[] = [];
    const invalid: any[] = [];

    data.forEach((row, index) => {
      const errors: string[] = [];

      if (!row.name?.trim()) {
        errors.push('Name is required');
      }

      if (!row.email?.trim() || !isValidEmail(row.email)) {
        errors.push('Valid email is required');
      }

      if (!row.role || !['admin', 'user', 'editor', 'viewer'].includes(row.role)) {
        errors.push('Valid role is required');
      }

      if (errors.length === 0) {
        valid.push({ ...row, _index: index + 1 });
      } else {
        invalid.push({ ...row, _index: index + 1, _errors: errors });
      }
    });

    return { valid, invalid };
  },

  // Filter helpers
  applyFilters: (users: User[], filters: FilterState): User[] => {
    return users.filter(user => {
      // Search filter
      if (filters.search) {
        const searchLower = filters.search.toLowerCase();
        if (!user.name.toLowerCase().includes(searchLower) && 
            !user.email.toLowerCase().includes(searchLower)) {
          return false;
        }
      }

      // Role filter
      if (filters.role && user.role !== filters.role) return false;

      // Status filter
      if (filters.status && user.status !== filters.status) return false;

      // Date range filter
      if (filters.dateRange[0] || filters.dateRange[1]) {
        const joinDate = new Date(user.joinDate);
        if (filters.dateRange[0] && joinDate < filters.dateRange[0]) return false;
        if (filters.dateRange[1] && joinDate > filters.dateRange[1]) return false;
      }

      // Login count filter
      const loginCount = user.loginCount || 0;
      if (loginCount < filters.loginCount[0] || loginCount > filters.loginCount[1]) {
        return false;
      }

      // Activity filter
      if (filters.isActive !== null && user.isActive !== filters.isActive) return false;

      return true;
    });
  },

  // Analytics calculations
  calculateUserAnalytics: (users: User[]) => {
    const now = new Date();
    const weekAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
    const monthAgo = new Date(now.getTime() - 30 * 24 * 60 * 60 * 1000);

    const analytics = {
      total: users.length,
      active: users.filter(u => u.status === 'Active').length,
      inactive: users.filter(u => u.status === 'Inactive').length,
      suspended: users.filter(u => u.status === 'Suspended').length,

      // Role distribution
      roleDistribution: {
        admin: users.filter(u => u.role === 'admin').length,
        user: users.filter(u => u.role === 'user').length,
        editor: users.filter(u => u.role === 'editor').length,
        viewer: users.filter(u => u.role === 'viewer').length,
      },

      // Growth metrics
      newUsersThisWeek: users.filter(u => new Date(u.joinDate) >= weekAgo).length,
      newUsersThisMonth: users.filter(u => new Date(u.joinDate) >= monthAgo).length,

      // Activity metrics
      averageLoginCount: users.reduce((sum, u) => sum + (u.loginCount || 0), 0) / users.length,
      topActiveUsers: users
        .sort((a, b) => (b.loginCount || 0) - (a.loginCount || 0))
        .slice(0, 5),

      // Engagement metrics
      onlineUsers: users.filter(u => u.isActive).length,
      recentlyActive: users.filter(u => {
        if (!u.lastActivity) return false;
        return new Date(u.lastActivity) >= weekAgo;
      }).length,
    };

    return analytics;
  }
};

// Helper functions
const isValidEmail = (email: string): boolean => {
  const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
  return emailRegex.test(email);
};

const convertToCSV = (data: any[]): string => {
  if (data.length === 0) return '';

  const headers = Object.keys(data[0]);
  const csvContent = [
    headers.join(','),
    ...data.map(row => 
      headers.map(header => {
        const value = row[header];
        if (typeof value === 'string' && (value.includes(',') || value.includes('"'))) {
          return `"${value.replace(/"/g, '""')}"`;
        }
        return value;
      }).join(',')
    )
  ].join('\n');

  return csvContent;
};

const convertToExcel = (data: any[]): string => {
  // This would typically use a library like SheetJS
  // For now, return CSV format as fallback
  return convertToCSV(data);
};

// Enhanced component continuation with analytics
const EnhancedUsersAnalytics = () => {
  const [analyticsData, setAnalyticsData] = useState<any>(null);
  const [analyticsLoading, setAnalyticsLoading] = useState(false);

  const fetchAnalytics = useCallback(async () => {
    setAnalyticsLoading(true);
    try {
      const analytics = userManagementUtils.calculateUserAnalytics(users);
      setAnalyticsData(analytics);
    } catch (error) {
      console.error('Error calculating analytics:', error);
    } finally {
      setAnalyticsLoading(false);
    }
  }, [users]);

  useEffect(() => {
    if (users.length > 0) {
      fetchAnalytics();
    }
  }, [users, fetchAnalytics]);

  if (!analyticsData) return null;

  return (
    <Card withBorder padding="lg" radius="md" mt="lg">
      <Group justify="space-between" mb="md">
        <Title order={3}>User Analytics</Title>
        <Button
          variant="light"
          size="sm"
          leftSection={<IconReload size={14} />}
          onClick={fetchAnalytics}
          loading={analyticsLoading}
        >
          Refresh
        </Button>
      </Group>

      <SimpleGrid cols={{ base: 1, sm: 2, lg: 4 }} spacing="lg" mb="xl">
