// Keyboard shortcuts handler
const useKeyboardShortcuts = (callbacks: any) => {
  useEffect(() => {
    const handleKeyDown = (event: KeyboardEvent) => {
      // Ctrl/Cmd + A - Select all
      if ((event.ctrlKey || event.metaKey) && event.key === 'a' && !event.target) {
        event.preventDefault();
        callbacks.selectAll?.();
      }

      // Escape - Clear selection
      if (event.key === 'Escape') {
        callbacks.clearSelection?.();
      }

      // Delete - Delete selected (with confirmation)
      if (event.key === 'Delete' && selectedUsers.size > 0) {
        callbacks.deleteSelected?.();
      }

      // Ctrl/Cmd + F - Focus search
      if ((event.ctrlKey || event.metaKey) && event.key === 'f') {
        event.preventDefault();
        callbacks.focusSearch?.();
      }
    };

    document.addEventListener('keydown', handleKeyDown);
    return () => document.removeEventListener('keydown', handleKeyDown);
  }, [callbacks]);
};

// Performance optimization hooks
const useDebounce = (value: string, delay: number) => {
  const [debouncedValue, setDebouncedValue] = useState(value);

  useEffect(() => {
    const handler = setTimeout(() => {
      setDebouncedValue(value);
    }, delay);

    return () => {
      clearTimeout(handler);
    };
  }, [value, delay]);

  return debouncedValue;
};

const usePagination = (data: any[], pageSize: number) => {
  const [currentPage, setCurrentPage] = useState(1);

  const paginatedData = useMemo(() => {
    const startIndex = (currentPage - 1) * pageSize;
    return data.slice(startIndex, startIndex + pageSize);
  }, [data, currentPage, pageSize]);

  const totalPages = Math.ceil(data.length / pageSize);

  return {
    currentPage,
    setCurrentPage,
    paginatedData,
    totalPages,
    hasNext: currentPage < totalPages,
    hasPrev: currentPage > 1,
  };
};

