// Chord diagrams database - updated with proper fret positions
const chordDiagrams = {
    'Em7': { frets: [0, 2, 0, 0, 0, 0], fingers: [0, 2, 0, 0, 0, 0] },
    'G': { frets: [3, 2, 0, 0, 3, 3], fingers: [3, 1, 0, 0, 4, 4] },
    'D': { frets: [-1, -1, 0, 2, 3, 2], fingers: [0, 0, 0, 1, 3, 2] },
    'C': { frets: [-1, 3, 2, 0, 1, 0], fingers: [0, 3, 2, 0, 1, 0] },
    'Am': { frets: [-1, 0, 2, 2, 1, 0], fingers: [0, 0, 2, 3, 1, 0] },
    'F': { frets: [1, 3, 3, 2, 1, 1], fingers: [1, 3, 4, 2, 1, 1] },
    'E': { frets: [0, 2, 2, 1, 0, 0], fingers: [0, 2, 3, 1, 0, 0] },
    'A': { frets: [-1, 0, 2, 2, 2, 0], fingers: [0, 0, 1, 2, 3, 0] },
    'Dm': { frets: [-1, -1, 0, 2, 3, 1], fingers: [0, 0, 0, 2, 3, 1] },
    'Em': { frets: [0, 2, 2, 0, 0, 0], fingers: [0, 2, 3, 0, 0, 0] },
    'B7': { frets: [-1, 2, 1, 2, 0, 2], fingers: [0, 2, 1, 3, 0, 4] },
    'F#m': { frets: [2, 4, 4, 2, 2, 2], fingers: [1, 3, 4, 1, 1, 1] }
};

function createChordDiagram(chordName) {
    const chordData = chordDiagrams[chordName];
    if (!chordData) return null;

    const diagram = document.createElement('div');
    diagram.className = 'chord-diagram';

    // Chord name
    const name = document.createElement('div');
    name.className = 'chord-name';
    name.textContent = chordName;

    // String markers (E A D G B E from left to right)
    const stringMarkers = document.createElement('div');
    stringMarkers.className = 'string-markers';
    ['E', 'A', 'D', 'G', 'B', 'E'].forEach(note => {
        const marker = document.createElement('div');
        marker.className = 'string-marker';
        marker.textContent = note;
        stringMarkers.appendChild(marker);
    });

    // Fretboard
    const fretboard = document.createElement('div');
    fretboard.className = 'fretboard';

    // Draw fret lines (horizontal)
    for (let fret = 0; fret <= 4; fret++) {
        const fretLine = document.createElement('div');
        fretLine.className = 'fret-line';
        fretLine.style.top = (fret * 24) + 'px';
        fretboard.appendChild(fretLine);
    }

    // Draw string lines (vertical)
    for (let string = 0; string < 6; string++) {
        const stringLine = document.createElement('div');
        stringLine.className = 'string-line';
        stringLine.style.left = (string * 23 + 11) + 'px';
        fretboard.appendChild(stringLine);
    }

    // Place finger dots and markers
    chordData.frets.forEach((fret, stringIndex) => {
        const x = stringIndex * 23 + 12;

        if (fret === -1) {
            // Muted string
            const muted = document.createElement('div');
            muted.className = 'muted-string';
            muted.textContent = '×';
            muted.style.left = x + 'px';
            fretboard.appendChild(muted);
        } else if (fret === 0) {
            // Open string
            const open = document.createElement('div');
            open.className = 'open-string';
            open.style.left = x + 'px';
            fretboard.appendChild(open);
        } else {
            // Fretted note
            const dot = document.createElement('div');
            dot.className = 'finger-dot';
            dot.style.left = x + 'px';
            dot.style.top = (fret * 24 - 12) + 'px';
            dot.textContent = chordData.fingers[stringIndex];
            fretboard.appendChild(dot);
        }
    });

    diagram.appendChild(name);
    diagram.appendChild(stringMarkers);
    diagram.appendChild(fretboard);

    return diagram;
}

function showChordDiagram(chordName) {
    const container = document.getElementById('currentChordDiagram');
    container.innerHTML = '';

    const diagram = createChordDiagram(chordName);
    if (diagram) {
        container.appendChild(diagram);
    }
}

