function parseCustomTab(tabText) {
    const lines = tabText.trim().split('\n');
    const sections = [];
    let strummingPattern = '';
    let currentSection = null;
    let i = 0;

    while (i < lines.length) {
        const line = lines[i].trim();

        // Skip empty lines
        if (!line) {
            i++;
            continue;
        }

        // Check for strumming pattern
        if (line.toLowerCase().includes('strum') || line.match(/^[DUdu\s\-]+$/)) {
            strummingPattern = line.replace(/strum.*?:/i, '').trim();
            i++;
            continue;
        }

        // Check for section headers [Verse 1], [Chorus], etc.
        if (line.match(/^\[.*\]$/)) {
            // Section header - just skip for now, we'll group everything together
            i++;
            continue;
        }

        // Check if this line has chords (letters separated by spaces, positioned above lyrics)
        const isChordLine = line.match(/^[\s]*[A-G][#b]?[mM]?[0-9]?[\s]+/) || 
                           line.match(/[A-G][#b]?[mM]?[0-9]?/) && 
                           !line.match(/[a-z]{3,}/); // Avoid lines with lots of lowercase (lyrics)

        if (isChordLine && i + 1 < lines.length) {
            // This is a chord line, next line should be lyrics
            const chordLine = line;
            const lyricLine = lines[i + 1] || '';

            // Parse chords and their positions
            const chords = [];
            const lyrics = [];

            // Find chord positions
            const chordMatches = [...chordLine.matchAll(/([A-G][#b]?[mM]?[0-9]?)/g)];

            if (chordMatches.length > 0) {
                let lastPos = 0;

                chordMatches.forEach((match, index) => {
                    const chordPos = match.index;
                    const chord = match[1];

                    // Extract lyric portion from this chord to the next
                    const nextPos = index < chordMatches.length - 1 ? 
                                  chordMatches[index + 1].index : 
                                  lyricLine.length;

                    const lyricPortion = lyricLine.slice(chordPos, nextPos).trim();

                    chords.push(chord);
                    lyrics.push(lyricPortion || '');
                });

                if (chords.length > 0) {
                    sections.push({ chords, lyrics });
                }
            }

            i += 2; // Skip both chord and lyric lines
        } else {
            // Single line - check if it contains chords in [bracket] format
            const bracketChords = [...line.matchAll(/\[([^\]]+)\]/g)];
            if (bracketChords.length > 0) {
                const chords = [];
                const lyrics = [];

                const parts = line.split(/(\[[^\]]+\])/);
                let currentLyric = '';

                parts.forEach(part => {
                    if (part.match(/\[[^\]]+\]/)) {
                        if (currentLyric.trim()) {
                            lyrics.push(currentLyric.trim());
                            currentLyric = '';
                        }
                        chords.push(part.replace(/[\[\]]/g, ''));
                        lyrics.push('');
                    } else if (part.trim()) {
                        currentLyric += part;
                    }
                });

                if (currentLyric.trim()) {
                    lyrics.push(currentLyric.trim());
                }

                if (chords.length > 0) {
                    while (lyrics.length < chords.length) {
                        lyrics.push('');
                    }
                    sections.push({ chords, lyrics });
                }
            }
            i++;
        }
    }

    return { sections, strummingPattern };
}

