// lib/user-management/index.ts
import { User, UserRole } from '@/types/user';
import { ObjectId } from 'mongodb';

// Core utility types
export interface SanitizedUser {
  id: string;
  name: string;
  email: string;
  role: UserRole;
  status: string;
  createdAt: Date;
  updatedAt: Date;
}

export interface EngagementScore {
  score: number;
  level: 'low' | 'medium' | 'high';
  factors: string[];
  lastActivity?: Date;
}

export interface DuplicateReport {
  duplicates: User[];
  confidence: number;
  criteria: string[];
}

export interface BulkOperation {
  type: 'create' | 'update' | 'delete' | 'activate' | 'deactivate';
  users: Partial<User>[];
  options?: Record<string, any>;
}

export interface BatchResult {
  success: number;
  failed: number;
  errors: Array<{ index: number; error: string }>;
  operationId: string;
}

export interface ValidationResult {
  valid: boolean;
  errors: string[];
  warnings?: string[];
}

export interface UserSegments {
  newUsers: User[];
  activeUsers: User[];
  inactiveUsers: User[];
  adminUsers: User[];
  segments: Record<string, User[]>;
}

export interface RetentionData {
  period: string;
  totalUsers: number;
  retainedUsers: number;
  retentionRate: number;
  cohorts: Array<{
    period: string;
    users: number;
    retained: number;
    rate: number;
  }>;
}

export interface ChurnPrediction {
  userId: string;
  riskScore: number;
  riskLevel: 'low' | 'medium' | 'high';
  factors: string[];
  recommendedActions: string[];
}

export interface Permission {
  resource: string;
  actions: string[];
  conditions?: Record<string, any>;
}

export interface AuditLog {
  userId: string;
  action: string;
  resource: string;
  timestamp: Date;
  details: Record<string, any>;
  ipAddress?: string;
}

// Core User Management Utilities
export class UserUtils {
  /**
   * Sanitize user data for client consumption
   */
  static sanitizeUserData(userData: any): SanitizedUser {
    const { passwordHash, ...sanitized } = userData;
    return {
      id: userData._id?.toString() || userData.id,
      name: userData.name || '',
      email: userData.email || '',
      role: userData.role || 'user',
      status: userData.status || 'active',
      createdAt: userData.createdAt || new Date(),
      updatedAt: userData.updatedAt || new Date(),
    };
  }

  /**
   * Generate user avatar initials
   */
  static generateUserAvatar(name: string): string {
    return name
      .split(' ')
      .map(n => n[0])
      .join('')
      .toUpperCase()
      .slice(0, 2);
  }

  /**
   * Calculate user engagement score
   */
  static calculateUserEngagement(user: User): EngagementScore {
    const factors: string[] = [];
    let score = 0;

    // Check account age
    const accountAge = Date.now() - user.createdAt.getTime();
    const daysSinceCreation = accountAge / (1000 * 60 * 60 * 24);

    if (daysSinceCreation > 30) {
      score += 20;
      factors.push('Established account');
    }

    // Role-based scoring
    if (user.role === 'admin') {
      score += 30;
      factors.push('Administrative role');
    }

    // Activity indicators (simplified)
    const hasRecentActivity = user.updatedAt.getTime() > Date.now() - (7 * 24 * 60 * 60 * 1000);
    if (hasRecentActivity) {
      score += 25;
      factors.push('Recent activity');
    }

    // Profile completeness
    if (user.name && user.email && user.image) {
      score += 25;
      factors.push('Complete profile');
    }

    const level = score >= 70 ? 'high' : score >= 40 ? 'medium' : 'low';

    return { score, level, factors };
  }

  /**
   * Detect potential duplicate users
   */
  static detectDuplicateUsers(users: User[]): DuplicateReport[] {
    const duplicates: DuplicateReport[] = [];
    const processed = new Set<string>();

    for (let i = 0; i < users.length; i++) {
      const user = users[i];
      const userId = user._id?.toString() || user.email;

      if (processed.has(userId)) continue;
      processed.add(userId);

      const potentialDuplicates = users.filter((u, index) => {
        if (index <= i) return false;

        const criteria: string[] = [];
        let matches = 0;

        // Email match
        if (u.email.toLowerCase() === user.email.toLowerCase()) {
          criteria.push('email');
          matches += 50;
        }

        // Name similarity
        if (u.name.toLowerCase().trim() === user.name.toLowerCase().trim()) {
          criteria.push('name');
          matches += 30;
        }

        // Similar creation time (within 1 hour)
        const timeDiff = Math.abs(u.createdAt.getTime() - user.createdAt.getTime());
        if (timeDiff < 3600000) {
          criteria.push('creation_time');
          matches += 20;
        }

        return matches >= 50;
      });

      if (potentialDuplicates.length > 0) {
        duplicates.push({
          duplicates: [user, ...potentialDuplicates],
          confidence: Math.min(100, potentialDuplicates.length * 25 + 25),
          criteria: ['email', 'name', 'creation_time']
        });
      }
    }

    return duplicates;
  }

  /**
   * Validate bulk operation before execution
   */
  static validateBulkOperation(operation: BulkOperation): ValidationResult {
    const errors: string[] = [];
    const warnings: string[] = [];

    if (!operation.type) {
      errors.push('Operation type is required');
    }

    if (!operation.users || operation.users.length === 0) {
      errors.push('No users provided for operation');
    }

    if (operation.users.length > 1000) {
      warnings.push('Large batch operation may take significant time');
    }

    // Validate operation-specific requirements
    switch (operation.type) {
      case 'create':
        operation.users.forEach((user, index) => {
          if (!user.email) {
            errors.push(`User at index ${index} missing email`);
          }
          if (!user.name) {
            errors.push(`User at index ${index} missing name`);
          }
        });
        break;
      case 'update':
        operation.users.forEach((user, index) => {
          if (!user._id && !user.email) {
            errors.push(`User at index ${index} missing identifier`);
          }
        });
        break;
      case 'delete':
        operation.users.forEach((user, index) => {
          if (!user._id) {
            errors.push(`User at index ${index} missing ID for deletion`);
          }
        });
        break;
    }

    return {
      valid: errors.length === 0,
      errors,
      warnings
    };
  }

  /**
   * Estimate operation execution time
   */
  static estimateOperationTime(operation: BulkOperation): number {
    const baseTimePerUser = {
      create: 100, // ms
      update: 50,
      delete: 30,
      activate: 25,
      deactivate: 25
    };

    const timePerUser = baseTimePerUser[operation.type] || 50;
    const totalTime = operation.users.length * timePerUser;

    // Add overhead for large operations
    const overhead = operation.users.length > 100 ? totalTime * 0.2 : 0;

    return Math.round(totalTime + overhead);
  }
}

// Analytics Engine
export class UserAnalytics {
  /**
   * Calculate user retention rates
   */
  static calculateRetentionRates(users: User[], period: 'daily' | 'weekly' | 'monthly' = 'monthly'): RetentionData {
    const now = new Date();
    const periodMs = {
      daily: 24 * 60 * 60 * 1000,
      weekly: 7 * 24 * 60 * 60 * 1000,
      monthly: 30 * 24 * 60 * 60 * 1000
    }[period];

    const cohorts: Array<{ period: string; users: number; retained: number; rate: number }> = [];

    // Group users by creation period
    const userCohorts = new Map<string, User[]>();

    users.forEach(user => {
      const cohortKey = new Date(
        Math.floor(user.createdAt.getTime() / periodMs) * periodMs
      ).toISOString().split('T')[0];

      if (!userCohorts.has(cohortKey)) {
        userCohorts.set(cohortKey, []);
      }
      userCohorts.get(cohortKey)!.push(user);
    });

    // Calculate retention for each cohort
    userCohorts.forEach((cohortUsers, cohortKey) => {
      const cohortDate = new Date(cohortKey);
      const retentionCutoff = new Date(cohortDate.getTime() + periodMs);

      const retainedUsers = cohortUsers.filter(user => 
        user.updatedAt > retentionCutoff
      );

      cohorts.push({
        period: cohortKey,
        users: cohortUsers.length,
        retained: retainedUsers.length,
        rate: cohortUsers.length > 0 ? (retainedUsers.length / cohortUsers.length) * 100 : 0
      });
    });

    const totalUsers = users.length;
    const totalRetained = users.filter(user => {
      const daysSinceCreation = (now.getTime() - user.createdAt.getTime()) / (24 * 60 * 60 * 1000);
      const daysSinceUpdate = (now.getTime() - user.updatedAt.getTime()) / (24 * 60 * 60 * 1000);
      return daysSinceCreation >= 30 && daysSinceUpdate <= 30;
    }).length;

    return {
      period,
      totalUsers,
      retainedUsers: totalRetained,
      retentionRate: totalUsers > 0 ? (totalRetained / totalUsers) * 100 : 0,
      cohorts: cohorts.sort((a, b) => a.period.localeCompare(b.period))
    };
  }

  /**
   * Generate user segments
   */
  static generateUserSegments(users: User[]): UserSegments {
    const now = new Date();
    const thirtyDaysAgo = new Date(now.getTime() - (30 * 24 * 60 * 60 * 1000));
    const sevenDaysAgo = new Date(now.getTime() - (7 * 24 * 60 * 60 * 1000));

    return {
      newUsers: users.filter(user => user.createdAt > sevenDaysAgo),
      activeUsers: users.filter(user => user.updatedAt > sevenDaysAgo),
      inactiveUsers: users.filter(user => user.updatedAt < thirtyDaysAgo),
      adminUsers: users.filter(user => user.role === 'admin'),
      segments: {
        'highly-engaged': users.filter(user => {
          const engagement = UserUtils.calculateUserEngagement(user);
          return engagement.level === 'high';
        }),
        'at-risk': users.filter(user => {
          const daysSinceUpdate = (now.getTime() - user.updatedAt.getTime()) / (24 * 60 * 60 * 1000);
          return daysSinceUpdate > 14 && daysSinceUpdate <= 30;
        }),
        'power-users': users.filter(user => 
          user.role === 'admin' || user.createdAt < thirtyDaysAgo
        )
      }
    };
  }

  /**
   * Predict user churn risk
   */
  static predictUserChurn(users: User[]): ChurnPrediction[] {
    return users.map(user => {
      const factors: string[] = [];
      let riskScore = 0;

      // Inactivity factor
      const daysSinceUpdate = (Date.now() - user.updatedAt.getTime()) / (24 * 60 * 60 * 1000);
      if (daysSinceUpdate > 30) {
        riskScore += 40;
        factors.push('Long period of inactivity');
      } else if (daysSinceUpdate > 14) {
        riskScore += 20;
        factors.push('Recent inactivity');
      }

      // Account age factor
      const daysSinceCreation = (Date.now() - user.createdAt.getTime()) / (24 * 60 * 60 * 1000);
      if (daysSinceCreation < 7) {
        riskScore += 15;
        factors.push('New account');
      }

      // Profile completeness
      if (!user.name || !user.image) {
        riskScore += 10;
        factors.push('Incomplete profile');
      }

      // Engagement level
      const engagement = UserUtils.calculateUserEngagement(user);
      if (engagement.level === 'low') {
        riskScore += 25;
        factors.push('Low engagement score');
      }

      const riskLevel: 'low' | 'medium' | 'high' = 
        riskScore >= 60 ? 'high' : riskScore >= 30 ? 'medium' : 'low';

      const recommendedActions: string[] = [];
      if (riskLevel === 'high') {
        recommendedActions.push('Send re-engagement email', 'Offer personalized content');
      } else if (riskLevel === 'medium') {
        recommendedActions.push('Monitor activity', 'Send helpful tips');
      }

      return {
        userId: user._id?.toString() || user.email,
        riskScore: Math.min(100, riskScore),
        riskLevel,
        factors,
        recommendedActions
      };
    });
  }
}

// Permission Management
export class PermissionManager {
  private static rolePermissions: Record<UserRole, Permission[]> = {
    admin: [
      { resource: '*', actions: ['*'] },
    ],
    user: [
      { resource: 'profile', actions: ['read', 'update'] },
      { resource: 'dashboard', actions: ['read'] },
    ]
  };

  /**
   * Validate if user can perform action on resource
   */
  static validateUserAction(user: User, action: string, resource: string): boolean {
    const permissions = this.getUserPermissions(user);

    return permissions.some(permission => {
      const resourceMatch = permission.resource === '*' || permission.resource === resource;
      const actionMatch = permission.actions.includes('*') || permission.actions.includes(action);
      return resourceMatch && actionMatch;
    });
  }

  /**
   * Get all permissions for a user
   */
  static getUserPermissions(user: User): Permission[] {
    return this.rolePermissions[user.role] || [];
  }

  /**
   * Check if user can access specific resource
   */
  static canAccessResource(user: User, resource: string): boolean {
    return this.validateUserAction(user, 'read', resource);
  }

  /**
   * Create audit log entry
   */
  static createAuditLog(
    user: User, 
    action: string, 
    resource: string, 
    details: Record<string, any> = {},
    ipAddress?: string
  ): AuditLog {
    return {
      userId: user._id?.toString() || user.email,
      action,
      resource,
      timestamp: new Date(),
      details,
      ipAddress
    };
  }
}

