// Custom validation functions
export interface ValidationResult {
  valid: boolean;
  errors: string[];
  warnings?: string[];
}

export interface PasswordStrength {
  score: number;
  level: 'weak' | 'medium' | 'strong';
  suggestions: string[];
}

export class UserValidation {
  static validateEmail(email: string): ValidationResult {
    const errors: string[] = [];

    // Basic format check
    const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
    if (!emailRegex.test(email)) {
      errors.push('Invalid email format');
    }

    // Domain blacklist check
    const disposableEmailDomains = ['10minutemail.com', 'tempmail.org', 'guerrillamail.com'];
    const domain = email.split('@')[1]?.toLowerCase();
    if (domain && disposableEmailDomains.includes(domain)) {
      errors.push('Disposable email addresses not allowed');
    }

    // Length check
    if (email.length > 254) {
      errors.push('Email address too long');
    }

    return {
      valid: errors.length === 0,
      errors
    };
  }

  static validatePassword(password: string): PasswordStrength {
    let score = 0;
    const suggestions: string[] = [];

    // Length check
    if (password.length >= 8) score += 25;
    else suggestions.push('Use at least 8 characters');

    if (password.length >= 12) score += 10;

    // Character variety
    if (/[a-z]/.test(password)) score += 15;
    else suggestions.push('Include lowercase letters');

    if (/[A-Z]/.test(password)) score += 15;
    else suggestions.push('Include uppercase letters');

    if (/[0-9]/.test(password)) score += 15;
    else suggestions.push('Include numbers');

    if (/[^A-Za-z0-9]/.test(password)) score += 20;
    else suggestions.push('Include special characters');

    // Common patterns
    if (!/(.)\1{2,}/.test(password)) score += 5; // No repeated characters
    if (!/123|abc|qwe/i.test(password)) score += 5; // No common sequences

    const level: 'weak' | 'medium' | 'strong' = 
      score >= 80 ? 'strong' : score >= 60 ? 'medium' : 'weak';

    return { score, level, suggestions };
  }

  static validateUserUniqueness(user: Partial<any>, existing: any[]): boolean {
    return !existing.some(existingUser => 
      existingUser.email.toLowerCase() === user.email?.toLowerCase()
    );
  }
}

