          variables: { ...content.variables, name: user.name, email: user.email }
        };

        // Simulate email sending
        console.log(`Sending bulk email to: ${user.email}`);

        results.sent++;
      } catch (error) {
        results.failed++;
        results.errors.push({
          email: user.email,
          error: error instanceof Error ? error.message : 'Unknown error'
        });
      }
    }

    return results;
