      const template = this.templates.passwordReset;
      const resetToken = this.generateResetToken();
      const variables = {
        name: user.name,
        resetUrl: `${process.env.NEXTAUTH_URL}/reset-password?token=${resetToken}`
      };

      const content = this.renderTemplate(template, variables);

      console.log('Sending password reset email to:', user.email);

      return {
        success: true,
        messageId: `reset_${Date.now()}_${user.email}`
      };
