        name: user.name,
        status,
        reason
      };

      const content = this.renderTemplate(template, variables);

      console.log('Sending account status email to:', user.email);

      return {
        success: true,
        messageId: `status_${Date.now()}_${user.email}`
      };
    } catch (error) {
      return {
        success: false,
        error: error instanceof Error ? error.message : 'Unknown error'
      };
    }
  }

  /**
   * Render email template with variables
   */
  private static renderTemplate(template: EmailTemplate, variables: Record<string, any>): EmailContent {
    let subject = template.subject;
    let html = template.html;
    let text = template.text;

    // Simple template variable replacement
    Object.entries(variables).forEach(([key, value]) => {
      const regex = new RegExp(`{{${key}}}`, 'g');
      subject = subject.replace(regex, String(value || ''));
      html = html.replace(regex, String(value || ''));
      text = text.replace(regex, String(value || ''));
    });

    return { subject, html, text, variables };
  }

  /**
   * Validate email content
   */
  static validateEmailContent(content: EmailContent): ValidationResult {
    const errors: string[] = [];

    if (!content.subject || content.subject.trim().length === 0) {
      errors.push('Email subject is required');
    }

    if (!content.html && !content.text) {
      errors.push('Email must have either HTML or text content');
    }

    if (content.subject && content.subject.length > 200) {
      errors.push('Email subject too long (max 200 characters)');
    }

    return {
      valid: errors.length === 0,
      errors
    };
  }

  /**
   * Generate password reset token
   */
  private static generateResetToken(): string {
    return Math.random().toString(36).substring(2, 15) + 
           Math.random().toString(36).substring(2, 15);
  }

  /**
   * Get available email templates
   */
  static getAvailableTemplates(): string[] {
    return Object.keys(this.templates);
  }

  /**
   * Get template by name
   */
  static getTemplate(name: string): EmailTemplate | null {
    return this.templates[name] || null;
  }
}

// app/api/admin/users/bulk/route.ts
import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth/next';
import { authOptions } from '../../../auth/[...nextauth]/route';
import { getCollection } from '@/lib/db/mongo';
import { UserUtils } from '@/lib/user-management';
import { EmailService } from '@/lib/email/emailService';
import { bulkOperationSchema } from '@/lib/validations/userSchemas';
import { ObjectId } from 'mongodb';

interface BulkOperationStatus {
  operationId: string;
  status: 'pending' | 'processing' | 'completed' | 'failed';
  progress: number;
  results?: any;
  error?: string;
}

// In-memory storage for operation status (in production, use Redis or database)
const operationStatus = new Map<string, BulkOperationStatus>();

export async function POST(request: NextRequest): Promise<NextResponse> {
  const session = await getServerSession(authOptions);

  if (!session || session.user?.role !== 'admin') {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  try {
    const body = await request.json();
    const validation = bulkOperationSchema.safeParse(body);

    if (!validation.success) {
      return NextResponse.json({
        error: 'Invalid request data',
        details: validation.error.errors
      }, { status: 400 });
    }

    const { type, users, options, notifyUsers, sendWelcomeEmail } = validation.data;

    // Validate operation before processing
    const operationValidation = UserUtils.validateBulkOperation({ type, users, options });
    if (!operationValidation.valid) {
      return NextResponse.json({
        error: 'Operation validation failed',
        details: operationValidation.errors
      }, { status: 400 });
    }

    const operationId = `bulk_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;

    // Initialize operation status
    operationStatus.set(operationId, {
      operationId,
      status: 'pending',
      progress: 0
    });

    // Process operation asynchronously
    processBulkOperation(operationId, type, users, options, notifyUsers, sendWelcomeEmail, session.user.id);

    return NextResponse.json({
      operationId,
      status: 'pending',
      estimatedTime: UserUtils.estimateOperationTime({ type, users, options }),
      message: 'Bulk operation started'
    });

  } catch (error) {
    console.error('Bulk operation error:', error);
    return NextResponse.json({
      error: 'Internal server error',
      message: error instanceof Error ? error.message : 'Unknown error'
    }, { status: 500 });
  }
}

export async function GET(request: NextRequest): Promise<NextResponse> {
  const session = await getServerSession(authOptions);

  if (!session || session.user?.role !== 'admin') {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  const { searchParams } = new URL(request.url);
  const operationId = searchParams.get('operationId');

  if (!operationId) {
    return NextResponse.json({ error: 'Operation ID required' }, { status: 400 });
  }

  const status = operationStatus.get(operationId);
  if (!status) {
    return NextResponse.json({ error: 'Operation not found' }, { status: 404 });
  }

  return NextResponse.json(status);
}

async function processBulkOperation(
  operationId: string,
  type: string,
  users: any[],
  options: any = {},
  notifyUsers: boolean = false,
  sendWelcomeEmail: boolean = true,
  adminId: string
) {
  const status = operationStatus.get(operationId)!;
  status.status = 'processing';
  operationStatus.set(operationId, status);

  try {
    const collection = await getCollection('users');
    const results = {
      success: 0,
      failed: 0,
      errors: [] as Array<{ index: number; error: string }>,
      operationId
    };

    for (let i = 0; i < users.length; i++) {
      const user = users[i];

      try {
        switch (type) {
          case 'create':
            await createUser(collection, user, sendWelcomeEmail);
            break;
          case 'update':
            await updateUser(collection, user);
            break;
          case 'delete':
            await deleteUser(collection, user);
            break;
          case 'activate':
            await updateUserStatus(collection, user, 'active');
            break;
          case 'deactivate':
            await updateUserStatus(collection, user, 'inactive');
            break;
        }

        results.success++;
      } catch (error) {
        results.failed++;
        results.errors.push({
          index: i,
          error: error instanceof Error ? error.message : 'Unknown error'
        });
      }

      // Update progress
      const progress = Math.round(((i + 1) / users.length) * 100);
      status.progress = progress;
      operationStatus.set(operationId, status);
    }

    // Complete operation
    status.status = 'completed';
    status.progress = 100;
    status.results = results;
    operationStatus.set(operationId, status);

    // Send notification email to admin
    if (notifyUsers) {
      await EmailService.sendBulkEmail([{ email: 'admin@example.com', name: 'Admin' }], {
        subject: 'Bulk Operation Completed',
        text: `Operation ${operationId} completed. Success: ${results.success}, Failed: ${results.failed}`,
        variables: {
          operationId,
          operationType: type,
          totalUsers: users.length,
          successCount: results.success,
          failureCount: results.failed
        }
      });
    }

  } catch (error) {
    status.status = 'failed';
    status.error = error instanceof Error ? error.message : 'Unknown error';
    operationStatus.set(operationId, status);
  }
}

async function createUser(collection: any, userData: any, sendWelcome: boolean) {
  const now = new Date();
  const newUser = {
    ...userData,
    createdAt: now,
    updatedAt: now,
  };

  const result = await collection.insertOne(newUser);

  if (sendWelcome) {
    await EmailService.sendWelcomeEmail(newUser);
  }

  return result;
}

async function updateUser(collection: any, userData: any) {
  const { id, ...updateData } = userData;
  return await collection.updateOne(
    { _id: new ObjectId(id) },
    { $set: { ...updateData, updatedAt: new Date() } }
  );
}

async function deleteUser(collection: any, userData: any) {
  return await collection.deleteOne({ _id: new ObjectId(userData.id) });
}

async function updateUserStatus(collection: any, userData: any, status: string) {
  return await collection.updateOne(
    { _id: new ObjectId(userData.id) },
    { $set: { status, updatedAt: new Date() } }
  );
}

// app/api/admin/users/analytics/route.ts
export async function GET(request: NextRequest): Promise<NextResponse> {
  const session = await getServerSession(authOptions);

  if (!session || session.user?.role !== 'admin') {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  try {
    const { searchParams } = new URL(request.url);
    const period = searchParams.get('period') as 'daily' | 'weekly' | 'monthly' || 'monthly';
    const segment = searchParams.get('segment');
    const startDate = searchParams.get('startDate');
    const endDate = searchParams.get('endDate');

    const collection = await getCollection('users');

    // Build query filters
    const query: any = {};
    if (startDate && endDate) {
      query.createdAt = {
        $gte: new Date(startDate),
        $lte: new Date(endDate)
      };
    }

    const users = await collection.find(query).toArray();
    const sanitizedUsers = users.map(user => UserUtils.sanitizeUserData(user));

    // Generate analytics
    const analytics = {
      overview: {
        totalUsers: users.length,
        activeUsers: users.filter(u => u.status === 'active').length,
        adminUsers: users.filter(u => u.role === 'admin').length,
        newUsersThisMonth: users.filter(u => {
          const monthAgo = new Date();
          monthAgo.setMonth(monthAgo.getMonth() - 1);
          return u.createdAt > monthAgo;
        }).length
      },
      retention: UserAnalytics.calculateRetentionRates(sanitizedUsers, period),
      segments: UserAnalytics.generateUserSegments(sanitizedUsers),
      churnPrediction: UserAnalytics.predictUserChurn(sanitizedUsers),
      engagement: users.map(user => ({
        userId: user._id.toString(),
        engagement: UserUtils.calculateUserEngagement(UserUtils.sanitizeUserData(user))
      }))
    };

    // Cache results for 1 hour
    const response = NextResponse.json(analytics);
    response.headers.set('Cache-Control', 'public, max-age=3600, stale-while-revalidate=1800');

    return response;

  } catch (error) {
    console.error('Analytics error:', error);
    return NextResponse.json({
      error: 'Failed to generate analytics',
      message: error instanceof Error ? error.message : 'Unknown error'
    }, { status: 500 });
  }
}

// app/api/admin/users/import/route.ts
export async function POST(request: NextRequest): Promise<NextResponse> {
  const session = await getServerSession(authOptions);

  if (!session || session.user?.role !== 'admin') {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  try {
    const formData = await request.formData();
    const file = formData.get('file') as File;
    const optionsJson = formData.get('options') as string;

    if (!file) {
      return NextResponse.json({ error: 'No file provided' }, { status: 400 });
    }

    const options = optionsJson ? JSON.parse(optionsJson) : {};
    const fileContent = await file.text();

    // Parse file based on type
    let userData: any[] = [];
    const fileExtension = file.name.split('.').pop()?.toLowerCase();

    switch (fileExtension) {
      case 'csv':
        userData = parseCSV(fileContent);
        break;
      case 'json':
        userData = JSON.parse(fileContent);
        break;
      default:
        return NextResponse.json({ error: 'Unsupported file format' }, { status: 400 });
    }

    // Validate and process data
    const processedData = processImportData(userData, options);

    // Create bulk operation
    const operationId = `import_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`;

    // Start background processing
    processImportOperation(operationId, processedData, options, session.user.id);

    return NextResponse.json({
      operationId,
      recordsFound: userData.length,
      recordsToProcess: processedData.length,
      message: 'Import started'
    });

  } catch (error) {
    console.error('Import error:', error);
    return NextResponse.json({
      error: 'Import failed',
      message: error instanceof Error ? error.message : 'Unknown error'
    }, { status: 500 });
  }
}

function parseCSV(content: string): any[] {
  const lines = content.split('\n').filter(line => line.trim());
  if (lines.length < 2) return [];

  const headers = lines[0].split(',').map(h => h.trim());
  const data = [];

  for (let i = 1; i < lines.length; i++) {
    const values = lines[i].split(',').map(v => v.trim());
    const record: any = {};

    headers.forEach((header, index) => {
      record[header] = values[index] || '';
    });

    data.push(record);
  }

  return data;
}

function processImportData(data: any[], options: any): any[] {
  return data
    .filter(record => record.email && record.name) // Basic validation
    .map(record => ({
      name: record.name?.trim(),
      email: record.email?.toLowerCase().trim(),
      role: record.role || 'user',
      status: record.status || 'active'
    }));
}

async function processImportOperation(
  operationId: string,
  userData: any[],
  options: any,
  adminId: string
) {
  operationStatus.set(operationId, {
    operationId,
    status: 'processing',
    progress: 0
  });

  try {
    const collection = await getCollection('users');
    const results = {
      created: 0,
      updated: 0,
      skipped: 0,
      errors: [] as string[]
    };

    for (let i = 0; i < userData.length; i++) {
      const user = userData[i];

      try {
        // Check if user exists
        const existingUser = await collection.findOne({ email: user.email });

        if (existingUser) {
          if (options.updateExisting) {
            await collection.updateOne(
              { email: user.email },
              { $set: { ...user, updatedAt: new Date() } }
            );
            results.updated++;
          } else {
            results.skipped++;
          }
        } else {
          await collection.insertOne({
            ...user,
            createdAt: new Date(),
            updatedAt: new Date()
          });
          results.created++;

          if (options.sendWelcomeEmails) {
            await EmailService.sendWelcomeEmail(user);
          }
        }
      } catch (error) {
        results.errors.push(`Row ${i + 1}: ${error instanceof Error ? error.message : 'Unknown error'}`);
      }

      // Update progress
      const progress = Math.round(((i + 1) / userData.length) * 100);
      const status = operationStatus.get(operationId)!;
      status.progress = progress;
      operationStatus.set(operationId, status);
    }

    // Complete operation
    const finalStatus = operationStatus.get(operationId)!;
    finalStatus.status = 'completed';
    finalStatus.progress = 100;
    finalStatus.results = results;
    operationStatus.set(operationId, finalStatus);

  } catch (error) {
    const status = operationStatus.get(operationId)!;
    status.status = 'failed';
    status.error = error instanceof Error ? error.message : 'Unknown error';
    operationStatus.set(operationId, status);
  }
}

// app/api/admin/users/export/route.ts
export async function GET(request: NextRequest): Promise<NextResponse> {
  const session = await getServerSession(authOptions);

  if (!session || session.user?.role !== 'admin') {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  try {
    const { searchParams } = new URL(request.url);
    const format = searchParams.get('format') || 'csv';
    const fields = searchParams.get('fields')?.split(',');
    const includeAnalytics = searchParams.get('includeAnalytics') === 'true';

    const collection = await getCollection('users');
    const users = await collection.find({}).toArray();

    const exportData = users.map(user => {
      const sanitized = UserUtils.sanitizeUserData(user);

      if (includeAnalytics) {
        const engagement = UserUtils.calculateUserEngagement(sanitized);
        return {
          ...sanitized,
          engagementScore: engagement.score,
          engagementLevel: engagement.level
        };
      }

      return sanitized;
    });

    // Filter fields if specified
    const finalData = fields ? 
      exportData.map(user => {
        const filtered: any = {};
        fields.forEach(field => {
          if (user.hasOwnProperty(field)) {
            filtered[field] = user[field];
          }
        });
        return filtered;
      }) : exportData;

    let responseData: string;
    let contentType: string;
    let filename: string;

    switch (format.toLowerCase()) {
      case 'json':
        responseData = JSON.stringify(finalData, null, 2);
        contentType = 'application/json';
        filename = `users_export_${Date.now()}.json`;
        break;
      case 'csv':
      default:
        responseData = convertToCSV(finalData);
        contentType = 'text/csv';
        filename = `users_export_${Date.now()}.csv`;
        break;
    }

    return new NextResponse(responseData, {
      headers: {
        'Content-Type': contentType,
        'Content-Disposition': `attachment; filename="${filename}"`,
        'Cache-Control': 'no-cache'
      }
    });

  } catch (error) {
    console.error('Export error:', error);
    return NextResponse.json({
      error: 'Export failed',
      message: error instanceof Error ? error.message : 'Unknown error'
    }, { status: 500 });
  }
}

function convertToCSV(data: any[]): string {
  if (data.length === 0) return '';

  const headers = Object.keys(data[0]);
  const csvContent = [
    headers.join(','),
    ...data.map(row => 
      headers.map(header => {
        const value = row[header];
        return typeof value === 'string' && value.includes(',') 
          ? `"${value}"` 
          : String(value || '');
      }).join(',')
    )
  ].join('\n');

  return csvContent;
}

