// Unit Tests - Analytics Engine
describe('UserAnalytics', () => {
  describe('calculateRetentionRates', () => {
    test('should calculate retention rates correctly', () => {
      const users = createMockUsers(10);
      // Make half of them recently active
      users.slice(0, 5).forEach(user => {
        user.updatedAt = new Date(); // Recently active
      });

      const retention = UserAnalytics.calculateRetentionRates(users, 'monthly');

      expect(retention.totalUsers).toBe(10);
      expect(retention.retentionRate).toBeGreaterThan(0);
      expect(retention.cohorts).toBeDefined();
      expect(retention.period).toBe('monthly');
    });

    test('should handle empty user array', () => {
      const retention = UserAnalytics.calculateRetentionRates([], 'weekly');

      expect(retention.totalUsers).toBe(0);
      expect(retention.retentionRate).toBe(0);
      expect(retention.cohorts).toHaveLength(0);
    });
  });

  describe('generateUserSegments', () => {
    test('should segment users correctly', () => {
      const users = [
        createMockUser({ 
          role: 'admin',
          createdAt: new Date(Date.now() - 2 * 24 * 60 * 60 * 1000), // 2 days ago
          updatedAt: new Date(Date.now() - 1 * 24 * 60 * 60 * 1000)  // 1 day ago
        }),
        createMockUser({ 
          role: 'user',
          createdAt: new Date(Date.now() - 40 * 24 * 60 * 60 * 1000), // 40 days ago
          updatedAt: new Date(Date.now() - 20 * 24 * 60 * 60 * 1000)  // 20 days ago
        })
      ];

      const segments = UserAnalytics.generateUserSegments(users);

      expect(segments.newUsers).toHaveLength(1);
      expect(segments.adminUsers).toHaveLength(1);
      expect(segments.inactiveUsers).toHaveLength(1);
      expect(segments.segments['at-risk']).toHaveLength(1);
    });
  });

  describe('predictUserChurn', () => {
    test('should predict high churn risk for inactive users', () => {
      const inactiveUser = createMockUser({
        updatedAt: new Date(Date.now() - 35 * 24 * 60 * 60 * 1000), // 35 days ago
        createdAt: new Date(Date.now() - 2 * 24 * 60 * 60 * 1000),  // 2 days ago
        image: undefined
      });

      const predictions = UserAnalytics.predictUserChurn([inactiveUser]);

      expect(predictions).toHaveLength(1);
      expect(predictions[0].riskLevel).toBe('high');
      expect(predictions[0].riskScore).toBeGreaterThan(60);
      expect(predictions[0].recommendedActions).toContain('Send re-engagement email');
    });

    test('should predict low churn risk for active users', () => {
      const activeUser = createMockUser({
        role: 'admin',
        updatedAt: new Date(), // Just updated
        createdAt: new Date(Date.now() - 60 * 24 * 60 * 60 * 1000), // 60 days ago
        image: 'avatar.jpg'
      });

      const predictions = UserAnalytics.predictUserChurn([activeUser]);

      expect(predictions[0].riskLevel).toBe('low');
      expect(predictions[0].riskScore).toBeLessThan(30);
    });
  });
});

