// lib/user-management/security.ts
import { User } from '@/types/user';
import { getCollection } from '@/lib/db/mongo';
import crypto from 'crypto';

export interface EncryptedData {
  data: string;
  iv: string;
  tag: string;
}

export interface SecurityAlert {
  id: string;
  userId: string;
  type: 'suspicious_login' | 'multiple_failures' | 'unusual_activity' | 'data_breach';
  severity: 'low' | 'medium' | 'high' | 'critical';
  description: string;
  timestamp: Date;
  resolved: boolean;
  metadata: Record<string, any>;
}

export interface AuditEntry {
  id: string;
  userId: string;
  action: string;
  resource: string;
  timestamp: Date;
  ipAddress?: string;
  userAgent?: string;
  success: boolean;
  details: Record<string, any>;
}

export interface SecurityReport {
  totalAlerts: number;
  criticalAlerts: number;
  unresolvedAlerts: number;
  recentBreaches: number;
  failedLogins: number;
  suspiciousActivities: SecurityAlert[];
  recommendations: string[];
  generatedAt: Date;
}

export class SecurityManager {
  private static readonly ENCRYPTION_ALGORITHM = 'aes-256-gcm';
  private static readonly SECRET_KEY = process.env.ENCRYPTION_KEY || 'default-key-for-development';

  /**
   * Encrypt sensitive data
   */
  static encryptSensitiveData(data: any): EncryptedData {
    try {
      const key = crypto.scryptSync(this.SECRET_KEY, 'salt', 32);
      const iv = crypto.randomBytes(16);
      const cipher = crypto.createCipher(this.ENCRYPTION_ALGORITHM, key);

      let encrypted = cipher.update(JSON.stringify(data), 'utf8', 'hex');
      encrypted += cipher.final('hex');

      return {
        data: encrypted,
        iv: iv.toString('hex'),
        tag: '' // Simplified for demo
      };
    } catch (error) {
      throw new Error(`Encryption failed: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }
  }

  /**
   * Decrypt sensitive data
   */
  static decryptSensitiveData(encryptedData: EncryptedData): any {
    try {
      const key = crypto.scryptSync(this.SECRET_KEY, 'salt', 32);
      const decipher = crypto.createDecipher(this.ENCRYPTION_ALGORITHM, key);

      let decrypted = decipher.update(encryptedData.data, 'hex', 'utf8');
      decrypted += decipher.final('utf8');

      return JSON.parse(decrypted);
    } catch (error) {
      throw new Error(`Decryption failed: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }
  }

  /**
   * Create audit log entry
   */
  static async auditUserAction(
    user: User,
    action: string,
    details: Record<string, any> = {},
    ipAddress?: string,
    userAgent?: string
  ): Promise<AuditEntry> {
    const auditEntry: AuditEntry = {
      id: crypto.randomUUID(),
      userId: user._id?.toString() || user.email,
      action,
      resource: 'user_management',
      timestamp: new Date(),
      ipAddress,
      userAgent,
      success: true,
      details
    };

    try {
      const auditCollection = await getCollection('audit_logs');
      await auditCollection.insertOne(auditEntry);

      // Check for suspicious patterns
      await this.detectSuspiciousActivity(user, action, details);

      return auditEntry;
    } catch (error) {
      console.error('Failed to create audit log:', error);
      auditEntry.success = false;
      return auditEntry;
    }
  }

  /**
   * Detect suspicious activity patterns
   */
  static async detectSuspiciousActivity(
    user: User,
    action: string,
    details: Record<string, any>
  ): Promise<SecurityAlert[]> {
    const alerts: SecurityAlert[] = [];

    try {
      const auditCollection = await getCollection('audit_logs');
      const oneHourAgo = new Date(Date.now() - 60 * 60 * 1000);

      // Check for rapid successive actions
      const recentActions = await auditCollection.countDocuments({
        userId: user._id?.toString() || user.email,
        timestamp: { $gte: oneHourAgo }
      });

      if (recentActions > 50) {
        alerts.push({
          id: crypto.randomUUID(),
          userId: user._id?.toString() || user.email,
          type: 'unusual_activity',
          severity: 'medium',
          description: `User performed ${recentActions} actions in the last hour`,
          timestamp: new Date(),
          resolved: false,
          metadata: { actionCount: recentActions, timeWindow: '1hour' }
        });
      }

      // Check for failed login attempts
      if (action === 'login_failed') {
        const failedLogins = await auditCollection.countDocuments({
          userId: user._id?.toString() || user.email,
          action: 'login_failed',
          timestamp: { $gte: oneHourAgo }
        });

        if (failedLogins >= 5) {
          alerts.push({
            id: crypto.randomUUID(),
            userId: user._id?.toString() || user.email,
            type: 'multiple_failures',
            severity: 'high',
            description: `${failedLogins} failed login attempts in the last hour`,
            timestamp: new Date(),
            resolved: false,
            metadata: { failedAttempts: failedLogins, timeWindow: '1hour' }
          });
        }
      }

      // Store alerts
      if (alerts.length > 0) {
        const alertsCollection = await getCollection('security_alerts');
        await alertsCollection.insertMany(alerts);
      }

      return alerts;
    } catch (error) {
      console.error('Failed to detect suspicious activity:', error);
      return alerts;
    }
  }

  /**
   * Validate data access permissions
   */
  static validateDataAccess(user: User, dataType: string): boolean {
    const dataAccessRules: Record<string, string[]> = {
      'user_profiles': ['admin'],
      'audit_logs': ['admin'],
      'security_alerts': ['admin'],
      'analytics_data': ['admin'],
      'export_data': ['admin'],
      'personal_data': ['admin', 'user'] // Users can access their own data
    };

    const allowedRoles = dataAccessRules[dataType] || [];
    return allowedRoles.includes(user.role);
  }

  /**
   * Generate security report
   */
  static async generateSecurityReport(): Promise<SecurityReport> {
    try {
      const alertsCollection = await getCollection('security_alerts');
      const auditCollection = await getCollection('audit_logs');

      const totalAlerts = await alertsCollection.countDocuments();
      const criticalAlerts = await alertsCollection.countDocuments({ severity: 'critical' });
      const unresolvedAlerts = await alertsCollection.countDocuments({ resolved: false });

      const oneDayAgo = new Date(Date.now() - 24 * 60 * 60 * 1000);
      const recentBreaches = await alertsCollection.countDocuments({
        type: 'data_breach',
        timestamp: { $gte: oneDayAgo }
      });

      const failedLogins = await auditCollection.countDocuments({
        action: 'login_failed',
        timestamp: { $gte: oneDayAgo }
      });

      const suspiciousActivities = await alertsCollection
        .find({ resolved: false })
        .sort({ timestamp: -1 })
        .limit(10)
        .toArray();

      const recommendations = this.generateSecurityRecommendations({
        totalAlerts,
        criticalAlerts,
        unresolvedAlerts,
        recentBreaches,
        failedLogins
      });

      return {
        totalAlerts,
        criticalAlerts,
        unresolvedAlerts,
        recentBreaches,
        failedLogins,
        suspiciousActivities,
        recommendations,
        generatedAt: new Date()
      };
    } catch (error) {
      console.error('Failed to generate security report:', error);
      throw new Error('Security report generation failed');
    }
  }

  /**
   * Generate security recommendations
   */
  private static generateSecurityRecommendations(metrics: {
    totalAlerts: number;
    criticalAlerts: number;
    unresolvedAlerts: number;
    recentBreaches: number;
    failedLogins: number;
  }): string[] {
    const recommendations: string[] = [];

    if (metrics.criticalAlerts > 0) {
      recommendations.push('Address critical security alerts immediately');
    }

    if (metrics.unresolvedAlerts > 10) {
      recommendations.push('Review and resolve pending security alerts');
    }

    if (metrics.failedLogins > 100) {
      recommendations.push('Consider implementing stronger authentication measures');
    }

    if (metrics.recentBreaches > 0) {
      recommendations.push('Conduct security audit and review access controls');
    }

    if (recommendations.length === 0) {
      recommendations.push('Security posture appears healthy');
    }

    return recommendations;
  }
}

// lib/user-management/gdpr.ts
export interface UserDataExport {
  userId: string;
  requestedAt: Date;
  exportId: string;
  data: {
    profile: any;
    auditLogs: AuditEntry[];
    preferences: any;
    metadata: any;
  };
  format: 'json' | 'csv' | 'pdf';
  downloadUrl?: string;
  expiresAt: Date;
}

export interface AnonymizationResult {
  userId: string;
  anonymizedAt: Date;
  fieldsAnonymized: string[];
  retentionPeriod?: number;
  success: boolean;
  errors?: string[];
}

export interface DeletionResult {
  userId: string;
  deletedAt: Date;
  deletedResources: string[];
  success: boolean;
  errors?: string[];
}

export interface ConsentRecord {
  userId: string;
  consentType: 'data_processing' | 'marketing' | 'analytics' | 'cookies';
  granted: boolean;
  timestamp: Date;
  ipAddress?: string;
  version: string;
}

export interface GDPRComplianceReport {
  totalUsers: number;
  dataExportRequests: number;
  deletionRequests: number;
  anonymizationRequests: number;
  consentRecords: number;
  complianceIssues: string[];
  lastAuditDate: Date;
  nextAuditDue: Date;
  generatedAt: Date;
}

export class GDPRManager {
  /**
   * Export all user data for GDPR compliance
   */
  static async exportUserData(userId: string, format: 'json' | 'csv' | 'pdf' = 'json'): Promise<UserDataExport> {
    try {
      const userCollection = await getCollection('users');
      const auditCollection = await getCollection('audit_logs');
      const preferencesCollection = await getCollection('user_preferences');

      // Fetch user data
      const user = await userCollection.findOne({ _id: userId });
      if (!user) {
        throw new Error('User not found');
      }

      // Fetch audit logs
      const auditLogs = await auditCollection
        .find({ userId })
        .sort({ timestamp: -1 })
        .toArray();

      // Fetch preferences
      const preferences = await preferencesCollection.findOne({ userId }) || {};

      const exportData: UserDataExport = {
        userId,
        requestedAt: new Date(),
        exportId: crypto.randomUUID(),
        data: {
          profile: {
            name: user.name,
            email: user.email,
            role: user.role,
            createdAt: user.createdAt,
            updatedAt: user.updatedAt
          },
          auditLogs,
          preferences,
          metadata: {
            totalLogins: auditLogs.filter(log => log.action === 'login').length,
            lastLogin: auditLogs.find(log => log.action === 'login')?.timestamp,
            accountAge: Math.floor((Date.now() - user.createdAt.getTime()) / (1000 * 60 * 60 * 24))
          }
        },
        format,
        expiresAt: new Date(Date.now() + 7 * 24 * 60 * 60 * 1000) // 7 days
      };

      // Store export request
      const exportsCollection = await getCollection('data_exports');
      await exportsCollection.insertOne(exportData);

      return exportData;
    } catch (error) {
      console.error('User data export failed:', error);
      throw new Error(`Data export failed: ${error instanceof Error ? error.message : 'Unknown error'}`);
    }
  }

  /**
   * Anonymize user data while preserving analytics value
   */
  static async anonymizeUserData(userId: string): Promise<AnonymizationResult> {
    const result: AnonymizationResult = {
      userId,
      anonymizedAt: new Date(),
      fieldsAnonymized: [],
      success: false,
      errors: []
    };

    try {
      const userCollection = await getCollection('users');
      const user = await userCollection.findOne({ _id: userId });

      if (!user) {
        result.errors = ['User not found'];
        return result;
      }

      // Fields to anonymize
      const anonymizedData = {
        name: `Anonymous_${Math.random().toString(36).substr(2, 8)}`,
        email: `anon_${Math.random().toString(36).substr(2, 8)}@anonymized.com`,
        image: null,
        updatedAt: new Date()
      };

      // Update user record
      await userCollection.updateOne(
        { _id: userId },
        { $set: anonymizedData }
      );

      // Anonymize audit logs (keep structure but remove identifying info)
      const auditCollection = await getCollection('audit_logs');
      await auditCollection.updateMany(
        { userId },
        { 
          $set: { 
            userId: `anon_${userId}`,
            'details.email': anonymizedData.email,
            'details.name': anonymizedData.name
          }
        }
      );

      result.fieldsAnonymized = ['name', 'email', 'image', 'audit_logs'];
      result.success = true;

      // Log anonymization action
      await SecurityManager.auditUserAction(
        user,
        'data_anonymized',
        { anonymizedFields: result.fieldsAnonymized }
      );

      return result;
    } catch (error) {
      result.errors = [error instanceof Error ? error.message : 'Unknown error'];
      return result;
    }
  }

  /**
   * Completely delete user data
   */
  static async deleteUserData(userId: string): Promise<DeletionResult> {
    const result: DeletionResult = {
      userId,
      deletedAt: new Date(),
      deletedResources: [],
      success: false,
      errors: []
    };

    try {
      // Collections to clean up
      const collections = [
        'users',
        'audit_logs',
        'security_alerts',
        'user_preferences',
        'data_exports',
        'consent_records'
      ];

      for (const collectionName of collections) {
        try {
          const collection = await getCollection(collectionName);
          const deleteResult = await collection.deleteMany({ userId });

          if (deleteResult.deletedCount > 0) {
            result.deletedResources.push(`${collectionName}: ${deleteResult.deletedCount} records`);
          }
        } catch (error) {
          result.errors?.push(`Failed to delete from ${collectionName}: ${error}`);
        }
      }

      result.success = result.errors?.length === 0;
      return result;
    } catch (error) {
      result.errors = [error instanceof Error ? error.message : 'Unknown error'];
      return result;
    }
  }

  /**
   * Track user consent
   */
  static async trackDataConsent(
    userId: string,
    consentType: ConsentRecord['consentType'],
    granted: boolean,
    ipAddress?: string
  ): Promise<ConsentRecord> {
    const consentRecord: ConsentRecord = {
      userId,
      consentType,
      granted,
      timestamp: new Date(),
      ipAddress,
      version: '1.0'
    };

    try {
      const consentCollection = await getCollection('consent_records');
      await consentCollection.insertOne(consentRecord);

      return consentRecord;
    } catch (error) {
      console.error('Failed to track consent:', error);
      throw new Error('Consent tracking failed');
    }
  }

  /**
   * Generate GDPR compliance report
   */
  static async generateGDPRReport(): Promise<GDPRComplianceReport> {
    try {
      const userCollection = await getCollection('users');
      const exportsCollection = await getCollection('data_exports');
      const consentCollection = await getCollection('consent_records');

      const totalUsers = await userCollection.countDocuments();
      const dataExportRequests = await exportsCollection.countDocuments();
      const consentRecords = await consentCollection.countDocuments();

      // Check for compliance issues
      const complianceIssues: string[] = [];

      // Check for users without consent records
      const usersWithoutConsent = await userCollection.countDocuments({
        _id: { $nin: await consentCollection.distinct('userId') }
      });

      if (usersWithoutConsent > 0) {
        complianceIssues.push(`${usersWithoutConsent} users without consent records`);
      }

      // Check for expired export requests
      const expiredExports = await exportsCollection.countDocuments({
        expiresAt: { $lt: new Date() }
      });

      if (expiredExports > 0) {
        complianceIssues.push(`${expiredExports} expired data export requests need cleanup`);
      }

      const lastAuditDate = new Date(Date.now() - 90 * 24 * 60 * 60 * 1000); // 90 days ago
      const nextAuditDue = new Date(Date.now() + 90 * 24 * 60 * 60 * 1000); // 90 days from now

      return {
        totalUsers,
        dataExportRequests,
        deletionRequests: 0, // Would need separate tracking
        anonymizationRequests: 0, // Would need separate tracking
        consentRecords,
        complianceIssues,
        lastAuditDate,
        nextAuditDue,
        generatedAt: new Date()
      };
    } catch (error) {
      console.error('GDPR report generation failed:', error);
      throw new Error('GDPR compliance report generation failed');
    }
  }
}

// lib/error-handling/userManagementErrors.ts
export class UserManagementError extends Error {
  public readonly code: string;
  public readonly statusCode: number;
  public readonly isOperational: boolean;
  public readonly context?: Record<string, any>;

  constructor(
    message: string,
    code: string = 'USER_MANAGEMENT_ERROR',
    statusCode: number = 500,
    isOperational: boolean = true,
    context?: Record<string, any>
  ) {
    super(message);
    this.name = this.constructor.name;
    this.code = code;
    this.statusCode = statusCode;
    this.isOperational = isOperational;
    this.context = context;

    Error.captureStackTrace(this, this.constructor);
  }
}

export class ValidationError extends UserManagementError {
  constructor(message: string, field?: string, value?: any) {
    super(message, 'VALIDATION_ERROR', 400, true, { field, value });
  }
}

export class NotFoundError extends UserManagementError {
  constructor(resource: string, identifier?: string) {
    super(`${resource} not found`, 'NOT_FOUND', 404, true, { resource, identifier });
  }
}

export class ConflictError extends UserManagementError {
  constructor(message: string, conflictingField?: string) {
    super(message, 'CONFLICT', 409, true, { conflictingField });
  }
}

export class SecurityError extends UserManagementError {
  constructor(message: string, securityContext?: Record<string, any>) {
    super(message, 'SECURITY_ERROR', 403, true, securityContext);
  }
}

export class RateLimitError extends UserManagementError {
  constructor(limit: number, window: string) {
    super(`Rate limit exceeded: ${limit} requests per ${window}`, 'RATE_LIMIT', 429, true, { limit, window });
  }
}

export interface ErrorResponse {
  success: false;
  error: {
    code: string;
    message: string;
    details?: any;
    timestamp: string;
    requestId?: string;
  };
}

export class ErrorHandler {
  /**
   * Format error for API response
   */
  static formatError(error: Error, requestId?: string): ErrorResponse {
    if (error instanceof UserManagementError) {
      return {
        success: false,
        error: {
          code: error.code,
          message: error.message,
          details: error.context,
          timestamp: new Date().toISOString(),
          requestId
        }
      };
    }

    // Handle unknown errors
    return {
      success: false,
      error: {
        code: 'INTERNAL_ERROR',
        message: 'An unexpected error occurred',
        timestamp: new Date().toISOString(),
        requestId
      }
    };
  }

  /**
   * Log error with context
   */
  static logError(error: Error, context?: Record<string, any>): void {
    const errorInfo = {
      name: error.name,
      message: error.message,
      stack: error.stack,
      context,
      timestamp: new Date().toISOString()
    };

    if (error instanceof UserManagementError && error.statusCode >= 500) {
      console.error('Critical Error:', errorInfo);
    } else {
      console.warn('Application Error:', errorInfo);
    }
  }

  /**
   * Check if error is operational (expected) vs programming error
   */
  static isOperationalError(error: Error): boolean {
    if (error instanceof UserManagementError) {
      return error.isOperational;
    }
    return false;
  }
}

