async function createLoopPage() {
  console.log('Starting Microsoft Loop automation...');

  // Launch browser
  const browser = await chromium.launch({ 
    headless: false, // Set to true if you don't want to see the browser
    slowMo: 1000 // Slow down actions for visibility
  });

  const context = await browser.newContext();
  const page = await context.newPage();

  try {
    // Navigate to Microsoft Loop
    console.log('Navigating to Microsoft Loop...');
    await page.goto('https://loop.microsoft.com');

    // Wait for page to load
    await page.waitForLoadState('networkidle');

    // You might need to sign in here
    // Uncomment and modify if authentication is required
    /*
    await page.waitForSelector('input[type="email"]', { timeout: 10000 });
    await page.fill('input[type="email"]', 'your-email@domain.com');
    await page.click('input[type="submit"]');
    await page.waitForSelector('input[type="password"]');
    await page.fill('input[type="password"]', 'your-password');
    await page.click('input[type="submit"]');
    */

    // Wait for Loop to fully load
    await page.waitForTimeout(5000);

    // Try to create a new page - multiple selectors as fallbacks
    console.log('Creating new page...');
    const newPageCreated = await createNewPage(page);

    if (!newPageCreated) {
      console.log('Could not create new page automatically. Please create one manually and press Enter to continue...');
      // In a real scenario, you might want to pause here
      await page.waitForTimeout(10000);
    }

    // Wait for editor to be available
