        console.log(`📄 Renamed to "${title}"`);
        await page.waitForTimeout(5000);

        // Focus the editable canvas and clear it
        console.log('📝 Adding content...');

        const canvasSelectors = [
          '[role="textbox"][aria-label*="Canvas"]',
          '[contenteditable="true"]',
          '.canvas',
          '[data-automation-id="canvas"]'
        ];

        let canvasFound = false;
        for (const selector of canvasSelectors) {
          try {
            const canvas = page.locator(selector);
            await canvas.click({ timeout: 5000 });
            console.log(`✅ Found canvas with selector: ${selector}`);
            canvasFound = true;
            break;
          } catch (e) {
            console.log(`❌ Canvas selector "${selector}" not found`);
          }
        }

        if (!canvasFound) {
          await page.screenshot({ path: `debug-8-looking-for-canvas-${i}.png`, fullPage: true });
          throw new Error('Cannot find editable canvas');
        }

        // Clear existing content
        await page.keyboard.press('Control+A');
        await page.keyboard.press('Backspace');
        await page.waitForTimeout(500);

        // Type content
        await page.keyboard.type(content, { delay: 50 });
        console.log(`✍️ Inserted content for "${title}"`);

        // Save explicitly
        await page.keyboard.press('Control+S');
        await page.waitForTimeout(2000);

        console.log(`✅ Completed "${title}"`);

      } catch (err) {
        console.error(`❌ Error with "${title}":`, err.message);
        await page.screenshot({ path: `debug-error-${i}-${title.replace(/[^a-zA-Z0-9]/g, '_')}.png`, fullPage: true });
        // Continue with next hotel instead of stopping
        continue;
      }
    }

    console.log('✅ All done!');

  } catch (error) {
    console.error('❌ Critical error:', error.message);
    await page.screenshot({ path: 'debug-critical-error.png', fullPage: true });
  }

  // Keep browser open for a moment to see the result
  console.log('Keeping browser open for 10 seconds...');
  await page.waitForTimeout(10000);

  await browser.close();
})();

chat_messages.text:
 The issue is with the string interpolation in your selector. You're using single quotes which don't interpolate variables in JavaScript. Here are a few solutions:

## Solution 1: Fix the String Interpolation

Change this:
```javascript
await page.click('text="${title}"');
```

To this (using backticks for template literals):
```javascript
await page.click(`text=${title}`);
```

## Solution 2: More Robust Page Selection

But there's a better approach since the page name might not be exactly what we expect. Here's the improved section:
```
Viewing artifacts created via the Analysis Tool web feature preview isn’t yet supported on mobile.
```

## Solution 3: Alternative Approach - Navigate by Double-Click

If the above doesn't work, you might need to double-click to open the page:

```javascript
// After renaming, double-click to open the page
console.log(`🖱️ Double-clicking to open "${title}"`);
try {
  await page.dblclick(`text=${title}`, { timeout: 10000 });
  await page.waitForTimeout(3000);
} catch (e) {
  console.log('Could not double-click, trying single click...');
  await page.click(`text=${title}`, { timeout: 10000 });
}
```

## Solution 4: Wait for Page Content to Load

You might also need to wait for the page content to actually load:

```javascript
// After clicking on the page, wait for the canvas to be ready
console.log('⏳ Waiting for page content to load...');
await page.waitForLoadState('networkidle');
await page.waitForTimeout(2000);
```

## Complete Fixed Section:

Here's the complete corrected section you can replace in your script:

```javascript
console.log(`📄 Renamed to "${title}"`);
await page.waitForTimeout(3000);

// Click on the newly renamed page to make sure it's selected and opened
console.log(`🔍 Opening the newly created page: "${title}"`);

try {
  // Try double-click first (this often opens the page for editing)
  await page.waitForSelector(`text=${title}`, { timeout: 10000 });
  await page.dblclick(`text=${title}`);
  console.log(`✅ Double-clicked on "${title}"`);
  await page.waitForTimeout(3000);
} catch (e) {
  console.log('Double-click failed, trying single click...');
  try {
    await page.click(`text=${title}`);
    console.log(`✅ Single-clicked on "${title}"`);
    await page.waitForTimeout(2000);
  } catch (e2) {
    console.log('⚠️ Could not click on page, proceeding anyway...');
    await page.screenshot({ path: `debug-cannot-click-page-${i}.png`, fullPage: true });
  }
}

// Wait for page to be ready for editing
await page.waitForLoadState('networkidle');
```

The main issue was using single quotes instead of backticks for string interpolation. Try the updated version and let me know if it works!

