const { chromium } = require('playwright');

(async () => {
  const browser = await chromium.launch({ 
    headless: false, 
    slowMo: 100,
    devtools: true 
  });

  const context = await browser.newContext({ 
    storageState: 'auth.json' 
  });

  const page = await context.newPage();

  // Add console logging
  page.on('console', msg => console.log('PAGE LOG:', msg.text()));

  try {
    console.log('🚀 Starting page sorting...');

    // STEP 1: Open Loop
    await page.goto('https://loop.microsoft.com');
    console.log('📍 Navigated to Loop');

    await page.waitForLoadState('networkidle');

    // STEP 2: Navigate to Positioning & Benefits
    const possibleSelectors = [
      'text=Positioning & Benefits',
      '[aria-label*="Positioning & Benefits"]',
      'div:has-text("Positioning & Benefits")',
      'span:has-text("Positioning & Benefits")',
      'a:has-text("Positioning & Benefits")'
    ];

    let foundPositioningBenefits = false;
    for (const selector of possibleSelectors) {
      try {
        await page.waitForSelector(selector, { timeout: 5000 });
        console.log(`✅ Found "Positioning & Benefits" with selector: ${selector}`);
        await page.click(selector);
        foundPositioningBenefits = true;
        break;
      } catch (e) {
        console.log(`❌ Selector "${selector}" not found`);
      }
    }

    if (!foundPositioningBenefits) {
      throw new Error('Cannot find "Positioning & Benefits"');
    }

    await page.waitForTimeout(3000);
    console.log('✅ Ready to sort pages.');

    // Take screenshot to see current state
    await page.screenshot({ path: 'debug-before-sorting.png', fullPage: true });

    // STEP 3: Get all page elements
    console.log('🔍 Finding all pages...');

    // Try different selectors to find page list items
    const pageListSelectors = [
      '[data-automation-id*="page"]',
      '[role="listitem"]',
      '.page-item',
      '[draggable="true"]',
      'div[title]:not([title=""])',
      'span[title]:not([title=""])'
    ];

    let pageElements = [];
    for (const selector of pageListSelectors) {
      try {
        const elements = await page.$$(selector);
        if (elements.length > 0) {
          console.log(`✅ Found ${elements.length} elements with selector: ${selector}`);
          pageElements = elements;
          break;
        }
      } catch (e) {
        console.log(`❌ Page selector "${selector}" not found`);
      }
    }

    if (pageElements.length === 0) {
      console.log('❌ Could not find page elements. Trying to find by text content...');

      // Get all text elements and filter for hotel names
      const allTextElements = await page.$$('*');
      const hotelNames = [
        'Millennium Hotel and Convention Centre Kuwait',
        'Millennium Hotel and Resort Manuels Taupo', 
        'Millennium Hotel Broadway Times Square',
        'Template' // Include template for reference
      ];

      for (const name of hotelNames) {
        try {
          const elements = await page.$$(`text=${name}`);
          if (elements.length > 0) {
            pageElements.push(...elements);
          }
        } catch (e) {
          console.log(`Could not find page: ${name}`);
        }
      }
    }

    if (pageElements.length === 0) {
      throw new Error('Cannot find any page elements to sort');
    }

    console.log(`📋 Found ${pageElements.length} page elements`);

    // STEP 4: Get page names and their positions
    console.log('📝 Getting page names...');

    const pages = [];
    for (let i = 0; i < pageElements.length; i++) {
      try {
        const element = pageElements[i];

        // Try different ways to get the page name
        let pageName = '';

        // Method 1: Get title attribute
        pageName = await element.getAttribute('title');

        // Method 2: Get text content if no title
        if (!pageName) {
          pageName = await element.textContent();
        }

        // Method 3: Look for nested text elements
        if (!pageName) {
          const textElement = await element.$('span, div');
          if (textElement) {
            pageName = await textElement.textContent();
          }
        }

        if (pageName && pageName.trim()) {
          pages.push({
            name: pageName.trim(),
            element: element,
            originalIndex: i
          });
          console.log(`📄 Found page: "${pageName.trim()}"`);
        }
      } catch (e) {
        console.log(`Could not get name for element ${i}:`, e.message);
      }
    }

    if (pages.length === 0) {
      throw new Error('Could not extract any page names');
    }

    // STEP 5: Sort pages alphabetically (keeping Template at top if it exists)
    console.log('🔤 Sorting pages alphabetically...');

    const templatePages = pages.filter(p => p.name.toLowerCase().includes('template'));
    const hotelPages = pages.filter(p => !p.name.toLowerCase().includes('template'));

    // Sort hotel pages alphabetically
    hotelPages.sort((a, b) => a.name.localeCompare(b.name));

    // Combine: templates first, then sorted hotels
    const sortedPages = [...templatePages, ...hotelPages];

    console.log('📋 Sorted order:');
    sortedPages.forEach((page, index) => {
      console.log(`  ${index + 1}. ${page.name}`);
    });

    // STEP 6: Rearrange pages by drag and drop
    console.log('🔄 Rearranging pages...');

    for (let targetIndex = 0; targetIndex < sortedPages.length; targetIndex++) {
      const pageToMove = sortedPages[targetIndex];
      const currentIndex = pages.findIndex(p => p.name === pageToMove.name);

      if (currentIndex !== targetIndex) {
        console.log(`🔄 Moving "${pageToMove.name}" from position ${currentIndex + 1} to ${targetIndex + 1}`);

        try {
          // Get current positions of source and target
          const sourceElement = pageToMove.element;
          const targetPosition = targetIndex;

          // Method 1: Try drag and drop
          await dragAndDropByPosition(page, sourceElement, targetPosition);

          // Wait for animation/update
          await page.waitForTimeout(2000);

          // Update the pages array to reflect new positions
          const movedPage = pages.splice(currentIndex, 1)[0];
          pages.splice(targetIndex, 0, movedPage);

        } catch (e) {
          console.log(`❌ Could not move "${pageToMove.name}":`, e.message);

          // Try alternative method: right-click and use context menu
          try {
            await movePageUsingContextMenu(page, pageToMove.element, targetIndex);
          } catch (e2) {
            console.log(`❌ Alternative method also failed:`, e2.message);
          }
        }
      }
    }

    console.log('✅ Page sorting completed!');

    // Take final screenshot
    await page.screenshot({ path: 'debug-after-sorting.png', fullPage: true });

  } catch (error) {
    console.error('❌ Error during sorting:', error.message);
    await page.screenshot({ path: 'debug-sorting-error.png', fullPage: true });
  }

  // Keep browser open to see results
  console.log('Keeping browser open for 10 seconds...');
  await page.waitForTimeout(10000);

  await browser.close();
})();

// Helper function for drag and drop
async function dragAndDropByPosition(page, sourceElement, targetIndex) {
  // Get the bounding box of the source element
  const sourceBox = await sourceElement.boundingBox();

  if (!sourceBox) {
    throw new Error('Could not get source element position');
  }

  // Calculate target position (approximate)
  const itemHeight = 40; // Estimated height of each page item
  const targetY = sourceBox.y + (targetIndex * itemHeight);

  // Perform drag and drop
  await page.mouse.move(sourceBox.x + sourceBox.width / 2, sourceBox.y + sourceBox.height / 2);
  await page.mouse.down();
