const { chromium } = require('playwright');
const fs = require('fs');

// Load your auth if you have it
const useAuth = fs.existsSync('auth.json');

(async () => {
  const browser = await chromium.launch({ 
    headless: false, 
    slowMo: 200 // Slower for more reliable interactions
  });

  const context = useAuth 
    ? await browser.newContext({ storageState: 'auth.json' })
    : await browser.newContext();

  const page = await context.newPage();

  try {
    console.log('🚀 Starting realistic page sorting...');

    // Navigate to Loop (adjust URL to your workspace)
    await page.goto('https://loop.cloud.microsoft/');

    // Wait for page to load
    await page.waitForLoadState('networkidle');
    await page.waitForTimeout(3000);

    // Navigate to your workspace (you'll need to adapt this)
    // Based on your script, it looks like you click on a specific workspace
    console.log('📂 Navigating to workspace...');

    // You might need to click on your specific workspace here
    // await page.getByTestId('YOUR_WORKSPACE_ID').click();

    // For now, let's assume we're in the right workspace
    // Take a screenshot to see current state
    await page.screenshot({ path: 'current-page-order.png', fullPage: true });

    // Define the hotels you want to sort (in alphabetical order)
    const desiredOrder = [
      'Template', // Keep template at top
      'Millennium Hotel and Convention Centre Kuwait',
      'Millennium Hotel and Resort Manuels Taupo',
      'Millennium Hotel Broadway Times Square'
      // Add other hotel names as needed
    ];

    console.log('🎯 Target alphabetical order:');
    desiredOrder.forEach((name, index) => {
      console.log(`  ${index + 1}. ${name}`);
    });

    // For each hotel (starting from the one that should be at the top)
    // we'll move it to the correct position

    for (let targetPosition = 0; targetPosition < desiredOrder.length; targetPosition++) {
      const hotelName = desiredOrder[targetPosition];

      console.log(`\n🔄 Processing: "${hotelName}" (target position: ${targetPosition + 1})`);

      try {
        // Find the page element (try multiple selectors)
        let pageElement = null;
        const selectors = [
          `text=${hotelName}`,
          `[title="${hotelName}"]`,
          `[aria-label*="${hotelName}"]`
        ];

        for (const selector of selectors) {
          try {
            await page.waitForSelector(selector, { timeout: 5000 });
            pageElement = page.locator(selector).first();
            console.log(`✅ Found "${hotelName}" with selector: ${selector}`);
            break;
          } catch (e) {
            console.log(`❌ Selector "${selector}" not found for ${hotelName}`);
          }
        }

        if (!pageElement) {
          console.log(`⚠️ Could not find page "${hotelName}", skipping...`);
          continue;
        }

        // Right-click on the page
        console.log(`🖱️ Right-clicking on "${hotelName}"...`);
        await pageElement.click({ button: 'right' });
        await page.waitForTimeout(1000);

        // Click "Rearrange"
        console.log('📋 Clicking Rearrange...');
        const rearrangeSelectors = [
          'button[name="Rearrange"]',
          'text=Rearrange',
          '[role="button"]:has-text("Rearrange")'
        ];

        let rearrangeClicked = false;
        for (const selector of rearrangeSelectors) {
          try {
            await page.click(selector, { timeout: 3000 });
            rearrangeClicked = true;
            console.log(`✅ Clicked Rearrange with: ${selector}`);
            break;
          } catch (e) {
            console.log(`❌ Rearrange selector failed: ${selector}`);
          }
        }

        if (!rearrangeClicked) {
          console.log(`❌ Could not find Rearrange option for ${hotelName}`);
          await page.keyboard.press('Escape'); // Close context menu
          continue;
        }

        await page.waitForTimeout(1000);

        // Now we need to determine how many positions to move
        // This is tricky - we need to know the current position

        // For now, let's use a simple strategy:
        // Move each hotel to the very top, then they'll be in reverse order
        // Then we can fine-tune positions

        if (targetPosition === 0) {
          // Move to top
          console.log(`⬆️ Moving "${hotelName}" to top...`);
          await movePageToTop(page, hotelName);
        } else {
          // Move to correct position by moving up/down
          console.log(`↕️ Moving "${hotelName}" to position ${targetPosition + 1}...`);
          await movePageToPosition(page, hotelName, targetPosition);
        }

        // Close any open menus
        await page.keyboard.press('Escape');
        await page.waitForTimeout(2000);

      } catch (error) {
        console.error(`❌ Error processing "${hotelName}":`, error.message);
        await page.keyboard.press('Escape'); // Close any open menus
        continue;
      }
    }

    console.log('✅ Sorting completed!');
    await page.screenshot({ path: 'final-page-order.png', fullPage: true });

  } catch (error) {
    console.error('❌ Critical error:', error.message);
    await page.screenshot({ path: 'sorting-error.png', fullPage: true });
  }

  console.log('Keeping browser open for 15 seconds to review...');
  await page.waitForTimeout(15000);

  await browser.close();
})();

// Helper function to move page to top
async function movePageToTop(page, pageName) {
  console.log(`⬆️ Moving "${pageName}" to top...`);

  // Click "Move page up" many times until it can't go higher
  for (let i = 0; i < 50; i++) { // Maximum 50 attempts
    try {
      const moveUpSelectors = [
        'text=Move page up',
        '[role="menuitem"]:has-text("Move page up")',
        'button:has-text("Move page up")'
      ];

      let moveUpClicked = false;
      for (const selector of moveUpSelectors) {
        try {
          await page.click(selector, { timeout: 2000 });
          moveUpClicked = true;
          break;
        } catch (e) {
          // Try next selector
        }
      }

      if (!moveUpClicked) {
        console.log(`✅ "${pageName}" reached the top (or move up not available)`);
        break;
      }

      await page.waitForTimeout(300); // Small delay between moves

    } catch (error) {
      console.log(`✅ "${pageName}" reached the top`);
      break;
    }
  }
}

// Helper function to move page to specific position
async function movePageToPosition(page, pageName, targetPosition) {
  console.log(`↕️ Moving "${pageName}" to position ${targetPosition + 1}...`);

  // First move to top
  await movePageToTop(page, pageName);

  // Then move down the required number of positions
  for (let i = 0; i < targetPosition; i++) {
    try {
      const moveDownSelectors = [
        'text=Move page down',
        '[role="menuitem"]:has-text("Move page down")',
        'button:has-text("Move page down")'
      ];

      let moveDownClicked = false;
      for (const selector of moveDownSelectors) {
        try {
          await page.click(selector, { timeout: 2000 });
          moveDownClicked = true;
          console.log(`  ⬇️ Moved down step ${i + 1}/${targetPosition}`);
          break;
        } catch (e) {
          // Try next selector
        }
      }

      if (!moveDownClicked) {
        console.log(`❌ Could not move "${pageName}" down further`);
        break;
      }

      await page.waitForTimeout(300); // Small delay between moves

    } catch (error) {
      console.log(`❌ Error moving "${pageName}" down:`, error.message);
      break;
    }
  }
}

// Alternative: Manual sorting with instructions
async function manualSortWithInstructions(page) {
  console.log(`
  ===============================================
  MANUAL SORTING INSTRUCTIONS:
  ===============================================

  To sort your pages alphabetically:

  1. Right-click on each page
  2. Select "Rearrange"
  3. Use "Move page up" / "Move page down"

  Target order:
  1. Template
  2. Millennium Hotel and Convention Centre Kuwait
  3. Millennium Hotel and Resort Manuels Taupo
  4. Millennium Hotel Broadway Times Square

  ===============================================
  `);

  await page.waitForTimeout(30000);
}

