        addPairDirect(fields[0] || "", fields[1] || "");
      }
    }

    updateViewer();
    showMessage('CSV file imported successfully', 'success');
  }

  function parseCSVLine(line) {
    const fields = [];
    let current = '';
    let inQuotes = false;

    for (let i = 0; i < line.length; i++) {
      const char = line[i];
      const nextChar = line[i + 1];

      if (char === '"') {
        if (inQuotes && nextChar === '"') {
          current += '"';
          i++; // Skip next quote
        } else {
          inQuotes = !inQuotes;
        }
      } else if (char === ',' && !inQuotes) {
        fields.push(current);
        current = '';
      } else {
        current += char;
      }
    }

    fields.push(current);
    return fields;
  }

  function importMarkdown(mdText) {
    const lines = mdText.split(/\r?\n/);
    let currentQ = "", currentA = "";
    let title = lines[0].startsWith("# ") ? lines[0].substring(2) : "Imported";

    saveState();
    document.getElementById('docTitle').value = title;
    document.getElementById('qaBuilder').innerHTML = "";
    selectedPairs.clear();

    for (let i = 1; i < lines.length; i++) {
      const line = lines[i];
      if (line.startsWith("### ")) {
        if (currentQ && currentA) addPairDirect(currentQ, currentA.trim());
        currentQ = line.replace(/^### Question \d+\s*/, "");
        currentA = "";
      } else if (line.startsWith("**Answer:**")) {
        currentA = line.replace("**Answer:**", "").trim();
      } else if (line.trim() === "") {
        continue;
      } else if (currentQ && !currentA) {
        currentA += line + "\n";
      }
    }

    if (currentQ && currentA) addPairDirect(currentQ, currentA.trim());
    updateViewer();
    showMessage('Markdown file imported successfully', 'success');
  }

  function importWord(arrayBuffer) {
    // Basic Word document text extraction
    try {
      const text = extractTextFromWord(arrayBuffer);

      // Try to parse as Q&A format
      const lines = text.split('\n');
      let questions = [];
      let currentQ = "", currentA = "";

      saveState();
      document.getElementById('qaBuilder').innerHTML = "";
      selectedPairs.clear();

      for (let line of lines) {
        line = line.trim();
        if (!line) continue;

        // Look for question patterns
        if (line.match(/^\d+\./) || line.toLowerCase().startsWith('q:') || line.toLowerCase().startsWith('question')) {
          if (currentQ && currentA) {
            addPairDirect(currentQ, currentA);
          }
          currentQ = line.replace(/^\d+\./, '').replace(/^q:/i, '').replace(/^question:?/i, '').trim();
          currentA = "";
        } else if (line.toLowerCase().startsWith('a:') || line.toLowerCase().startsWith('answer')) {
          currentA = line.replace(/^a:/i, '').replace(/^answer:?/i, '').trim();
        } else if (currentQ && !currentA) {
          currentQ += ' ' + line;
        } else if (currentQ && currentA) {
          currentA += ' ' + line;
        }
      }

      if (currentQ && currentA) {
        addPairDirect(currentQ, currentA);
      }

      updateViewer();
      showMessage('Word document imported successfully', 'success');
    } catch (error) {
      alert('Error reading Word document. Please try saving as .txt or .md format.');
    }
  }

  function extractTextFromWord(arrayBuffer) {
    // Simple text extraction from Word docs
    // This is a basic implementation - Word docs are complex
    const uint8Array = new Uint8Array(arrayBuffer);
    let text = '';

    // Look for readable text in the binary data
    for (let i = 0; i < uint8Array.length; i++) {
      const byte = uint8Array[i];
      if (byte >= 32 && byte <= 126) {
        text += String.fromCharCode(byte);
      } else if (byte === 10 || byte === 13) {
        text += '\n';
      }
    }

    // Clean up the extracted text
    text = text.replace(/[^\x20-\x7E\n]/g, ' ');
    text = text.replace(/\s+/g, ' ');
    text = text.replace(/\n\s+/g, '\n');

    return text;
  }

  function addPairDirect(question, answer) {
    // Add pair without saving state (used during imports)
    pairId++;
    const div = document.createElement('div');
    div.className = 'pair';
    div.dataset.id = pairId;
    div.innerHTML = `
      <div class="pair-header">
        <input type="checkbox" class="pair-checkbox" onchange="toggleSelection(this.parentNode.parentNode)">
        <div class="pair-controls">
          <button onclick="saveToBank(this.parentNode.parentNode.parentNode.querySelector('.question').value, this.parentNode.parentNode.parentNode.querySelector('.answer-input').value)">🏦 Save</button>
          <button onclick="confirmDelete(this.parentNode.parentNode.parentNode)">🗑️ Delete</button>
        </div>
      </div>
      <label>Question:</label>
      <textarea class="question" rows="2">${question}</textarea>
      <label>Answer:</label>
      <textarea class="answer-input" rows="2">${answer}</textarea>
    `;
    document.getElementById('qaBuilder').appendChild(div);
  }

  // Utility functions
  function toggleAnswers() {
    answersVisible = !answersVisible;
    document.querySelectorAll('.qa-pair .answer').forEach(a => {
      a.style.display = answersVisible ? 'inline' : 'none';
    });
  }

  function toggleEditor() {
    const editor = document.getElementById('editorPanel');
    const viewer = document.getElementById('qaViewer');
    const toggleBtn = document.getElementById('editToggleBtn');

    const isNowEditing = editor.classList.toggle('collapsed');
    viewer.style.display = isNowEditing ? 'block' : 'none';
    toggleBtn.textContent = isNowEditing ? '✏️ Edit Mode' : '👁️ Preview Mode';
  }

  function handleExportOption(option) {
    if (option === "save") save();
    else if (option === "markdown") exportMarkdown();
    else if (option === "json") exportJSON();
    else if (option === "csv") exportCSV();
    else if (option === "anki") exportAnki();
    else if (option === "print") {
      const wasVisible = answersVisible;
      if (!wasVisible) toggleAnswers();
      window.print();
      if (!wasVisible) toggleAnswers();
    }
    document.getElementById("exportOptions").value = "";
  }

  // Modal and confirmation dialogs
  function showModal(modalId) {
    document.getElementById(modalId).style.display = 'block';
  }

  function hideModal(modalId) {
    document.getElementById(modalId).style.display = 'none';
  }

  function confirmAction(title, message, callback) {
    document.getElementById('confirmTitle').textContent = title;
    document.getElementById('confirmMessage').textContent = message;
    document.getElementById('confirmBtn').onclick = () => {
      hideModal('confirmModal');
      callback();
    };
    showModal('confirmModal');
  }

  function showMessage(message, type = 'info') {
    const statusDiv = document.createElement('div');
    statusDiv.className = `status-message ${type}`;
    statusDiv.textContent = message;
    document.body.appendChild(statusDiv);

    setTimeout(() => statusDiv.classList.add('show'), 100);
    setTimeout(() => {
      statusDiv.classList.remove('show');
      setTimeout(() => statusDiv.remove(), 300);
    }, 3000);
  }

  // Event listeners
  document.getElementById('fileInput').addEventListener('change', function () {
    const file = this.files[0];
    if (!file) return;
    importFile(file);
  });

  document.addEventListener('keyup', e => {
    if (e.target.matches('.question, .answer-input, #docTitle')) {
      updateViewer();
      autoSave();
    }
  });

  document.addEventListener('keydown', e => {
    if (e.ctrlKey || e.metaKey) {
      if (e.key === 'z' && !e.shiftKey) {
        e.preventDefault();
        undo();
      } else if ((e.key === 'y') || (e.key === 'z' && e.shiftKey)) {
        e.preventDefault();
        redo();
      } else if (e.key === 's') {
        e.preventDefault();
        save();
      }
    }
  });

  // Click outside modal to close
  window.onclick = function(event) {
    const modals = document.querySelectorAll('.modal');
    modals.forEach(modal => {
      if (event.target === modal) {
        modal.style.display = 'none';
      }
    });
  };

  // Initialize
  window.addEventListener('load', () => {
    loadAutoSave();
    updateBankDisplay();
    addPair(); // Add initial pair
    updateUndoRedoButtons();
  });

  // Save before page unload
  window.addEventListener('beforeunload', autoSave);
</script>
</body>
</html>

function clearBank() {
  confirmAction('Clear Question Bank', 'This will permanently delete all saved questions. Are you sure?', () => {
    localStorage.removeItem('skillbuilder_bank');
    updateBankDisplay();
    showMessage('Question bank cleared', 'info');
  });
}

function exportQuestionBank() {
  const bank = getQuestionBank();
  if (bank.length === 0) {
    alert('No questions in the bank to export.');
    return;
  }

  const exportData = {
    exportType: 'skillbuilder_questionbank',
    version: '1.0',
    exported: new Date().toISOString(),
    questions: bank
  };

  const filename = `question_bank_${new Date().toISOString().split('T')[0]}.json`;
  downloadFile(JSON.stringify(exportData, null, 2), filename, "application/json");
  showMessage(`Question bank exported: ${bank.length} questions`, 'success');
}

function importQuestionBank(file) {
  const reader = new FileReader();
  reader.onload = function(e) {
    try {
      const data = JSON.parse(e.target.result);

      // Validate the import file
      if (data.exportType !== 'skillbuilder_questionbank') {
        throw new Error('Invalid question bank file format');
      }

      if (!Array.isArray(data.questions)) {
        throw new Error('No questions found in the file');
      }

      // Ask user how to handle existing questions
      const existingBank = getQuestionBank();
      if (existingBank.length > 0) {
        confirmAction(
          'Import Question Bank', 
          `You have ${existingBank.length} questions in your current bank. Do you want to:\n\n• MERGE: Add imported questions to existing ones\n• REPLACE: Replace all existing questions\n\nClick Confirm to MERGE, or Cancel to abort.`, 
          () => {
            // Merge questions
            mergeQuestionBank(data.questions, false);
          }
        );

        // Add a replace option button
        const confirmBtn = document.getElementById('confirmBtn');
        const originalText = confirmBtn.textContent;
        const originalHandler = confirmBtn.onclick;

        // Create replace button
        const replaceBtn = document.createElement('button');
        replaceBtn.textContent = 'Replace All';
        replaceBtn.className = 'btn-primary';
        replaceBtn.style.marginLeft = '10px';
        replaceBtn.style.background = '#dc3545';
        replaceBtn.onclick = () => {
          hideModal('confirmModal');
          mergeQuestionBank(data.questions, true);
        };

        confirmBtn.textContent = 'Merge';
        confirmBtn.parentNode.insertBefore(replaceBtn, confirmBtn.nextSibling);

        // Clean up when modal is closed
        const originalOnClose = () => {
          confirmBtn.textContent = originalText;
          confirmBtn.onclick = originalHandler;
          if (replaceBtn.parentNode) {
            replaceBtn.remove();
          }
        };

        // Override modal close to clean up
        const modal = document.getElementById('confirmModal');
        const originalDisplay = modal.style.display;
        const observer = new MutationObserver(() => {
          if (modal.style.display === 'none' && originalDisplay !== 'none') {
            originalOnClose();
            observer.disconnect();
          }
        });
        observer.observe(modal, { attributes: true, attributeFilter: ['style'] });

      } else {
        // No existing questions, just import
        mergeQuestionBank(data.questions, true);
      }

    } catch (error) {
      alert('Error importing question bank: ' + error.message);
    }
  };
  reader.readAsText(file);
}

function mergeQuestionBank(importedQuestions, replace = false) {
  let bank = replace ? [] : getQuestionBank();
  let addedCount = 0;
  let skippedCount = 0;

  importedQuestions.forEach(importedQ => {
    // Check for duplicates (same question text)
    const isDuplicate = bank.some(existingQ => 
      existingQ.question.toLowerCase().trim() === importedQ.question.toLowerCase().trim()
    );

    if (!isDuplicate) {
      const item = {
        id: Date.now() + Math.random(), // Ensure unique ID
        question: importedQ.question || '',
        answer: importedQ.answer || '',
        created: importedQ.created || new Date().toISOString()
      };
      bank.push(item);
      addedCount++;
    } else {
      skippedCount++;
    }
  });

  localStorage.setItem('skillbuilder_bank', JSON.stringify(bank));
  updateBankDisplay();

  let message = `Import complete: ${addedCount} questions added`;
  if (skippedCount > 0) {
    message += `, ${skippedCount} duplicates skipped`;
  }
  showMessage(message, 'success');
}

