  function importCSV(csvText) {
    const lines = csvText.split('\n');
    const header = lines[0].toLowerCase();

    if (!header.includes('question') || !header.includes('answer')) {
      alert('CSV must have "Question" and "Answer" columns');
      return;
    }

    saveState();
    document.getElementById('qaBuilder').innerHTML = "";
    selectedPairs.clear();

    for (let i = 1; i < lines.length; i++) {
      const line = lines[i].trim();
      if (!line) continue;

      // Simple CSV parsing - handles quoted fields
      const fields = parseCSVLine(line);
      if (fields.length >= 2) {
        addPairDirect(fields[0] || "", fields[1] || "");
      }
    }

    updateViewer();
    switchToPreviewMode();
    showMessage('CSV file imported successfully', 'success');
  }

  function parseCSVLine(line) {
    const fields = [];
    let current = '';
    let inQuotes = false;

    for (let i = 0; i < line.length; i++) {
      const char = line[i];
      const nextChar = line[i + 1];

      if (char === '"') {
        if (inQuotes && nextChar === '"') {
          current += '"';
          i++; // Skip next quote
        } else {
          inQuotes = !inQuotes;
        }
      } else if (char === ',' && !inQuotes) {
        fields.push(current);
        current = '';
      } else {
        current += char;
      }
    }

    fields.push(current);
    return fields;
  }

