        if (currentQ && currentA) addPairDirect(currentQ, currentA.trim());
        currentQ = line.replace(/^### Question \d+\s*/, "");
        currentA = "";
      } else if (line.startsWith("**Answer:**")) {
        currentA = line.replace("**Answer:**", "").trim();
      } else if (line.trim() === "") {
        continue;
      } else if (currentQ && !currentA) {
        currentA += line + "\n";
      }
    }

    if (currentQ && currentA) addPairDirect(currentQ, currentA.trim());
    updateViewer();
    switchToPreviewMode();
    showMessage('Markdown file imported successfully', 'success');
  }

  function importWord(arrayBuffer) {
    // Basic Word document text extraction
    try {
      const text = extractTextFromWord(arrayBuffer);

      // Try to parse as Q&A format
      const lines = text.split('\n');
      let questions = [];
      let currentQ = "", currentA = "";

      saveState();
      document.getElementById('qaBuilder').innerHTML = "";
      selectedPairs.clear();

      for (let line of lines) {
        line = line.trim();
        if (!line) continue;

        // Look for question patterns
        if (line.match(/^\d+\./) || line.toLowerCase().startsWith('q:') || line.toLowerCase().startsWith('question')) {
          if (currentQ && currentA) {
            addPairDirect(currentQ, currentA);
          }
          currentQ = line.replace(/^\d+\./, '').replace(/^q:/i, '').replace(/^question:?/i, '').trim();
          currentA = "";
        } else if (line.toLowerCase().startsWith('a:') || line.toLowerCase().startsWith('answer')) {
          currentA = line.replace(/^a:/i, '').replace(/^answer:?/i, '').trim();
        } else if (currentQ && !currentA) {
          currentQ += ' ' + line;
        } else if (currentQ && currentA) {
          currentA += ' ' + line;
        }
      }

      if (currentQ && currentA) {
        addPairDirect(currentQ, currentA);
      }

      updateViewer();
      switchToPreviewMode();
      showMessage('Word document imported successfully', 'success');
    } catch (error) {
      alert('Error reading Word document. Please try saving as .txt or .md format.');
    }
  }

  function extractTextFromWord(arrayBuffer) {
    // Simple text extraction from Word docs
    // This is a basic implementation - Word docs are complex
    const uint8Array = new Uint8Array(arrayBuffer);
    let text = '';

    // Look for readable text in the binary data
    for (let i = 0; i < uint8Array.length; i++) {
      const byte = uint8Array[i];
      if (byte >= 32 && byte <= 126) {
        text += String.fromCharCode(byte);
      } else if (byte === 10 || byte === 13) {
        text += '\n';
      }
    }

    // Clean up the extracted text
    text = text.replace(/[^\x20-\x7E\n]/g, ' ');
    text = text.replace(/\s+/g, ' ');
    text = text.replace(/\n\s+/g, '\n');

    return text;
  }

  function addPairDirect(question, answer) {
    // Add pair without saving state (used during imports)
    pairId++;
    const div = document.createElement('div');
    div.className = 'pair';
    div.dataset.id = pairId;
    div.innerHTML = `
      <div class="pair-header">
        <input type="checkbox" class="pair-checkbox" onchange="toggleSelection(this.parentNode.parentNode)">
        <div class="pair-controls">
          <button onclick="saveToBank(this.parentNode.parentNode.parentNode.querySelector('.question').value, this.parentNode.parentNode.parentNode.querySelector('.answer-input').value)">🏦 Save</button>
          <button onclick="confirmDelete(this.parentNode.parentNode.parentNode)">🗑️ Delete</button>
        </div>
      </div>
      <label>Question:</label>
      <textarea class="question" rows="2">${question}</textarea>
      <label>Answer:</label>
      <textarea class="answer-input" rows="2">${answer}</textarea>
    `;
    document.getElementById('qaBuilder').appendChild(div);
  }

  // Utility functions
  function toggleAnswers() {
    answersVisible = !answersVisible;
    document.querySelectorAll('.qa-pair .answer').forEach(a => {
      a.style.display = answersVisible ? 'inline' : 'none';
    });
  }

  function toggleEditor() {
    const editor = document.getElementById('editorPanel');
    const viewer = document.getElementById('qaViewer');
    const toggleBtn = document.getElementById('editToggleBtn');

    const isNowEditing = editor.classList.toggle('collapsed');
    viewer.style.display = isNowEditing ? 'block' : 'none';
    toggleBtn.textContent = isNowEditing ? '✏️ Edit Mode' : '👁️ Preview Mode';
  }

  function switchToPreviewMode() {
    const editor = document.getElementById('editorPanel');
    const viewer = document.getElementById('qaViewer');
    const toggleBtn = document.getElementById('editToggleBtn');

    // Switch to preview mode
    editor.classList.add('collapsed');
    viewer.style.display = 'block';
    toggleBtn.textContent = '✏️ Edit Mode';
  }

  function newDocument() {
    // Check if there are unsaved changes
    const pairs = getAllPairs();
    const title = document.getElementById('docTitle').value.trim();

    if (pairs.length > 0 || title) {
      confirmAction('Start New Document', 
        'This will clear all current work. Any unsaved changes will be lost. Are you sure?', 
        () => {
          createNewDocument();
        });
    } else {
      createNewDocument();
    }
  }

  function createNewDocument() {
    // Clear all data
    document.getElementById('docTitle').value = '';
    document.getElementById('scenarioText').value = '';
    document.getElementById('qaBuilder').innerHTML = '';
    document.getElementById('qaViewer').innerHTML = '';

    // Hide scenario section
    document.getElementById('scenarioSection').style.display = 'none';
    document.getElementById('toggleScenarioBtn').textContent = '📝 Add Scenario';
    document.getElementById('toggleScenarioBtn').style.background = '';

    // Reset state
    pairId = 0;
    selectedPairs.clear();
    undoStack = [];
    redoStack = [];
    answersVisible = false;

    // Clear auto-save
    localStorage.removeItem('skillbuilder_autosave');

    // Reset UI
    updateBulkControls();
    updateUndoRedoButtons();

    // Switch to edit mode
    const editor = document.getElementById('editorPanel');
    const viewer = document.getElementById('qaViewer');
    const toggleBtn = document.getElementById('editToggleBtn');

    editor.classList.remove('collapsed');
    viewer.style.display = 'none';
    toggleBtn.textContent = '👁️ Preview Mode';

    // Add initial empty pair
    addPairDirect('', '');

    showMessage('New document created', 'info');
  }

  function handleExportOption(option) {
    if (option === "save") save();
    else if (option === "markdown") exportMarkdown();
    else if (option === "json") exportJSON();
    else if (option === "csv") exportCSV();
    else if (option === "anki") exportAnki();
    else if (option === "print") {
      const wasVisible = answersVisible;
      if (!wasVisible) toggleAnswers();
      window.print();
      if (!wasVisible) toggleAnswers();
    }
    document.getElementById("exportOptions").value = "";
  }

  // Modal and confirmation dialogs
  function showModal(modalId) {
    document.getElementById(modalId).style.display = 'block';
  }

  function hideModal(modalId) {
    document.getElementById(modalId).style.display = 'none';
  }

  function confirmAction(title, message, callback) {
    document.getElementById('confirmTitle').textContent = title;
    document.getElementById('confirmMessage').textContent = message;
    document.getElementById('confirmBtn').onclick = () => {
      hideModal('confirmModal');
      callback();
    };
    showModal('confirmModal');
  }

  function showMessage(message, type = 'info') {
    const statusDiv = document.createElement('div');
    statusDiv.className = `status-message ${type}`;
    statusDiv.textContent = message;
    document.body.appendChild(statusDiv);

    setTimeout(() => statusDiv.classList.add('show'), 100);
    setTimeout(() => {
      statusDiv.classList.remove('show');
      setTimeout(() => statusDiv.remove(), 300);
    }, 3000);
  }

  // Event listeners
  document.getElementById('fileInput').addEventListener('change', function () {
    const file = this.files[0];
    if (!file) return;
    importFile(file);
  });

  document.getElementById('bankImportInput').addEventListener('change', function () {
    const file = this.files[0];
    if (!file) return;
    importQuestionBank(file);
    this.value = ''; // Reset file input
  });

  document.addEventListener('keyup', e => {
    if (e.target.matches('.question, .answer-input, #docTitle, #scenarioText')) {
      updateViewer();
      autoSave();
    }
  });

  document.addEventListener('keydown', e => {
    if (e.ctrlKey || e.metaKey) {
      if (e.key === 'z' && !e.shiftKey) {
        e.preventDefault();
        undo();
      } else if ((e.key === 'y') || (e.key === 'z' && e.shiftKey)) {
        e.preventDefault();
        redo();
      } else if (e.key === 's') {
        e.preventDefault();
        save();
      } else if (e.key === 'n') {
        e.preventDefault();
        newDocument();
      }
    }
  });

  // Click outside modal to close
  window.onclick = function(event) {
    const modals = document.querySelectorAll('.modal');
    modals.forEach(modal => {
      if (event.target === modal) {
        modal.style.display = 'none';
      }
    });
  };

  // Initialize
  window.addEventListener('load', () => {
    loadAutoSave();
    updateBankDisplay();
    addPair(); // Add initial pair
    updateUndoRedoButtons();
  });

  // Save before page unload
  window.addEventListener('beforeunload', autoSave);
</script>
</body>
</html>

