// App.tsx or your root component
import { MantineProvider, createTheme } from '@mantine/core';
import { useComputedColorScheme, useColorScheme } from '@mantine/hooks';
import '@mantine/core/styles.css';

// Create your custom theme (optional)
const theme = createTheme({
  // Your theme customizations here
  primaryColor: 'blue',
  // Add any other theme properties
});

function App() {
  // This will automatically detect the browser's color scheme preference
  const colorScheme = useComputedColorScheme('auto', { 
    getInitialValueInEffect: false 
  });

  return (
    <MantineProvider 
      theme={theme} 
      defaultColorScheme="auto"
      colorSchemeManager={{
        get: (defaultValue) => {
          // Check if we're in the browser environment
          if (typeof window !== 'undefined') {
            return window.matchMedia('(prefers-color-scheme: dark)').matches 
              ? 'dark' 
              : 'light';
          }
          return defaultValue;
        },
        set: () => {}, // We don't need to store anything since we're following system preference
        subscribe: (onUpdate) => {
          // Listen for changes in system color scheme
          if (typeof window !== 'undefined') {
            const mediaQuery = window.matchMedia('(prefers-color-scheme: dark)');
            const handler = (e: MediaQueryListEvent) => {
              onUpdate(e.matches ? 'dark' : 'light');
            };

            mediaQuery.addEventListener('change', handler);
            return () => mediaQuery.removeEventListener('change', handler);
          }
          return () => {};
        },
        clear: () => {}
      }}
    >
      <YourAppContent />
    </MantineProvider>
  );
}

// Alternative simpler approach using just hooks
function SimpleAutoThemeApp() {
  const colorScheme = useComputedColorScheme('auto');

  return (
    <MantineProvider 
      theme={theme} 
      defaultColorScheme="auto"
      forceColorScheme={colorScheme}
    >
      <YourAppContent />
    </MantineProvider>
  );
}

// If you want to access the current color scheme in your components
function SomeComponent() {
  const colorScheme = useComputedColorScheme('auto');

  return (
    <div>
      <p>Current theme: {colorScheme}</p>
      {/* Your component content */}
    </div>
  );
}

export default App;

