const crypto = require('crypto');

// Method 1: Create a one-time password reset script
function resetAdminPassword() {
  const newPassword = 'your-new-admin-password'; // Change this to your desired password
  const salt = crypto.randomBytes(32).toString('hex');
  const iterations = 100000;

  const hashedPassword = crypto.pbkdf2Sync(newPassword, salt, iterations, 64, 'sha512').toString('hex');

  console.log('New password hash:', hashedPassword);
  console.log('Salt:', salt);
  console.log('Iterations:', iterations);

  // Now update your database/storage with these values
  return {
    hash: hashedPassword,
    salt: salt,
    iterations: iterations
  };
}

