                    : 'N/A'
                }
              />
              <MetricItem
                label="Memory"
                value={
                  metrics.memoryUsage
                    ? `${Math.round(metrics.memoryUsage * 100) / 100} MB`
                    : 'N/A'
                }
              />
              <MetricItem
                label="CPU"
                value={
                  metrics.cpuUsage
                    ? `${Math.round(metrics.cpuUsage * 100) / 100}%`
                    : 'N/A'
                }
              />
            </>
          )}

          {title === 'MongoDB' && (
