        <Stack gap="xs">
          <MetricItem label="Status" value={message || 'N/A'} />

          {title === 'Web Server' && (
            <>
              <MetricItem
                label="Uptime"
                value={
                  metrics.uptime
                    ? `${Math.floor(metrics.uptime / 3600)}h ${Math.floor((metrics.uptime % 3600) / 60)}m`
                    : 'N/A'
                }
              />
              <MetricItem
                label="Memory"
                value={
                  metrics.memoryUsage
                    ? `${Math.round(metrics.memoryUsage * 100) / 100} MB`
                    : 'N/A'
                }
              />
              <MetricItem
                label="CPU"
                value={
                  metrics.cpuUsage
                    ? `${Math.round(metrics.cpuUsage * 100) / 100}%`
                    : 'N/A'
                }
              />
            </>
          )}

          {title === 'MongoDB' && (
            <>
              <MetricItem label="Version" value={metrics.version || 'unknown'} />
              <MetricItem
                label="Connections"
                value={metrics.connections?.toString() || '0'}
              />
              <MetricItem
                label="DB Size"
                value={
                  metrics.dbSize !== undefined
                    ? `${Math.round(metrics.dbSize * 100) / 100} MB`
                    : '0 MB'
                }
              />
            </>
          )}

          {title === 'ChromaDB' && (
            <>
              <MetricItem label="Version" value={metrics.version || 'unknown'} />
              <MetricItem
                label="Collections"
                value={metrics.collections?.toString() || '0'}
              />
              <MetricItem
                label="Embeddings"
                value={metrics.totalEmbeddings?.toString() || '0'}
              />
            </>
          )}
        </Stack>
      </Stack>
    </Card>
