            </Group>
          ))}
        </Stack>
      </Stack>
    </Card>
  );

  // Show loading skeleton while data is being fetched
  if (isLoading && !serverStatus) {
    return (
      <Stack gap="xl" p="md">
        {/* Page Header */}
        <div>
          <Title order={1} mb="xs">
            Server Status
          </Title>
          <Text c="dimmed">
