      {/* Status Cards Grid */}
      {serverStatus && (
        <Grid>
          <Grid.Col span={{ base: 12, md: 4 }}>
            <ServiceCard
              title="Web Server"
              subtitle="Next.js Application Server"
              status={serverStatus.webServer.status}
              message={serverStatus.webServer.message}
