import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth';
import { authOptions } from '@/lib/auth';

// MongoDB health check
async function checkMongoDBHealth() {
  try {
    // Import your MongoDB client
    const { MongoClient } = require('mongodb');

    // Use your actual MongoDB connection string
    const client = new MongoClient(process.env.MONGODB_URI);

    // Set a timeout for the connection attempt
    await client.connect();

    // Actually ping the database to verify it's responding
    const adminDb = client.db().admin();
    const result = await adminDb.ping();

    // Get database stats
    const db = client.db(); // or specify your database name
    const stats = await db.stats();
    const serverStatus = await adminDb.serverStatus();

    await client.close();

    return {
      status: 'healthy' as const,
      message: 'MongoDB is connected and responding',
      metrics: {
        version: serverStatus.version,
        connections: serverStatus.connections?.current || 0,
        dbSize: Math.round((stats.dataSize / 1024 / 1024) * 100) / 100, // Convert to MB
      }
    };
  } catch (error) {
    console.error('MongoDB health check failed:', error);
    return {
      status: 'error' as const,
      message: `MongoDB connection failed: ${error.message}`,
      metrics: {
        version: 'unknown',
        connections: 0,
        dbSize: 0,
      }
    };
  }
}

// ChromaDB health check
async function checkChromaDBHealth() {
  try {
    // Replace with your actual ChromaDB endpoint
    const chromaUrl = process.env.CHROMA_URL || 'http://localhost:8000';

    // Test connection with a timeout
    const controller = new AbortController();
    const timeoutId = setTimeout(() => controller.abort(), 5000); // 5 second timeout

    // Try to get ChromaDB version/heartbeat
    const response = await fetch(`${chromaUrl}/api/v1/version`, {
      signal: controller.signal,
      headers: {
        'Content-Type': 'application/json',
      }
    });

    clearTimeout(timeoutId);

    if (!response.ok) {
      throw new Error(`ChromaDB returned status ${response.status}`);
    }

    const versionData = await response.json();

    // Try to list collections to verify it's actually working
    const collectionsResponse = await fetch(`${chromaUrl}/api/v1/collections`, {
      headers: {
        'Content-Type': 'application/json',
      }
    });

    if (!collectionsResponse.ok) {
      throw new Error('Failed to fetch collections');
    }

    const collections = await collectionsResponse.json();

    // Count total embeddings (if your ChromaDB supports this)
    let totalEmbeddings = 0;
    try {
      // This is approximate - you might need to adjust based on your ChromaDB setup
      for (const collection of collections) {
        const countResponse = await fetch(`${chromaUrl}/api/v1/collections/${collection.name}/count`);
        if (countResponse.ok) {
          const countData = await countResponse.json();
          totalEmbeddings += countData.count || 0;
        }
      }
    } catch (countError) {
      console.warn('Could not count embeddings:', countError);
    }

    return {
      status: 'healthy' as const,
      message: 'ChromaDB is connected and responding',
      metrics: {
        version: versionData.version || 'unknown',
        collections: collections.length || 0,
        totalEmbeddings,
      }
    };
  } catch (error) {
    console.error('ChromaDB health check failed:', error);

    // Check if it's a timeout or connection error
    const isConnectionError = error.name === 'AbortError' || 
                             error.message.includes('fetch') ||
                             error.message.includes('ECONNREFUSED');

    return {
      status: 'error' as const,
      message: isConnectionError 
        ? 'ChromaDB is not responding or unreachable'
        : `ChromaDB error: ${error.message}`,
      metrics: {
        version: 'unknown',
        collections: 0,
        totalEmbeddings: 0,
      }
    };
  }
}

// Web Server health check
function checkWebServerHealth() {
  const startTime = process.hrtime.bigint();
  const uptime = process.uptime();
  const memoryUsage = process.memoryUsage();

  // Get CPU usage (simplified)
  const cpuUsage = process.cpuUsage();
  const cpuPercent = (cpuUsage.user + cpuUsage.system) / 1000000; // Convert to milliseconds

  return {
    status: 'healthy' as const,
    message: 'Web server is running normally',
    metrics: {
      uptime,
      memoryUsage: Math.round((memoryUsage.rss / 1024 / 1024) * 100) / 100, // Convert to MB
      cpuUsage: Math.round(cpuPercent * 100) / 100,
    }
  };
}

export async function GET(request: NextRequest) {
  try {
    // Check if user is authenticated and is admin
    const session = await getServerSession(authOptions);

    if (!session || session.user?.role !== 'admin') {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    // Run all health checks in parallel
    const [webServerStatus, mongoStatus, chromaStatus] = await Promise.allSettled([
      Promise.resolve(checkWebServerHealth()),
      checkMongoDBHealth(),
      checkChromaDBHealth(),
    ]);

    // Handle results, treating rejected promises as errors
    const webServer = webServerStatus.status === 'fulfilled' 
      ? webServerStatus.value 
      : { status: 'error', message: 'Web server check failed', metrics: {} };

    const mongodb = mongoStatus.status === 'fulfilled'
      ? mongoStatus.value
      : { status: 'error', message: 'MongoDB check failed', metrics: {} };

    const chromadb = chromaStatus.status === 'fulfilled'
      ? chromaStatus.value
      : { status: 'error', message: 'ChromaDB check failed', metrics: {} };

    const responseData = {
      webServer,
      mongodb,
      chromadb,
      timestamp: new Date().toISOString(),
    };

    return NextResponse.json(responseData);

  } catch (error) {
    console.error('Server status check failed:', error);
    return NextResponse.json(
      { error: 'Failed to check server status' },
      { status: 500 }
    );
  }
}

// Alternative MongoDB health check using Mongoose (if you're using Mongoose)
async function checkMongoDBHealthWithMongoose() {
  try {
    const mongoose = require('mongoose');

    // Check connection state
    if (mongoose.connection.readyState !== 1) {
      throw new Error('MongoDB not connected');
    }

    // Test the connection with a simple operation
    await mongoose.connection.db.admin().ping();

    // Get stats
    const stats = await mongoose.connection.db.stats();
    const adminDb = mongoose.connection.db.admin();
    const serverStatus = await adminDb.serverStatus();

    return {
      status: 'healthy' as const,
      message: 'MongoDB is connected and responding',
      metrics: {
        version: serverStatus.version,
        connections: serverStatus.connections?.current || 0,
        dbSize: Math.round((stats.dataSize / 1024 / 1024) * 100) / 100,
      }
    };
  } catch (error) {
    return {
      status: 'error' as const,
      message: `MongoDB connection failed: ${error.message}`,
      metrics: {
        version: 'unknown',
        connections: 0,
        dbSize: 0,
      }
    };
  }
}

