import React, { useState } from 'react';
import {
  AppShell,
  Navbar,
  Header,
  Text,
  MediaQuery,
  Burger,
  useMantineTheme,
  MantineProvider,
  createTheme,
  NavLink,
  Stack,
  Group,
  ActionIcon,
  Avatar,
  Menu,
  Divider,
  Badge,
  Box
} from '@mantine/core';
import {
  IconDashboard,
  IconUsers,
  IconSettings,
  IconChartBar,
  IconBell,
  IconLogout,
  IconUser,
  IconChevronRight,
  IconHome
} from '@tabler/icons-react';

// Custom theme override
const dashboardTheme = createTheme({
  primaryColor: 'blue',
  colors: {
    // Custom color palette
    brand: [
      '#f0f9ff',
      '#e0f2fe',
      '#bae6fd',
      '#7dd3fc',
      '#38bdf8',
      '#0ea5e9',
      '#0284c7',
      '#0369a1',
      '#075985',
      '#0c4a6e'
    ]
  },
  components: {
    AppShell: {
      styles: {
        root: {
          backgroundColor: '#f8fafc'
        }
      }
    },
    Navbar: {
      styles: {
        root: {
          backgroundColor: '#ffffff',
          borderRight: '1px solid #e2e8f0',
          boxShadow: '0 1px 3px 0 rgba(0, 0, 0, 0.1)'
        }
      }
    },
    Header: {
      styles: {
        root: {
          backgroundColor: '#ffffff',
          borderBottom: '1px solid #e2e8f0',
          boxShadow: '0 1px 3px 0 rgba(0, 0, 0, 0.1)'
        }
      }
    }
  }
});

// Navigation items configuration
const navigationItems = [
  { label: 'Dashboard', icon: IconDashboard, href: '/dashboard', badge: null },
  { label: 'Analytics', icon: IconChartBar, href: '/analytics', badge: 'New' },
  { label: 'Users', icon: IconUsers, href: '/users', badge: null },
  { label: 'Settings', icon: IconSettings, href: '/settings', badge: null }
];

interface DashboardLayoutProps {
  children: React.ReactNode;
  activeItem?: string;
}

export function DashboardLayout({ children, activeItem = 'Dashboard' }: DashboardLayoutProps) {
  const [opened, setOpened] = useState(false);
  const theme = useMantineTheme();

  const navItems = navigationItems.map((item) => (
    <NavLink
      key={item.label}
      href={item.href}
      label={item.label}
      icon={<item.icon size="1rem" stroke={1.5} />}
      rightSection={
        item.badge ? (
          <Badge size="xs" variant="filled" color="red">
            {item.badge}
          </Badge>
        ) : (
          <IconChevronRight size="0.8rem" stroke={1.5} />
        )
      }
      active={activeItem === item.label}
      onClick={() => setOpened(false)}
      styles={{
        root: {
          borderRadius: theme.radius.md,
          margin: '4px 8px',
          '&[data-active]': {
            backgroundColor: theme.colors.brand[0],
            color: theme.colors.brand[7],
            '&:hover': {
              backgroundColor: theme.colors.brand[1]
            }
          }
        }
      }}
    />
  ));

  return (
    <MantineProvider theme={dashboardTheme}>
      <AppShell
        navbarOffsetBreakpoint="sm"
        asideOffsetBreakpoint="sm"
        navbar={{
          width: { sm: 200, lg: 300 },
          collapsed: { mobile: !opened }
        }}
        header={{ height: 70 }}
        padding="md"
      >
        <AppShell.Header>
          <Group h="100%" px="md" justify="space-between">
            <Group>
              <MediaQuery largerThan="sm" styles={{ display: 'none' }}>
                <Burger
                  opened={opened}
                  onClick={() => setOpened((o) => !o)}
                  size="sm"
                  color={theme.colors.gray[6]}
                />
              </MediaQuery>
              <Group spacing="xs">
                <IconHome size={24} color={theme.colors.brand[6]} />
                <Text size="xl" weight={600} color={theme.colors.brand[7]}>
                  Dashboard
                </Text>
              </Group>
            </Group>

            <Group>
              <ActionIcon variant="light" color="gray" size="lg">
                <IconBell size="1.1rem" />
              </ActionIcon>

              <Menu shadow="md" width={200}>
                <Menu.Target>
                  <ActionIcon variant="light" size="lg">
                    <Avatar size="sm" color="blue">
                      JD
                    </Avatar>
                  </ActionIcon>
                </Menu.Target>

                <Menu.Dropdown>
                  <Menu.Label>Account</Menu.Label>
                  <Menu.Item icon={<IconUser size={14} />}>
                    Profile
                  </Menu.Item>
                  <Menu.Item icon={<IconSettings size={14} />}>
                    Settings
                  </Menu.Item>
                  <Menu.Divider />
                  <Menu.Item 
                    icon={<IconLogout size={14} />}
                    color="red"
                  >
                    Logout
                  </Menu.Item>
                </Menu.Dropdown>
              </Menu>
            </Group>
          </Group>
        </AppShell.Header>

        <AppShell.Navbar p="md">
          <AppShell.Section>
            <Text size="xs" weight={500} color="dimmed" tt="uppercase" mb="md">
              Navigation
            </Text>
          </AppShell.Section>

          <AppShell.Section grow>
            <Stack spacing={4}>
              {navItems}
            </Stack>
          </AppShell.Section>

          <AppShell.Section>
            <Divider mb="md" />
            <Box p="xs" style={{ 
              backgroundColor: theme.colors.gray[0], 
              borderRadius: theme.radius.md 
            }}>
              <Text size="xs" color="dimmed" align="center">
                Version 1.0.0
              </Text>
            </Box>
          </AppShell.Section>
        </AppShell.Navbar>

        <AppShell.Main>
          {children}
        </AppShell.Main>
      </AppShell>
    </MantineProvider>
  );
}

