            <Box p="xs" style={{ 
              backgroundColor: '#f8f9fa', 
              borderRadius: '6px' 
            }}>
              <Text size="xs" c="dimmed" ta="center">
                Version 1.0.0
              </Text>
            </Box>
          </AppShell.Section>
        </AppShell.Navbar>

        <AppShell.Main>
          {children}
        </AppShell.Main>
      </AppShell>
    </MantineProvider>
  );
}

