import type { NextApiRequest, NextApiResponse } from 'next';
import fs from 'fs';
import path from 'path';

// This is a simple file-based storage approach
// In a production environment, you'd use a database

const PAGES_DIRECTORY = path.join(process.cwd(), 'data', 'pages');

// Ensure the directory exists
if (!fs.existsSync(PAGES_DIRECTORY)) {
  fs.mkdirSync(PAGES_DIRECTORY, { recursive: true });
}

export default async function handler(
  req: NextApiRequest,
  res: NextApiResponse
) {
  // Handle different HTTP methods
  switch (req.method) {
    case 'GET':
      if (req.query.slug) {
        // Return a specific page
        return getPage(req, res);
      }
      // Return a list of all pages
      return getPages(req, res);

    case 'POST':
      // Create a new page
      return savePage(req, res);

    case 'PUT':
      // Update an existing page
      return updatePage(req, res);

    case 'DELETE':
      // Delete a page
      return deletePage(req, res);

    default:
      return res.status(405).json({ error: 'Method not allowed' });
  }
}

// Get all pages
async function getPages(req: NextApiRequest, res: NextApiResponse) {
  try {
    const files = fs.readdirSync(PAGES_DIRECTORY);
    const pages = files
      .filter(file => file.endsWith('.json'))
      .map(file => {
        const content = fs.readFileSync(path.join(PAGES_DIRECTORY, file), 'utf-8');
        return JSON.parse(content);
      });

    return res.status(200).json(pages);
  } catch (error) {
    console.error('Error getting pages:', error);
    return res.status(500).json({ error: 'Failed to get pages' });
  }
}

// Get a specific page by slug
async function getPage(req: NextApiRequest, res: NextApiResponse) {
  try {
    const { slug } = req.query;
    const filePath = path.join(PAGES_DIRECTORY, `${slug}.json`);

    if (!fs.existsSync(filePath)) {
      return res.status(404).json({ error: 'Page not found' });
    }

    const content = fs.readFileSync(filePath, 'utf-8');
    return res.status(200).json(JSON.parse(content));
  } catch (error) {
    console.error('Error getting page:', error);
    return res.status(500).json({ error: 'Failed to get page' });
  }
}

// Save a new page
async function savePage(req: NextApiRequest, res: NextApiResponse) {
  try {
    const { title, slug, content } = req.body;

    if (!title || !slug || !content) {
      return res.status(400).json({ error: 'Missing required fields' });
    }

    const filePath = path.join(PAGES_DIRECTORY, `${slug}.json`);

    // Check if page already exists
    if (fs.existsSync(filePath)) {
      return res.status(409).json({ error: 'Page with this slug already exists' });
    }

    // Save the page
    const pageData = {
      title,
      slug,
      content,
      createdAt: new Date().toISOString(),
      updatedAt: new Date().toISOString()
    };

    fs.writeFileSync(filePath, JSON.stringify(pageData, null, 2));

    return res.status(201).json(pageData);
  } catch (error) {
    console.error('Error saving page:', error);
    return res.status(500).json({ error: 'Failed to save page' });
  }
}

// Update an existing page
async function updatePage(req: NextApiRequest, res: NextApiResponse) {
  try {
    const { title, slug, content } = req.body;

    if (!title || !slug || !content) {
      return res.status(400).json({ error: 'Missing required fields' });
    }

    const filePath = path.join(PAGES_DIRECTORY, `${slug}.json`);

    // Check if page exists
    if (!fs.existsSync(filePath)) {
      return res.status(404).json({ error: 'Page not found' });
    }

    // Get existing page data
    const existingData = JSON.parse(fs.readFileSync(filePath, 'utf-8'));

    // Update the page
    const pageData = {
      ...existingData,
      title,
      content,
      updatedAt: new Date().toISOString()
    };

    fs.writeFileSync(filePath, JSON.stringify(pageData, null, 2));

    return res.status(200).json(pageData);
  } catch (error) {
    console.error('Error updating page:', error);
    return res.status(500).json({ error: 'Failed to update page' });
  }
}

// Delete a page
async function deletePage(req: NextApiRequest, res: NextApiResponse) {
  try {
    const { slug } = req.query;

    if (!slug) {
      return res.status(400).json({ error: 'Missing slug parameter' });
    }

    const filePath = path.join(PAGES_DIRECTORY, `${slug}.json`);

    // Check if page exists
    if (!fs.existsSync(filePath)) {
      return res.status(404).json({ error: 'Page not found' });
    }

    // Delete the page
    fs.unlinkSync(filePath);

    return res.status(200).json({ message: 'Page deleted successfully' });
  } catch (error) {
    console.error('Error deleting page:', error);
    return res.status(500).json({ error: 'Failed to delete page' });
  }
}

// components/PageRenderer.tsx
import React from 'react';
import { Button, Card, Text, Image, Box, Title } from '@mantine/core';

interface BlockProps {
  type: string;
  props: any;
  content?: any[];
}

interface PageRendererProps {
  pageData: BlockProps[];
}

// This component renders the saved page content
const PageRenderer: React.FC<PageRendererProps> = ({ pageData }) => {
  if (!pageData || !Array.isArray(pageData)) {
    return <div>No content to display</div>;
  }

  const renderBlock = (block: BlockProps) => {
    switch (block.type) {
      case 'heading':
        const level = block.props.level || 1;
        return React.createElement(
          `h${level}`,
          { style: { margin: '0.5em 0' } },
          block.props.content || ''
        );

      case 'paragraph':
        return <Text mb={10}>{block.props.content || ''}</Text>;

      case 'bulletListItem':
        return (
          <Box component="ul" ml={20} mb={10}>
            <li>{block.props.content || ''}</li>
          </Box>
        );

      case 'card':
        return (
          <Card 
            shadow="sm" 
            p="lg" 
            my={15}
            style={{ backgroundColor: block.props.backgroundColor || '#ffffff' }}
          >
            {block.props.imageUrl && (
              <Card.Section>
                <Image 
                  src={block.props.imageUrl} 
                  height={160} 
                  alt={block.props.title} 
                />
              </Card.Section>
            )}
            <Title order={4} mt="md">{block.props.title || 'Card Title'}</Title>
            <Text size="sm" color="dimmed">
              {block.props.description || 'Card description'}
            </Text>
          </Card>
        );

      case 'button':
        return (
          <Button
            color={block.props.color || 'blue'}
            size={block.props.size || 'md'}
            fullWidth={block.props.fullWidth || false}
            my={10}
          >
            {block.props.label || 'Button'}
          </Button>
        );

      default:
        console.warn(`Unknown block type: ${block.type}`);
        return null;
    }
  };

  return (
    <Box>
      {pageData.map((block, index) => (
        <div key={index}>
          {renderBlock(block)}
        </div>
      ))}
    </Box>
  );
};

export default PageRenderer;

