import { GetServerSideProps } from 'next';
import { useState } from 'react';
import { MantineProvider, Container, Title, Text, Box } from '@mantine/core';
import PageRenderer from '../components/PageRenderer';
import path from 'path';
import fs from 'fs';

// Define the component props type
interface PageProps {
  pageData: {
    title: string;
    content: any[];
    createdAt: string;
    updatedAt: string;
  } | null;
  error?: string;
}

// The dynamic page component
export default function DynamicPage({ pageData, error }: PageProps) {
  const [colorScheme] = useState<'light' | 'dark'>('light');

  // Handle error state
  if (error) {
    return (
      <MantineProvider theme={{ colorScheme }} withGlobalStyles withNormalizeCSS>
        <Container size="lg" py="xl">
          <Title order={1} mb="md">Error</Title>
          <Text>{error}</Text>
        </Container>
      </MantineProvider>
    );
  }

  // Handle no data state
  if (!pageData) {
    return (
      <MantineProvider theme={{ colorScheme }} withGlobalStyles withNormalizeCSS>
        <Container size="lg" py="xl">
          <Title order={1} mb="md">Page Not Found</Title>
          <Text>The requested page does not exist.</Text>
        </Container>
      </MantineProvider>
    );
  }

  return (
    <MantineProvider theme={{ colorScheme }} withGlobalStyles withNormalizeCSS>
      <Container size="lg" py="xl">
        <Title order={1} mb="md">{pageData.title}</Title>

        <Box py="md">
          <PageRenderer pageData={pageData.content} />
        </Box>

        <Text size="xs" color="dimmed" mt="xl">
          Last updated: {new Date(pageData.updatedAt).toLocaleString()}
        </Text>
      </Container>
    </MantineProvider>
  );
}

// Server-side rendering function
export const getServerSideProps: GetServerSideProps = async (context) => {
  const { slug } = context.params || {};

  if (!slug || typeof slug !== 'string') {
    return {
      props: {
        pageData: null,
        error: 'Invalid page path'
      }
    };
  }

  try {
    // Get the page data
    // In a production app, you would fetch this from your database
    const PAGES_DIRECTORY = path.join(process.cwd(), 'data', 'pages');
    const filePath = path.join(PAGES_DIRECTORY, `${slug}.json`);

    if (!fs.existsSync(filePath)) {
      return {
        props: {
          pageData: null
        }
      };
    }

    const fileContent = fs.readFileSync(filePath, 'utf-8');
    const pageData = JSON.parse(fileContent);

    return {
      props: {
        pageData
      }
    };
  } catch (error) {
    console.error('Error fetching page:', error);

    return {
      props: {
        pageData: null,
        error: 'Failed to load page data'
      }
    };
  }
}

// components/SavePageModal.tsx
import React, { useState } from 'react';
import {
  Modal,
  TextInput,
  Button,
  Group,
  Stack,
  Text,
  LoadingOverlay
} from '@mantine/core';

interface SavePageModalProps {
  opened: boolean;
  onClose: () => void;
  onSave: (title: string, slug: string) => Promise<void>;
  initialTitle?: string;
  initialSlug?: string;
  isEditing?: boolean;
}

const SavePageModal: React.FC<SavePageModalProps> = ({
  opened,
  onClose,
  onSave,
  initialTitle = '',
  initialSlug = '',
  isEditing = false
}) => {
  const [title, setTitle] = useState(initialTitle);
  const [slug, setSlug] = useState(initialSlug);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Generate slug from title
  const generateSlug = (title: string) => {
    return title
      .toLowerCase()
      .replace(/[^a-z0-9]+/g, '-')
      .replace(/^-|-$/g, '');
  };

  // Handle title change and auto-generate slug if not editing
  const handleTitleChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const newTitle = e.target.value;
    setTitle(newTitle);

    if (!isEditing && !slug) {
      setSlug(generateSlug(newTitle));
    }
  };

  // Handle form submission
  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();

    // Validate inputs
    if (!title.trim()) {
      setError('Title is required');
      return;
    }

    if (!slug.trim()) {
      setError('Slug is required');
      return;
    }

    try {
      setLoading(true);
      setError(null);

      await onSave(title, slug);

      // Close modal after successful save
      onClose();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to save page');
    } finally {
      setLoading(false);
    }
  };

  return (
    <Modal
      opened={opened}
      onClose={onClose}
      title={isEditing ? 'Update Page' : 'Save Page'}
      size="md"
    >
      <form onSubmit={handleSubmit}>
        <LoadingOverlay visible={loading} />

        <Stack spacing="md">
          {error && (
            <Text color="red" size="sm">
              {error}
            </Text>
          )}

          <TextInput
            label="Page Title"
            placeholder="Enter page title"
            value={title}
            onChange={handleTitleChange}
            required
          />

          <TextInput
            label="Page Slug"
            description="This will be used in the URL (e.g., /my-page)"
            placeholder="Enter page slug"
            value={slug}
            onChange={(e) => setSlug(e.target.value)}
            disabled={isEditing}
            required
          />

          <Group position="right" mt="md">
            <Button variant="outline" onClick={onClose}>
              Cancel
            </Button>
            <Button type="submit">
              {isEditing ? 'Update' : 'Save'}
            </Button>
          </Group>
        </Stack>
      </form>
    </Modal>
  );
};

export default SavePageModal;

