// pages/admin/pages/index.tsx
import React, { useState, useEffect } from 'react';
import { NextPage } from 'next';
import { 
  MantineProvider, 
  Container, 
  Title, 
  Table, 
  Button, 
  Group, 
  Text,
  Box,
  ActionIcon,
  Modal,
  LoadingOverlay
} from '@mantine/core';
import Link from 'next/link';
import { useRouter } from 'next/router';
import { IconPencil, IconTrash, IconEye, IconPlus } from '@tabler/icons-react';

interface Page {
  title: string;
  slug: string;
  createdAt: string;
  updatedAt: string;
}

const PagesAdmin: NextPage = () => {
  const router = useRouter();
  const [pages, setPages] = useState<Page[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [deleteModal, setDeleteModal] = useState<{ open: boolean; page: Page | null }>({
    open: false,
    page: null
  });

  // Fetch pages when component mounts
  useEffect(() => {
    fetchPages();
  }, []);

  // Function to fetch pages from API
  const fetchPages = async () => {
    try {
      setLoading(true);
      const response = await fetch('/api/pages');

      if (!response.ok) {
        throw new Error('Failed to fetch pages');
      }

      const data = await response.json();
      setPages(data);
      setError(null);
    } catch (error) {
      console.error('Error fetching pages:', error);
      setError('Failed to load pages. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  // Function to delete a page
  const deletePage = async (slug: string) => {
    try {
      setLoading(true);
      const response = await fetch(`/api/pages?slug=${slug}`, {
        method: 'DELETE'
      });

      if (!response.ok) {
        throw new Error('Failed to delete page');
      }

      // Refresh the page list
      await fetchPages();
      setDeleteModal({ open: false, page: null });
    } catch (error) {
      console.error('Error deleting page:', error);
      setError('Failed to delete page. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  // Function to open delete confirmation modal
  const openDeleteModal = (page: Page) => {
    setDeleteModal({ open: true, page });
  };

  // Function to close delete confirmation modal
  const closeDeleteModal = () => {
    setDeleteModal({ open: false, page: null });
  };

  return (
    <MantineProvider withGlobalStyles withNormalizeCSS>
      <Container size="lg" py="xl">
        <Box pos="relative">
          <LoadingOverlay visible={loading} />

          <Group position="apart" mb="lg">
            <Title order={2}>Pages</Title>
            <Button 
              leftIcon={<IconPlus size={16} />} 
              onClick={() => router.push('/admin/pages/editor')}
            >
              Create New Page
            </Button>
          </Group>

          {error && (
            <Text color="red" mb="md">
              {error}
            </Text>
          )}

          {pages.length === 0 && !loading ? (
            <Text color="dimmed" align="center" py="xl">
              No pages found. Click &quot;Create New Page&quot; to get started.
            </Text>
          ) : (
            <Table striped highlightOnHover>
              <thead>
                <tr>
                  <th>Title</th>
                  <th>Slug</th>
                  <th>Created</th>
                  <th>Updated</th>
                  <th>Actions</th>
                </tr>
              </thead>
              <tbody>
                {pages.map((page) => (
                  <tr key={page.slug}>
                    <td>{page.title}</td>
                    <td>/{page.slug}</td>
                    <td>{new Date(page.createdAt).toLocaleDateString()}</td>
                    <td>{new Date(page.updatedAt).toLocaleDateString()}</td>
                    <td>
                      <Group spacing="xs">
                        <ActionIcon color="blue" component={Link} href={`/${page.slug}`} target="_blank">
                          <IconEye size={16} />
                        </ActionIcon>
                        <ActionIcon color="yellow" component={Link} href={`/admin/pages/editor?slug=${page.slug}`}>
                          <IconPencil size={16} />
                        </ActionIcon>
                        <ActionIcon color="red" onClick={() => openDeleteModal(page)}>
                          <IconTrash size={16} />
                        </ActionIcon>
                      </Group>
                    </td>
                  </tr>
                ))}
              </tbody>
            </Table>
          )}
        </Box>

        {/* Delete Confirmation Modal */}
        <Modal
          opened={deleteModal.open}
          onClose={closeDeleteModal}
          title="Delete Page"
          size="sm"
        >
          <Text mb="lg">
            Are you sure you want to delete &quot;{deleteModal.page?.title}&quot;? This action cannot be undone.
          </Text>

          <Group position="right">
            <Button variant="outline" onClick={closeDeleteModal}>
              Cancel
            </Button>
            <Button 
              color="red" 
              onClick={() => deleteModal.page && deletePage(deleteModal.page.slug)}
            >
              Delete
            </Button>
          </Group>
        </Modal>
      </Container>
    </MantineProvider>
  );
};

export default PagesAdmin;

