import { MantineProvider, ColorSchemeProvider, LoadingOverlay, Box } from '@mantine/core';
import dynamic from 'next/dynamic';

// Use dynamic import with SSR disabled for the editor component
// This is necessary because BlockNote uses browser APIs
const PageEditor = dynamic(
  () => import('../../../components/PageEditor'),
  { ssr: false, loading: () => <LoadingOverlay visible /> }
);

const EditorPage: NextPage = () => {
  const [colorScheme, setColorScheme] = useState<'light' | 'dark'>('light');
