    setColorScheme(value || (colorScheme === 'dark' ? 'light' : 'dark'));
  };

  // Fetch page data if editing an existing page
  useEffect(() => {
    if (slug && typeof slug === 'string') {
      fetchPage(slug);
    } else {
      setLoading(false);
    }
  }, [slug]);

  // Function to fetch page data
  const fetchPage = async (pageSlug: string) => {
