        throw new Error('Failed to fetch page');
      }

      const data = await response.json();
      setPageData(data);
    } catch (error) {
      console.error('Error fetching page:', error);
      // Handle error (e.g., redirect to 404 page)
    } finally {
      setLoading(false);
    }
  };

  return (
    <ColorSchemeProvider
      colorScheme={colorScheme}
