// src/components/layout/Header.tsx
'use client';

import { useState } from 'react';
import {
  Container,
  Group,
  Burger,
  Drawer,
  Stack,
  Text,
  Box,
  Image,
  Anchor,
  Button,
  useMantineTheme,
} from '@mantine/core';
import { useDisclosure } from '@mantine/hooks';
import Link from 'next/link';
import { usePathname } from 'next/navigation';
import classes from './Header.module.css';

const mainLinks = [
  { label: 'Home', href: '/' },
  { label: 'About', href: '/about' },
  { label: 'Shop', href: '/shop' },
  { label: 'Blog', href: '/blog' },
  { label: 'Contact', href: '/contact' },
];

export function Header() {
  const theme = useMantineTheme();
  const pathname = usePathname();
  const [drawerOpened, { toggle: toggleDrawer, close: closeDrawer }] = useDisclosure(false);

  const mainItems = mainLinks.map((item) => {
    const isActive = pathname === item.href;

    return (
      <Link key={item.label} href={item.href} passHref legacyBehavior>
        <Anchor
          component="a"
          className={classes.mainLink}
          data-active={isActive || undefined}
          c={isActive ? 'primary.6' : 'inherit'}
          fw={isActive ? 600 : 500}
        >
          {item.label}
        </Anchor>
      </Link>
    );
  });

  return (
    <Box component="header" className={classes.header}>
      <Container size="xl" h="100%" py="md">
        <Group justify="space-between" h="100%">
          <Link href="/" passHref legacyBehavior>
            <Anchor component="a" underline="never">
              <Group gap="xs">
                <Box w={40} h={40} bg="primary.6" style={{ borderRadius: theme.radius.sm }} />
                <Text fz="xl" fw={700} c="primary.6">Hello Commerce</Text>
              </Group>
            </Anchor>
          </Link>

          <Group gap="xl" visibleFrom="md">
            {mainItems}
          </Group>

          <Group visibleFrom="md">
            <Button variant="outline" radius="md">Sign in</Button>
            <Button radius="md">Sign up</Button>
          </Group>

          <Burger 
            opened={drawerOpened} 
            onClick={toggleDrawer} 
            hiddenFrom="md" 
            size="sm"
          />
        </Group>
      </Container>

      <Drawer
        opened={drawerOpened}
        onClose={closeDrawer}
        title={
          <Group gap="xs">
            <Box w={30} h={30} bg="primary.6" style={{ borderRadius: theme.radius.sm }} />
            <Text fw={700} c="primary.6">Hello Commerce</Text>
          </Group>
        }
        size="100%"
        padding="md"
        hiddenFrom="md"
        zIndex={1000000}
      >
        <Stack gap="lg">
          {mainLinks.map((item) => (
            <Link key={item.label} href={item.href} passHref legacyBehavior>
              <Anchor
                component="a"
                size="lg"
                fw={500}
                c={pathname === item.href ? 'primary.6' : 'inherit'}
                onClick={closeDrawer}
              >
                {item.label}
              </Anchor>
            </Link>
          ))}
          <Group grow>
            <Button variant="outline" radius="md">Sign in</Button>
            <Button radius="md">Sign up</Button>
          </Group>
        </Stack>
      </Drawer>
    </Box>
  );
}

