// File: lib/db/mongo.ts
import { MongoClient, Db, MongoClientOptions, Document } from 'mongodb';

// Global variable to cache the database connection
let cachedClient: MongoClient | null = null;
let cachedDb: Db | null = null;
let connectionState: 'disconnected' | 'connecting' | 'connected' | 'error' = 'disconnected';

/**
 * Get the current connection state
 */
export function getConnectionState(): string {
  return connectionState;
}

/**
 * Connects to MongoDB and returns the database instance.
 * Uses connection pooling through a cached connection.
 */
export async function connectToDatabase(): Promise<{
  client: MongoClient;
  db: Db;
}> {
  // Return cached connection if available and connected
  if (cachedClient && cachedDb && connectionState === 'connected') {
    try {
      // Verify connection is still alive
      await cachedDb.command({ ping: 1 });
      return { client: cachedClient, db: cachedDb };
    } catch (error) {
      console.warn('Cached connection failed ping test, reconnecting...');
      connectionState = 'error';
      cachedClient = null;
      cachedDb = null;
    }
  }

  // Validate environment variables
  if (!process.env.MONGODB_URI) {
    connectionState = 'error';
    throw new Error('MONGODB_URI environment variable is not set');
  }

  if (!process.env.MONGODB_NAME) {
    connectionState = 'error';
    throw new Error('MONGODB_NAME environment variable is not set');
  }

  connectionState = 'connecting';

  const options: MongoClientOptions = {
    maxPoolSize: 10,
    minPoolSize: 1,
    maxIdleTimeMS: 30000,
    serverSelectionTimeoutMS: 5000,
    connectTimeoutMS: 10000,
  };

  try {
    console.log('Connecting to MongoDB...');
    const client = await MongoClient.connect(process.env.MONGODB_URI, options);
    const db = client.db(process.env.MONGODB_NAME);

    // Test the connection
    await db.command({ ping: 1 });

    cachedClient = client;
    cachedDb = db;
    connectionState = 'connected';

    console.log(`✅ Connected to MongoDB database: ${process.env.MONGODB_NAME}`);
    return { client, db };
  } catch (error) {
    connectionState = 'error';
    console.error('❌ MongoDB connection error:', error);
    throw new Error(`Failed to connect to MongoDB: ${error instanceof Error ? error.message : 'Unknown error'}`);
  }
}

/**
 * Get a reference to a specific collection with type safety
 */
export async function getCollection<T extends Document = Document>(
  collectionName: string,
) {
  const { db } = await connectToDatabase();
  return db.collection<T>(collectionName);
}

/**
 * Check MongoDB health status
 */
export async function checkMongoHealth(): Promise<{
  status: 'healthy' | 'unhealthy';
  message: string;
  details?: Record<string, any>;
}> {
  try {
    const { db } = await connectToDatabase();

    // Ping the database
    const pingResult = await db.command({ ping: 1 });

    // Get basic server status
    const serverStatus = await db.command({ serverStatus: 1 });

    // Get database stats
    const dbStats = await db.command({ dbStats: 1 });

    return {
      status: 'healthy',
      message: 'MongoDB is connected and responding',
      details: {
        ping: pingResult.ok === 1,
        version: serverStatus.version,
        uptime: serverStatus.uptime,
        connections: serverStatus.connections?.current || 0,
        dbSize: Math.round((dbStats.dataSize / (1024 * 1024)) * 100) / 100, // MB
        collections: dbStats.collections || 0,
        connectionState,
      },
    };
  } catch (error) {
    const errorMessage = error instanceof Error ? error.message : 'Unknown error';
    return {
      status: 'unhealthy',
      message: `MongoDB health check failed: ${errorMessage}`,
      details: {
        connectionState,
        error: errorMessage,
      },
    };
  }
}

/**
 * Gracefully close database connection
 */
export async function closeDatabaseConnection(): Promise<void> {
  if (cachedClient) {
    try {
      await cachedClient.close();
      console.log('✅ MongoDB connection closed');
    } catch (error) {
      console.error('❌ Error closing MongoDB connection:', error);
    } finally {
      cachedClient = null;
      cachedDb = null;
      connectionState = 'disconnected';
    }
  }
}

/**
 * Get connection statistics
 */
export function getConnectionStats(): {
  hasConnection: boolean;
  connectionState: string;
  isReady: boolean;
} {
  return {
    hasConnection: Boolean(cachedClient && cachedDb),
    connectionState,
    isReady: connectionState === 'connected',
  };
}

