import { ChromaClient, Collection } from 'chromadb';

let cachedClient: ChromaClient | null = null;
let connectionState: 'disconnected' | 'connecting' | 'connected' | 'error' = 'disconnected';

/**
 * Get the current ChromaDB connection state
 */
export function getChromaConnectionState(): string {
  return connectionState;
}

/**
 * Configure and get ChromaDB client with proper error handling
 */
export function getChromaClient(): ChromaClient {
  if (cachedClient && connectionState === 'connected') {
    return cachedClient;
  }

  try {
    connectionState = 'connecting';

    // For development, use default in-memory settings
    // For production, configure with environment variables
    const clientOptions = process.env.CHROMADB_HOST ? {
      path: `http://${process.env.CHROMADB_HOST}:${process.env.CHROMADB_PORT || 8000}`,
    } : {};

    cachedClient = new ChromaClient(clientOptions);
    connectionState = 'connected';

    console.log('✅ ChromaDB client initialized');
    return cachedClient;
  } catch (error) {
    connectionState = 'error';
    console.error('❌ ChromaDB client initialization error:', error);
    throw new Error(`Failed to initialize ChromaDB client: ${error instanceof Error ? error.message : 'Unknown error'}`);
  }
}

/**
 * Initialize or get a collection with proper error handling
 */
export async function getOrCreateCollection(
  collectionName: string,
  metadata?: Record<string, any>
): Promise<Collection> {
  try {
    const client = getChromaClient();

    const collection = await client.getOrCreateCollection({
      name: collectionName,
      metadata: {
        description: `Collection for ${collectionName}`,
        ...metadata,
      },
    });

    console.log(`✅ ChromaDB collection '${collectionName}' ready`);
    return collection;
  } catch (error) {
    console.error(`❌ Error with ChromaDB collection '${collectionName}':`, error);
    throw new Error(`Failed to get/create collection ${collectionName}: ${error instanceof Error ? error.message : 'Unknown error'}`);
  }
}

/**
 * Check ChromaDB health status
 */
export async function checkChromaHealth(): Promise<{
  status: 'healthy' | 'unhealthy';
  message: string;
  details?: Record<string, any>;
}> {
  try {
    const client = getChromaClient();

    // Test basic functionality
    const version = await client.version();

    // Get collections list
    const collections = await client.listCollections();

    // Count total embeddings across all collections
    let totalEmbeddings = 0;
    const collectionDetails: Record<string, number> = {};

    for (const collection of collections) {
      try {
        const coll = await client.getCollection({ name: collection.name });
        const count = await coll.count();
        collectionDetails[collection.name] = count;
        totalEmbeddings += count;
      } catch (error) {
        console.warn(`Could not get count for collection ${collection.name}:`, error);
        collectionDetails[collection.name] = -1; // Indicate error
      }
    }

    return {
      status: 'healthy',
      message: 'ChromaDB is connected and responding',
      details: {
        version,
        connectionState,
        totalCollections: collections.length,
        totalEmbeddings,
        collections: collectionDetails,
        clientReady: Boolean(cachedClient),
      },
    };
  } catch (error) {
    const errorMessage = error instanceof Error ? error.message : 'Unknown error';
    return {
      status: 'unhealthy',
      message: `ChromaDB health check failed: ${errorMessage}`,
      details: {
        connectionState,
        error: errorMessage,
        clientReady: Boolean(cachedClient),
      },
    };
  }
}

/**
 * Reset ChromaDB client connection
 */
export function resetChromaClient(): void {
  try {
    cachedClient = null;
    connectionState = 'disconnected';
    console.log('✅ ChromaDB client reset');
  } catch (error) {
    console.error('❌ Error resetting ChromaDB client:', error);
  }
}

/**
 * Get ChromaDB connection statistics
 */
export function getChromaConnectionStats(): {
  hasClient: boolean;
  connectionState: string;
  isReady: boolean;
} {
  return {
    hasClient: Boolean(cachedClient),
    connectionState,
    isReady: connectionState === 'connected',
  };
}

/**
 * Test ChromaDB connection with a simple operation
 */
export async function testChromaConnection(): Promise<boolean> {
  try {
    const client = getChromaClient();
    await client.version();
    return true;
  } catch (error) {
    console.error('ChromaDB connection test failed:', error);
    return false;
  }
}

