// File: lib/db/mongo.ts
import { MongoClient, Db, MongoClientOptions, Document } from 'mongodb';

// Global variable to cache the database connection
let cachedClient: MongoClient | null = null;
let cachedDb: Db | null = null;

/**
 * Connects to MongoDB and returns the database instance.
 * Uses connection pooling through a cached connection.
 */
export async function connectToDatabase(): Promise<{
  client: MongoClient;
  db: Db;
}> {
  if (cachedClient && cachedDb) {
    return { client: cachedClient, db: cachedDb };
  }

  if (!process.env.MONGODB_URI || !process.env.MONGODB_NAME) {
    throw new Error('MongoDB connection string or database name not provided');
  }

  const options: MongoClientOptions = {
    maxPoolSize: 10,
    minPoolSize: 1,
  };

  try {
    const client = await MongoClient.connect(process.env.MONGODB_URI, options);
    const db = client.db(process.env.MONGODB_NAME);

    cachedClient = client;
    cachedDb = db;

    return { client, db };
  } catch (error) {
    console.error('MongoDB connection error:', error);
    throw new Error('Failed to connect to database');
  }
}

/**
 * Get a reference to a specific collection with type safety
 */
export async function getCollection<T extends Document = Document>(
  collectionName: string,
) {
  const { db } = await connectToDatabase();
  return db.collection<T>(collectionName);
}

/**
 * Simple health check for MongoDB
 */
export async function checkMongoHealth() {
  try {
    const { db } = await connectToDatabase();

    // Ping the database
    await db.command({ ping: 1 });

    return {
      status: 'healthy' as const,
      message: 'MongoDB is connected and responding',
    };
  } catch (error) {
    return {
      status: 'unhealthy' as const,
      message: `MongoDB health check failed: ${error instanceof Error ? error.message : 'Unknown error'}`,
    };
  }
}

/**
 * Gracefully close database connection
 */
export async function closeDatabaseConnection(): Promise<void> {
  if (cachedClient) {
    await cachedClient.close();
    cachedClient = null;
    cachedDb = null;
  }
}

// app/api/health/route.ts
import { NextRequest, NextResponse } from 'next/server';
import { checkMongoHealth } from '@/lib/db/mongo';
import { checkChromaHealth } from '@/lib/db/chroma';

// Define types for health check response
type HealthStatus = 'healthy' | 'warning' | 'error';

interface ServiceHealth {
  status: HealthStatus;
  message: string;
  details?: Record<string, any>;
}

interface HealthCheckResponse {
  status: HealthStatus;
  environment: string;
  version: string;
  timestamp: string;
  services: {
    web: ServiceHealth;
    mongodb: ServiceHealth;
    chromadb: ServiceHealth;
  };
}

interface ErrorResponse {
  status: 'error';
  environment: string;
  version: string;
  timestamp: string;
  error: string;
}

/**
 * Health check API endpoint
 */
export async function GET(req: NextRequest): Promise<NextResponse> {
  const environment = process.env.NODE_ENV || 'development';
  const version = process.env.APP_VERSION || '1.0.0';
  const timestamp = new Date().toISOString();

  try {
    // Run health checks in parallel for efficiency
    const [mongodbHealth, chromadbHealth] = await Promise.all([
      checkMongoHealth(),
      checkChromaHealth(),
    ]);

    // Web server is healthy if we're responding
    const webHealth: ServiceHealth = {
      status: 'healthy',
      message: 'Web server is running normally',
      details: {
        uptime: process.uptime(),
        memory: Math.round(process.memoryUsage().rss / 1024 / 1024), // MB
      },
    };

    // Convert health check results to our format
    const mongoService: ServiceHealth = {
      status: mongodbHealth.status === 'healthy' ? 'healthy' : 'error',
      message: mongodbHealth.message,
      details: mongodbHealth.details,
    };

    const chromaService: ServiceHealth = {
      status: chromadbHealth.status === 'healthy' ? 'healthy' : 'error',
      message: chromadbHealth.message,
      details: chromadbHealth.details,
    };

    // Determine overall system health based on service health
    let overallStatus: HealthStatus = 'healthy';

    if (mongoService.status === 'error' || chromaService.status === 'error') {
      overallStatus = 'error';
    } else if (mongoService.status === 'warning' || chromaService.status === 'warning') {
      overallStatus = 'warning';
    }

    const healthResponse: HealthCheckResponse = {
      status: overallStatus,
      environment,
      version,
      timestamp,
      services: {
        web: webHealth,
        mongodb: mongoService,
        chromadb: chromaService,
      },
    };

    // Set appropriate cache headers to prevent caching
    return NextResponse.json(healthResponse, {
      headers: {
        'Cache-Control': 'no-store, max-age=0',
      },
    });
  } catch (error) {
    console.error('Health check error:', error);

    const errorResponse: ErrorResponse = {
      status: 'error',
      environment,
      version,
      timestamp,
      error: (error as Error).message,
    };

    return NextResponse.json(errorResponse, { status: 500 });
  }
}

