// app/api/admin/users/route.ts
import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth/next';
import { authOptions } from '../../auth/[...nextauth]/route';
import { UserModel } from '@/lib/db/models/mongo/user';
import { ObjectId } from 'mongodb';

export async function GET(request: NextRequest): Promise<NextResponse> {
  // Check authentication
  const session = await getServerSession(authOptions);

  if (!session || session.user?.role !== 'admin') {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  try {
    const { searchParams } = new URL(request.url);
    const page = parseInt(searchParams.get('page') || '1');
    const limit = parseInt(searchParams.get('limit') || '10');
    const search = searchParams.get('search') || '';
    const roleFilter = searchParams.get('role') || '';
    const statusFilter = searchParams.get('status') || '';

    // Build MongoDB query
    const query: any = {};

    // Search filter
    if (search) {
      query.$or = [
        { name: { $regex: search, $options: 'i' } },
        { email: { $regex: search, $options: 'i' } },
      ];
    }

    // Role filter
    if (roleFilter) {
      query.role = roleFilter;
    }

    // Status filter (we'll simulate this with a field or derive it)
    if (statusFilter) {
      // For now, we'll consider all users as 'Active' since we don't have a status field
      // You can add a status field to your User model later if needed
    }

    // Get total count for pagination
    const totalUsers = await UserModel.count(query);

    // Get users with pagination
    const users = await UserModel.findMany(query, {
      skip: (page - 1) * limit,
      limit,
      sort: { createdAt: -1 },
    });

    // Transform users for frontend
    const transformedUsers = users.map(user => ({
      id: user._id?.toString() || '',
      name: user.name,
      email: user.email,
      role: user.role,
      status: 'Active', // Simulated status - you can add this to your User model
      lastLogin: 'Recently', // Simulated - you can add lastLogin to your User model
      avatar: user.name.split(' ').map(n => n[0]).join('').toUpperCase(),
      joinDate: user.createdAt.toLocaleDateString('en-US', {
        year: 'numeric',
        month: 'short',
        day: 'numeric',
      }),
      createdAt: user.createdAt,
      updatedAt: user.updatedAt,
    }));

    return NextResponse.json({
      users: transformedUsers,
      pagination: {
        page,
        limit,
        total: totalUsers,
        pages: Math.ceil(totalUsers / limit),
        hasNext: page < Math.ceil(totalUsers / limit),
        hasPrev: page > 1,
      },
    });
  } catch (error) {
    console.error('Error fetching users:', error);
    return NextResponse.json(
      { error: 'Failed to fetch users' },
      { status: 500 }
    );
  }
}

export async function POST(request: NextRequest): Promise<NextResponse> {
  // Check authentication
  const session = await getServerSession(authOptions);

  if (!session || session.user?.role !== 'admin') {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  try {
    const userData = await request.json();

    // Create new user
    const newUser = await UserModel.create({
      email: userData.email,
      name: userData.name,
      role: userData.role || 'user',
      passwordHash: userData.passwordHash, // This should be properly hashed
    });

    return NextResponse.json({
      message: 'User created successfully',
      user: {
        id: newUser._id?.toString(),
        name: newUser.name,
        email: newUser.email,
        role: newUser.role,
        createdAt: newUser.createdAt,
      },
    });
  } catch (error) {
    console.error('Error creating user:', error);
    return NextResponse.json(
      { error: 'Failed to create user' },
      { status: 500 }
    );
  }
}

export async function PUT(request: NextRequest): Promise<NextResponse> {
  // Check authentication
  const session = await getServerSession(authOptions);

  if (!session || session.user?.role !== 'admin') {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  try {
    const { userId, ...updateData } = await request.json();

    if (!userId) {
      return NextResponse.json({ error: 'User ID is required' }, { status: 400 });
    }

    // Update user
    const updatedUser = await UserModel.update(userId, updateData);

    if (!updatedUser) {
      return NextResponse.json({ error: 'User not found' }, { status: 404 });
    }

    return NextResponse.json({
      message: 'User updated successfully',
      user: {
        id: updatedUser._id?.toString(),
        name: updatedUser.name,
        email: updatedUser.email,
        role: updatedUser.role,
        updatedAt: updatedUser.updatedAt,
      },
    });
  } catch (error) {
    console.error('Error updating user:', error);
    return NextResponse.json(
      { error: 'Failed to update user' },
      { status: 500 }
    );
  }
}

export async function DELETE(request: NextRequest): Promise<NextResponse> {
  // Check authentication
  const session = await getServerSession(authOptions);

  if (!session || session.user?.role !== 'admin') {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  try {
    const { userId } = await request.json();

    if (!userId) {
      return NextResponse.json({ error: 'User ID is required' }, { status: 400 });
    }

    // Delete user
    const deleted = await UserModel.delete(userId);

    if (!deleted) {
      return NextResponse.json({ error: 'User not found' }, { status: 404 });
    }

    return NextResponse.json({
      message: 'User deleted successfully',
    });
  } catch (error) {
    console.error('Error deleting user:', error);
    return NextResponse.json(
      { error: 'Failed to delete user' },
      { status: 500 }
    );
  }
}

import { z } from 'zod';
import { ObjectId } from 'mongodb';
import { getCollection } from '@lib/db/mongo';
import type { User, UserCreateInput, UserUpdateInput } from '@ftypes/user';

const COLLECTION = 'users';

// --- Zod Schemas ---

// Full User object (used for parsing from DB)
export const UserSchema = z.object({
  _id: z.instanceof(ObjectId).optional(),
  email: z.string().email(),
  name: z.string().min(2),
  image: z.string().url().optional(),
  role: z.enum(['user', 'admin']),
  passwordHash: z.string(),
  createdAt: z.date(),
  updatedAt: z.date(),
});

// Schema for incoming POST / create
export const UserCreateSchema = UserSchema.omit({
  _id: true,
  createdAt: true,
  updatedAt: true,
});

// Schema for update (PATCH / PUT)
export const UserUpdateSchema = UserCreateSchema.partial();

// --- Timestamp helper ---
function withTimestamps<T extends object>(
  data: T,
): T & { createdAt: Date; updatedAt: Date } {
  const now = new Date();
  return { ...data, createdAt: now, updatedAt: now };
}

// --- User Model ---
export const UserModel = {
  async create(userData: UserCreateInput): Promise<User> {
    UserCreateSchema.parse(userData);

    const user: User = withTimestamps(userData);

    const collection = await getCollection<User>(COLLECTION);
    const result = await collection.insertOne(user);

    return { ...user, _id: result.insertedId };
  },

  async findById(id: string | ObjectId): Promise<User | null> {
    const collection = await getCollection<User>(COLLECTION);
    const objectId = typeof id === 'string' ? new ObjectId(id) : id;
    return collection.findOne({ _id: objectId });
  },

  async findByEmail(email: string): Promise<User | null> {
    const collection = await getCollection<User>(COLLECTION);
    return collection.findOne({ email });
  },

  async findMany(
    query: any = {},
    options: {
      skip?: number;
      limit?: number;
      sort?: any;
    } = {}
  ): Promise<User[]> {
    const collection = await getCollection<User>(COLLECTION);

    let cursor = collection.find(query);

    if (options.sort) {
      cursor = cursor.sort(options.sort);
    }

    if (options.skip) {
      cursor = cursor.skip(options.skip);
    }

    if (options.limit) {
      cursor = cursor.limit(options.limit);
    }

    return cursor.toArray();
  },

  async count(query: any = {}): Promise<number> {
    const collection = await getCollection<User>(COLLECTION);
    return collection.countDocuments(query);
  },

  async update(
    id: string | ObjectId,
    userData: UserUpdateInput,
  ): Promise<User | null> {
    UserUpdateSchema.parse(userData);

    const objectId = typeof id === 'string' ? new ObjectId(id) : id;
    const collection = await getCollection<User>(COLLECTION);

    const updateData = {
      ...userData,
      updatedAt: new Date(),
    };

    await collection.updateOne({ _id: objectId }, { $set: updateData });

    return this.findById(objectId);
  },

  async delete(id: string | ObjectId): Promise<boolean> {
    const objectId = typeof id === 'string' ? new ObjectId(id) : id;
    const collection = await getCollection<User>(COLLECTION);
    const result = await collection.deleteOne({ _id: objectId });
    return result.deletedCount === 1;
  },

  async getUserStats(): Promise<{
    total: number;
    active: number;
    admins: number;
    recentSignups: number;
  }> {
    const collection = await getCollection<User>(COLLECTION);

    const total = await collection.countDocuments();
    const admins = await collection.countDocuments({ role: 'admin' });

    // Count recent signups (last 7 days)
    const weekAgo = new Date();
    weekAgo.setDate(weekAgo.getDate() - 7);
    const recentSignups = await collection.countDocuments({
      createdAt: { $gte: weekAgo }
    });

    return {
      total,
      active: total, // For now, assume all users are active
      admins,
      recentSignups,
    };
  },
};

'use client';

import React, { useState, useEffect } from 'react';
import {
  Card,
  Text,
  Title,
  Stack,
  Group,
  Badge,
  Avatar,
  ActionIcon,
  TextInput,
  Select,
  Button,
  Table,
  Pagination,
  Menu,
  ThemeIcon,
  SimpleGrid,
  Alert,
  Loader,
  Center,
} from '@mantine/core';
import {
  IconSearch,
  IconPlus,
  IconDots,
  IconEdit,
  IconTrash,
  IconMail,
  IconUsers,
  IconUserCheck,
  IconUserX,
  IconCrown,
  IconAlertCircle,
} from '@tabler/icons-react';

// Types for user data
interface User {
  id: string;
  name: string;
  email: string;
  role: string;
  status: string;
  lastLogin: string;
  avatar: string;
  joinDate: string;
}

interface UserStats {
  total: number;
  active: number;
  admins: number;
  recentSignups: number;
}

interface UsersResponse {
  users: User[];
  pagination: {
    page: number;
    limit: number;
    total: number;
    pages: number;
    hasNext: boolean;
    hasPrev: boolean;
  };
}

export default function Users() {
  const [users, setUsers] = useState<User[]>([]);
  const [userStats, setUserStats] = useState<UserStats | null>(null);
  const [searchTerm, setSearchTerm] = useState('');
  const [roleFilter, setRoleFilter] = useState<string | null>(null);
  const [statusFilter, setStatusFilter] = useState<string | null>(null);
  const [currentPage, setCurrentPage] = useState(1);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [pagination, setPagination] = useState({
    page: 1,
    limit: 10,
    total: 0,
    pages: 0,
    hasNext: false,
    hasPrev: false,
  });

  // Fetch users from API
  const fetchUsers = async () => {
    setLoading(true);
    setError(null);

    try {
      const params = new URLSearchParams({
        page: currentPage.toString(),
        limit: '10',
        ...(searchTerm && { search: searchTerm }),
        ...(roleFilter && { role: roleFilter }),
        ...(statusFilter && { status: statusFilter }),
      });

      const response = await fetch(`/api/admin/users?${params}`);

      if (!response.ok) {
        throw new Error(`Failed to fetch users: ${response.status}`);
      }

      const data: UsersResponse = await response.json();
      setUsers(data.users);
      setPagination(data.pagination);
    } catch (err) {
      setError(err instanceof Error ? err.message : 'An error occurred');
      console.error('Error fetching users:', err);
    } finally {
      setLoading(false);
    }
  };

  // Fetch user statistics
  const fetchUserStats = async () => {
    try {
      const response = await fetch('/api/admin/users/stats');
      if (response.ok) {
        const stats = await response.json();
        setUserStats(stats);
      }
    } catch (err) {
      console.error('Error fetching user stats:', err);
    }
  };

  // Initial load and when filters change
  useEffect(() => {
    fetchUsers();
  }, [currentPage, searchTerm, roleFilter, statusFilter]);

  // Load stats on mount
  useEffect(() => {
    fetchUserStats();
  }, []);

  // Handle search with debounce
  useEffect(() => {
    const timer = setTimeout(() => {
      setCurrentPage(1); // Reset to first page when searching
    }, 300);

    return () => clearTimeout(timer);
  }, [searchTerm]);

  const handleDelete = async (userId: string) => {
    if (!confirm('Are you sure you want to delete this user?')) return;

    try {
      const response = await fetch('/api/admin/users', {
        method: 'DELETE',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ userId }),
      });

      if (response.ok) {
        fetchUsers(); // Refresh the list
        fetchUserStats(); // Refresh stats
      } else {
        throw new Error('Failed to delete user');
      }
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Failed to delete user');
    }
  };

  const statsData = userStats ? [
    {
      title: 'Total Users',
      value: userStats.total.toString(),
      icon: IconUsers,
      color: 'blue',
    },
    {
      title: 'Active Users',
      value: userStats.active.toString(),
      icon: IconUserCheck,
      color: 'green',
    },
    {
      title: 'Recent Signups',
      value: userStats.recentSignups.toString(),
      icon: IconUserX,
      color: 'orange',
    },
    {
      title: 'Admin Users',
      value: userStats.admins.toString(),
      icon: IconCrown,
      color: 'violet',
    },
  ] : [];

  const rows = users.map(user => (
    <Table.Tr key={user.id}>
      <Table.Td>
        <Group gap="sm">
          <Avatar color="blue" radius="xl">
            {user.avatar}
          </Avatar>
          <div>
            <Text fw={500}>{user.name}</Text>
            <Text size="sm" c="dimmed">
              {user.email}
            </Text>
          </div>
        </Group>
      </Table.Td>
      <Table.Td>
        <Badge
          variant="light"
          color={
            user.role === 'admin'
              ? 'red'
              : user.role === 'editor'
                ? 'blue'
                : 'gray'
          }
        >
          {user.role}
        </Badge>
      </Table.Td>
      <Table.Td>
        <Badge
          variant="dot"
          color={
            user.status === 'Active'
              ? 'green'
              : user.status === 'Inactive'
                ? 'red'
                : 'orange'
          }
        >
          {user.status}
        </Badge>
      </Table.Td>
      <Table.Td>
        <Text size="sm">{user.lastLogin}</Text>
      </Table.Td>
      <Table.Td>
        <Text size="sm">{user.joinDate}</Text>
      </Table.Td>
      <Table.Td>
        <Group gap={4}>
          <ActionIcon variant="subtle" color="blue">
            <IconEdit size={16} />
          </ActionIcon>
          <ActionIcon variant="subtle" color="green">
            <IconMail size={16} />
          </ActionIcon>
          <Menu shadow="md" width={200}>
            <Menu.Target>
              <ActionIcon variant="subtle" color="gray">
                <IconDots size={16} />
              </ActionIcon>
            </Menu.Target>
            <Menu.Dropdown>
              <Menu.Item leftSection={<IconEdit size={14} />}>
                Edit User
              </Menu.Item>
              <Menu.Item leftSection={<IconMail size={14} />}>
                Send Email
              </Menu.Item>
              <Menu.Divider />
              <Menu.Item 
                leftSection={<IconTrash size={14} />} 
                color="red"
                onClick={() => handleDelete(user.id)}
              >
                Delete User
              </Menu.Item>
            </Menu.Dropdown>
          </Menu>
        </Group>
      </Table.Td>
    </Table.Tr>
  ));

  if (loading && users.length === 0) {
    return (
      <Stack gap="lg">
        <Group justify="space-between">
          <div>
            <Title order={2}>User Management</Title>
            <Text c="dimmed" size="sm">
              Manage user accounts, roles, and permissions
            </Text>
          </div>
        </Group>
        <Center h={400}>
          <Stack align="center" gap="md">
            <Loader size="lg" />
            <Text>Loading users...</Text>
          </Stack>
        </Center>
      </Stack>
    );
  }

  return (
    <Stack gap="lg">
      <Group justify="space-between">
        <div>
          <Title order={2}>User Management</Title>
          <Text c="dimmed" size="sm">
            Manage user accounts, roles, and permissions
          </Text>
        </div>
        <Button leftSection={<IconPlus size={16} />}>Add User</Button>
      </Group>

      {/* Error Display */}
      {error && (
        <Alert
          icon={<IconAlertCircle size="1rem" />}
          title="Error"
          color="red"
          variant="light"
          onClose={() => setError(null)}
          withCloseButton
        >
          {error}
        </Alert>
      )}

      {/* User Stats */}
      {userStats && (
        <SimpleGrid cols={{ base: 2, sm: 4 }} spacing="lg">
          {statsData.map(stat => (
            <Card key={stat.title} withBorder padding="md" radius="md">
              <Group justify="space-between">
                <div>
                  <Text c="dimmed" size="sm" tt="uppercase" fw={700}>
                    {stat.title}
                  </Text>
                  <Text fw={700} size="xl">
                    {stat.value}
                  </Text>
                </div>
                <ThemeIcon
                  color={stat.color}
                  size={38}
                  radius="md"
                  variant="light"
                >
                  <stat.icon size={22} stroke={1.5} />
                </ThemeIcon>
              </Group>
            </Card>
          ))}
        </SimpleGrid>
      )}

      {/* Filters and Search */}
      <Card withBorder padding="lg" radius="md">
        <Group justify="space-between" mb="md">
          <Text fw={500} size="lg">
            All Users
          </Text>
          <Text size="sm" c="dimmed">
            {pagination.total} users found
          </Text>
        </Group>

        <Group mb="lg">
          <TextInput
            placeholder="Search users..."
            leftSection={<IconSearch size={16} />}
            value={searchTerm}
            onChange={event => setSearchTerm(event.currentTarget.value)}
            style={{ flex: 1 }}
          />
          <Select
            placeholder="Filter by role"
            data={['admin', 'user']}
            value={roleFilter}
            onChange={setRoleFilter}
            clearable
            style={{ width: 150 }}
          />
          <Select
            placeholder="Filter by status"
            data={['Active', 'Inactive', 'Pending']}
            value={statusFilter}
            onChange={setStatusFilter}
            clearable
            style={{ width: 150 }}
          />
        </Group>

        {/* Users Table */}
        {loading ? (
          <Center p="xl">
            <Stack align="center" gap="md">
              <Loader />
              <Text>Loading users...</Text>
            </Stack>
          </Center>
        ) : users.length === 0 ? (
          <Center p="xl">
            <Stack align="center" gap="md">
              <IconUsers size={48} color="gray" />
              <Text size="lg" c="dimmed">No users found</Text>
              <Text size="sm" c="dimmed">
                {searchTerm || roleFilter || statusFilter
                  ? 'Try adjusting your search or filters'
                  : 'No users have been created yet'}
              </Text>
            </Stack>
          </Center>
        ) : (
          <>
            <Table.ScrollContainer minWidth={800}>
              <Table verticalSpacing="sm">
                <Table.Thead>
                  <Table.Tr>
                    <Table.Th>User</Table.Th>
                    <Table.Th>Role</Table.Th>
                    <Table.Th>Status</Table.Th>
                    <Table.Th>Last Login</Table.Th>
                    <Table.Th>Join Date</Table.Th>
                    <Table.Th>Actions</Table.Th>
                  </Table.Tr>
                </Table.Thead>
                <Table.Tbody>{rows}</Table.Tbody>
              </Table>
            </Table.ScrollContainer>

            {/* Pagination */}
            {pagination.pages > 1 && (
              <Group justify="center" mt="lg">
                <Pagination
                  value={currentPage}
                  onChange={setCurrentPage}
                  total={pagination.pages}
                  size="sm"
                />
              </Group>
            )}
          </>
        )}
      </Card>
    </Stack>
  );
}

// app/api/admin/users/route.ts
import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth/next';
import { authOptions } from '../../auth/[...nextauth]/route';
import { getCollection } from '@/lib/db/mongo';
import { ObjectId } from 'mongodb';

interface User {
  _id?: ObjectId;
  email: string;
  name: string;
  role: 'admin' | 'user';
  passwordHash: string;
  createdAt: Date;
  updatedAt: Date;
}

export async function GET(request: NextRequest): Promise<NextResponse> {
  // Check authentication
  const session = await getServerSession(authOptions);

  if (!session || session.user?.role !== 'admin') {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  try {
    const { searchParams } = new URL(request.url);
    const page = parseInt(searchParams.get('page') || '1');
    const limit = parseInt(searchParams.get('limit') || '10');
    const search = searchParams.get('search') || '';
    const roleFilter = searchParams.get('role') || '';

    const collection = await getCollection<User>('users');

    // Build MongoDB query
    const query: any = {};

    // Search filter
    if (search) {
      query.$or = [
        { name: { $regex: search, $options: 'i' } },
        { email: { $regex: search, $options: 'i' } },
      ];
    }

    // Role filter
    if (roleFilter) {
      query.role = roleFilter;
    }

    // Get total count for pagination
    const totalUsers = await collection.countDocuments(query);

    // Get users with pagination
    const users = await collection
      .find(query)
      .sort({ createdAt: -1 })
      .skip((page - 1) * limit)
      .limit(limit)
      .toArray();

    // Transform users for frontend
    const transformedUsers = users.map(user => ({
      id: user._id?.toString() || '',
      name: user.name,
      email: user.email,
      role: user.role,
      status: 'Active', // Simulated status
      lastLogin: 'Recently', // Simulated
      avatar: user.name.split(' ').map(n => n[0]).join('').toUpperCase(),
      joinDate: user.createdAt.toLocaleDateString('en-US', {
        year: 'numeric',
        month: 'short',
        day: 'numeric',
      }),
      createdAt: user.createdAt,
      updatedAt: user.updatedAt,
    }));

    return NextResponse.json({
      users: transformedUsers,
      pagination: {
        page,
        limit,
        total: totalUsers,
        pages: Math.ceil(totalUsers / limit),
        hasNext: page < Math.ceil(totalUsers / limit),
        hasPrev: page > 1,
      },
    });
  } catch (error) {
    console.error('Error fetching users:', error);
    return NextResponse.json(
      { error: 'Failed to fetch users' },
      { status: 500 }
    );
  }
}

export async function POST(request: NextRequest): Promise<NextResponse> {
  // Check authentication
  const session = await getServerSession(authOptions);

  if (!session || session.user?.role !== 'admin') {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  try {
    const userData = await request.json();
    const collection = await getCollection<User>('users');

    // Basic validation
    if (!userData.email || !userData.name || !userData.passwordHash) {
      return NextResponse.json(
        { error: 'Email, name, and password are required' },
        { status: 400 }
      );
    }

    // Check if user already exists
    const existingUser = await collection.findOne({ email: userData.email });
    if (existingUser) {
      return NextResponse.json(
        { error: 'User with this email already exists' },
        { status: 409 }
      );
    }

    // Create new user
    const now = new Date();
    const newUser: User = {
      email: userData.email,
      name: userData.name,
      role: userData.role || 'user',
      passwordHash: userData.passwordHash,
      createdAt: now,
      updatedAt: now,
    };

    const result = await collection.insertOne(newUser);

    return NextResponse.json({
      message: 'User created successfully',
      user: {
        id: result.insertedId.toString(),
        name: newUser.name,
        email: newUser.email,
        role: newUser.role,
        createdAt: newUser.createdAt,
      },
    });
  } catch (error) {
    console.error('Error creating user:', error);
    return NextResponse.json(
      { error: 'Failed to create user' },
      { status: 500 }
    );
  }
}

export async function PUT(request: NextRequest): Promise<NextResponse> {
  // Check authentication
  const session = await getServerSession(authOptions);

  if (!session || session.user?.role !== 'admin') {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  try {
    const { userId, ...updateData } = await request.json();
    const collection = await getCollection<User>('users');

    if (!userId) {
      return NextResponse.json({ error: 'User ID is required' }, { status: 400 });
    }

    // Update user
    const result = await collection.updateOne(
      { _id: new ObjectId(userId) },
      { 
        $set: {
          ...updateData,
          updatedAt: new Date(),
        }
      }
    );

    if (result.matchedCount === 0) {
      return NextResponse.json({ error: 'User not found' }, { status: 404 });
    }

    // Get updated user
    const updatedUser = await collection.findOne({ _id: new ObjectId(userId) });

    return NextResponse.json({
      message: 'User updated successfully',
      user: {
        id: updatedUser?._id?.toString(),
        name: updatedUser?.name,
        email: updatedUser?.email,
        role: updatedUser?.role,
        updatedAt: updatedUser?.updatedAt,
      },
    });
  } catch (error) {
    console.error('Error updating user:', error);
    return NextResponse.json(
      { error: 'Failed to update user' },
      { status: 500 }
    );
  }
}

export async function DELETE(request: NextRequest): Promise<NextResponse> {
  // Check authentication
  const session = await getServerSession(authOptions);

  if (!session || session.user?.role !== 'admin') {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  try {
    const { userId } = await request.json();
    const collection = await getCollection<User>('users');

    if (!userId) {
      return NextResponse.json({ error: 'User ID is required' }, { status: 400 });
    }

    // Delete user
    const result = await collection.deleteOne({ _id: new ObjectId(userId) });

    if (result.deletedCount === 0) {
      return NextResponse.json({ error: 'User not found' }, { status: 404 });
    }

    return NextResponse.json({
      message: 'User deleted successfully',
    });
  } catch (error) {
    console.error('Error deleting user:', error);
    return NextResponse.json(
      { error: 'Failed to delete user' },
      { status: 500 }
    );
  }
}

// app/api/admin/users/stats/route.ts
import { NextRequest, NextResponse } from 'next/server';
import { getServerSession } from 'next-auth/next';
import { authOptions } from '../../../auth/[...nextauth]/route';
import { getCollection } from '@/lib/db/mongo';

interface User {
  _id?: any;
  email: string;
  name: string;
  role: 'admin' | 'user';
  createdAt: Date;
}

export async function GET(request: NextRequest): Promise<NextResponse> {
  // Check authentication
  const session = await getServerSession(authOptions);

  if (!session || session.user?.role !== 'admin') {
    return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
  }

  try {
    const collection = await getCollection<User>('users');

    // Get total users
    const total = await collection.countDocuments();

    // Get admin users
    const admins = await collection.countDocuments({ role: 'admin' });

    // Count recent signups (last 7 days)
    const weekAgo = new Date();
    weekAgo.setDate(weekAgo.getDate() - 7);
    const recentSignups = await collection.countDocuments({
      createdAt: { $gte: weekAgo }
    });

    return NextResponse.json({
      total,
      active: total, // For now, assume all users are active
      admins,
      recentSignups,
    });
  } catch (error) {
    console.error('Error fetching user stats:', error);
    return NextResponse.json(
      { error: 'Failed to fetch user statistics' },
      { status: 500 }
    );
  }
}

